local connections = {}
local function connect(signal, fn)
	local c = signal:Connect(fn)
	table.insert(connections, c)
	return c
end

local remotesFolder
local serverRemote
local statRetrieveRemote
local remotesReady = false
local cachedRemotes = {}

local function rememberRemote(instance)
	if typeof(instance) ~= "Instance" or not instance.Parent then
		return
	end
	if not instance:IsA("RemoteFunction") and not instance:IsA("RemoteEvent") then
		return
	end
	cachedRemotes[instance.Name] = instance
	if instance.Name == "ServerRemote" then
		serverRemote = instance
	elseif instance.Name == "StatRetrieveRemote" then
		statRetrieveRemote = instance
	end
	local parent = instance.Parent
	if parent and parent.Name == "Remotes" and parent.Parent == ReplicatedStorage then
		remotesFolder = parent
	end
end

local function ensureRemotesFolder()
	local folder = remotesFolder
	if folder and folder.Parent then
		return folder
	end
	folder = ReplicatedStorage:FindFirstChild("Remotes")
	if folder then
		remotesFolder = folder
	end
	return folder
end

local function findGameRemote(name, preferredInstance)
	if preferredInstance and preferredInstance.Parent and preferredInstance.Name == name then
		rememberRemote(preferredInstance)
		return preferredInstance
	end
	local cached = cachedRemotes[name]
	if cached and cached.Parent then
		return cached
	end
	local folder = ensureRemotesFolder()
	if folder then
		local direct = folder:FindFirstChild(name)
		if direct and (direct:IsA("RemoteFunction") or direct:IsA("RemoteEvent")) then
			rememberRemote(direct)
			return direct
		end
		for _, desc in ipairs(folder:GetDescendants()) do
			if desc.Name == name and (desc:IsA("RemoteFunction") or desc:IsA("RemoteEvent")) then
				rememberRemote(desc)
				return desc
			end
		end
	end
	local top = ReplicatedStorage:FindFirstChild(name)
	if top and (top:IsA("RemoteFunction") or top:IsA("RemoteEvent")) then
		rememberRemote(top)
		return top
	end
	for _, desc in ipairs(ReplicatedStorage:GetDescendants()) do
		if desc.Name == name and (desc:IsA("RemoteFunction") or desc:IsA("RemoteEvent")) then
			rememberRemote(desc)
			return desc
		end
	end
	return nil
end

local function tryConnectRemotes()
	if remotesReady then
		return ensureRemotesFolder() ~= nil
	end
	local folder = ensureRemotesFolder()
	if not folder then
		return false
	end
	local getRace = findGameRemote("GetRace")
	if not getRace or not getRace:IsA("RemoteFunction") then
		return false
	end
	serverRemote = findGameRemote("ServerRemote")
	statRetrieveRemote = findGameRemote("StatRetrieveRemote")
	for _, remoteName in ipairs({ "GetSpins", "GetData", "SlotRemote", "StatChangeRemote", "GetCurrentSlot" }) do
		findGameRemote(remoteName)
	end
	remotesReady = true
	return true
end

