local function setStatus(text, color)
	statusLabel.Text = text
	statusLabel.TextColor3 = color or colors.Muted
end

local logLines = {}
local logOrder = 0
local LOG_LINE_LIMIT = 300

local function formatProbeValue(value)
	if value == nil then
		return "nil"
	end
	if type(value) == "table" then
		local ok, encoded = pcall(HttpService.JSONEncode, HttpService, value)
		if ok then
			return encoded
		end
		return "<table>"
	end
	return tostring(value)
end

local function getLogText()
	return table.concat(logLines, "\n")
end

local function refreshLogBox()
	logBox.Text = getLogText()
	task.defer(function()
		logBox.CursorPosition = #logBox.Text + 1
	end)
end

local function copyLogToClipboard()
	local text = getLogText()
	if text == "" then
		setStatus("Log is empty.", colors.Warning)
		return
	end
	local copied = false
	if type(setclipboard) == "function" then
		copied = select(1, pcall(setclipboard, text))
	end
	if copied then
		setStatus(string.format("Copied %d lines - paste with Ctrl+V.", #logLines), colors.Success)
		return
	end
	logBox:CaptureFocus()
	setStatus("Clipboard API missing - Ctrl+A in log box, then Ctrl+C.", colors.Warning)
end

local function appendLog(line)
	logOrder += 1
	local text = tostring(line)
	table.insert(logLines, text)
	if #logLines > LOG_LINE_LIMIT then
		table.remove(logLines, 1)
	end
	refreshLogBox()
	pcall(print, text)
end

