function npcSafety.GetProfile(npcType)
	local key = type(npcType) == "string" and npcType ~= "" and npcType or "__default"
	local profile = npcSafety.Profiles[key]
	if type(profile) ~= "table" then
		profile = {}
		for setting, value in pairs(npcSafety.DefaultProfile) do
			profile[setting] = value
		end
		npcSafety.Profiles[key] = profile
	end
	return profile
end

