-- Keep bright accent buttons legible when existing handlers update their colors.
function configStore.StyleButton(button)
	if button:GetAttribute("HubContrastBound") then return end
	button:SetAttribute("HubContrastBound", true)
	local function refresh()
		if button.BackgroundColor3 == colors.Accent and button.TextColor3 ~= colors.Background then
			button.TextColor3 = colors.Background
		end
	end
	connect(button:GetPropertyChangedSignal("BackgroundColor3"), refresh)
	connect(button:GetPropertyChangedSignal("TextColor3"), refresh)
	refresh()
end

local planetData = {}
do
	local modules = ReplicatedStorage:FindFirstChild("Modules")
	local metadata = modules and modules:FindFirstChild("Metadata")
	local planetDataFolder = metadata and metadata:FindFirstChild("PlanetData")
	local planetDataModule = planetDataFolder and planetDataFolder:FindFirstChild("PlanetData")
	if planetDataModule then
		local ok, result = pcall(require, planetDataModule)
		if ok and type(result) == "table" then
			planetData = result
		end
	end
end

local function getCurrentPlanet()
	local world = workspace:FindFirstChild("World")
	local map = world and world:FindFirstChild("Map")
	local currentPlanetFolder = map and map:FindFirstChild("CurrentPlanet")
	local planetValue = currentPlanetFolder and currentPlanetFolder:FindFirstChild("Planet")
	if planetValue and planetValue:IsA("StringValue") and planetValue.Value ~= "" then
		return planetValue.Value
	end

	for planetName, placeId in pairs(planetData) do
		if type(planetName) == "string" and placeId == game.PlaceId then
			return planetName
		end
	end
	return "Unknown"
end

local function isOtherworldLocation(planetName)
	return planetName == "Otherworld" or planetName == "HFIL"
end

