local function makePage(name)
	local usesDedicatedScroll = name == "QoL"
	local properties = {
		Name = name .. "Page",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Visible = false,
	}
	if not usesDedicatedScroll then
		properties.CanvasSize = UDim2.fromOffset(0, 0)
		properties.AutomaticCanvasSize = Enum.AutomaticSize.Y
		properties.ScrollingDirection = Enum.ScrollingDirection.Y
		properties.ScrollBarThickness = 5
		properties.ScrollBarImageColor3 = colors.Accent
		properties.ScrollBarImageTransparency = 0.15
		properties.ElasticBehavior = Enum.ElasticBehavior.WhenScrollable
		properties.VerticalScrollBarInset = Enum.ScrollBarInset.ScrollBar
		properties.Active = true
	end
	local page = create(usesDedicatedScroll and "Frame" or "ScrollingFrame", properties, content)
	pages[name] = page
	return page
end

