function configStore.ESP.GetDistanceAlpha(value)
	local minD = configStore.ESP.MinDistance or 500
	local maxD = configStore.ESP.MaxDistanceCap or 100000
	return math.clamp((value - minD) / (maxD - minD), 0, 1)
end

function configStore.ESP.SetMaxDistance(value)
	if type(value) ~= "number" then
		return false
	end
	local minD = configStore.ESP.MinDistance or 500
	local maxD = configStore.ESP.MaxDistanceCap or 100000
	configStore.ESP.MaxDistance = math.clamp(math.floor(value + 0.5), minD, maxD)
	local alpha = configStore.ESP.GetDistanceAlpha(configStore.ESP.MaxDistance)
	if configStore.ESP.DistanceFill then
		configStore.ESP.DistanceFill.Size = UDim2.fromScale(alpha, 1)
	end
	if configStore.ESP.DistanceKnob then
		configStore.ESP.DistanceKnob.Position = UDim2.fromScale(alpha, 0.5)
	end
	if configStore.ESP.DistanceValueLabel then
		configStore.ESP.DistanceValueLabel.Text = tostring(configStore.ESP.MaxDistance)
	end
	for _, entry in pairs(configStore.ESP.Entries) do
		if entry.Billboard then
			entry.Billboard.MaxDistance = configStore.ESP.MaxDistance
		end
		if entry.BoxBillboard then
			entry.BoxBillboard.MaxDistance = configStore.ESP.MaxDistance
		end
	end
	return true
end

function configStore.NpcESP.GetDistanceAlpha(value)
	local minD = configStore.NpcESP.MinDistance or 500
	local maxD = configStore.NpcESP.MaxDistanceCap or 1000000
	if type(value) ~= "number" or value ~= value or maxD <= minD then return 0 end
	-- Log spacing keeps nearby distances adjustable without losing the far end.
	return math.clamp(math.log(math.clamp(value, minD, maxD) / minD) / math.log(maxD / minD), 0, 1)
end

function configStore.NpcESP.GetDistanceFromAlpha(alpha)
	local minD = configStore.NpcESP.MinDistance or 500
	local maxD = configStore.NpcESP.MaxDistanceCap or 1000000
	return minD * (maxD / minD) ^ math.clamp(alpha, 0, 1)
end

function configStore.NpcESP.SetMaxDistance(value)
	if type(value) ~= "number" or value ~= value or math.abs(value) == math.huge then
		return false
	end
	local minD = configStore.NpcESP.MinDistance or 500
	local maxD = configStore.NpcESP.MaxDistanceCap or 1000000
	configStore.NpcESP.MaxDistance = math.clamp(math.floor(value + 0.5), minD, maxD)
	local alpha = configStore.NpcESP.GetDistanceAlpha(configStore.NpcESP.MaxDistance)
	if configStore.NpcESP.DistanceFill then
		configStore.NpcESP.DistanceFill.Size = UDim2.fromScale(alpha, 1)
	end
	if configStore.NpcESP.DistanceKnob then
		configStore.NpcESP.DistanceKnob.Position = UDim2.fromScale(alpha, 0.5)
	end
	if configStore.NpcESP.DistanceValueLabel then
		configStore.NpcESP.DistanceValueLabel.Text = tostring(configStore.NpcESP.MaxDistance)
	end
	for _, entry in pairs(configStore.NpcESP.Entries) do
		if entry.Billboard then
			entry.Billboard.MaxDistance = configStore.NpcESP.MaxDistance
		end
		if entry.BoxBillboard then
			entry.BoxBillboard.MaxDistance = configStore.NpcESP.MaxDistance
		end
	end
	return true
end

configStore.ESP.SetMaxDistance(configStore.ESP.MaxDistance)
configStore.NpcESP.SetMaxDistance(configStore.NpcESP.MaxDistance)

local function setPlayerEspMaxDistanceFromInputX(inputX)
	local track = configStore.ESP.DistanceTrack
	if not track or track.AbsoluteSize.X <= 0 then
		return
	end
	local alpha = math.clamp((inputX - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1)
	local minD = configStore.ESP.MinDistance or 500
	local maxD = configStore.ESP.MaxDistanceCap or 100000
	configStore.ESP.SetMaxDistance(minD + (maxD - minD) * alpha)
end

local function setNpcEspMaxDistanceFromInputX(inputX)
	local track = configStore.NpcESP.DistanceTrack
	if not track or track.AbsoluteSize.X <= 0 then
		return
	end
	local alpha = math.clamp((inputX - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1)
	configStore.NpcESP.SetMaxDistance(configStore.NpcESP.GetDistanceFromAlpha(alpha))
end

connect(configStore.ESP.DistanceHitbox.InputBegan, function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
		configStore.ESP.DistanceSliderDragging = true
		setPlayerEspMaxDistanceFromInputX(input.Position.X)
	end
end)
connect(configStore.NpcESP.DistanceHitbox.InputBegan, function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
		configStore.NpcESP.DistanceSliderDragging = true
		setNpcEspMaxDistanceFromInputX(input.Position.X)
	end
end)
connect(UserInputService.InputChanged, function(input)
	if configStore.ESP.DistanceSliderDragging
		and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
		setPlayerEspMaxDistanceFromInputX(input.Position.X)
	end
	if configStore.NpcESP.DistanceSliderDragging
		and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
		setNpcEspMaxDistanceFromInputX(input.Position.X)
	end
end)
connect(UserInputService.InputEnded, function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
		configStore.ESP.DistanceSliderDragging = false
		configStore.NpcESP.DistanceSliderDragging = false
	end
end)

function configStore.ESP.GetSpectatePlayers()
	local candidates={}
	for _,player in ipairs(Players:GetPlayers()) do
		if player~=localPlayer then table.insert(candidates,player) end
	end
	table.sort(candidates,function(a,b) return string.lower(a.Name)<string.lower(b.Name) end)
	return candidates
end

function configStore.ESP.RenderSpectate()
	local selected=configStore.ESP.SpectateSelected
	if not selected or selected.Parent~=Players then
		selected=configStore.ESP.GetSpectatePlayers()[1]
		configStore.ESP.SpectateSelected=selected
	end
	configStore.ESP.SpectateLabel.Text=selected
		and ("SPECTATE // "..selected.DisplayName.."  @"..selected.Name)
		or "SPECTATE // NO OTHER PLAYERS"
	local active=configStore.ESP.SpectateTarget~=nil
	configStore.ESP.SpectateButton.Text=active and "STOP SPECTATING" or "SPECTATE"
	configStore.ESP.SpectateButton.BackgroundColor3=active and colors.Danger or colors.Accent
	configStore.ESP.SpectateButton.TextColor3=active and colors.Text or colors.Background
end

function configStore.ESP.StopSpectate()
	configStore.ESP.SpectateTarget=nil
	configStore.ESP.SpectateReturnPending=true
	local camera=workspace.CurrentCamera
	local character=localPlayer.Character
	local humanoid=character and character:FindFirstChildOfClass("Humanoid")
	if camera and humanoid then
		camera.CameraType=Enum.CameraType.Custom
		camera.CameraSubject=humanoid
		configStore.ESP.SpectateReturnPending=false
	end
	configStore.ESP.RenderSpectate()
	return true
end

function configStore.ESP.StartSpectate(player)
	if unloaded then return false end
	player=player or configStore.ESP.SpectateSelected
	if not player or player==localPlayer or player.Parent~=Players then return false end
	local humanoid=player.Character and player.Character:FindFirstChildOfClass("Humanoid")
	if not humanoid or humanoid.Health<=0 then
		configStore.ESP.SpectateLabel.Text="SPECTATE // @"..player.Name.." has no loaded living character"
		warn("[Anomaly's Hub] Cannot spectate @"..player.Name..": character not loaded or alive.")
		return false
	end
	configStore.ESP.SpectateSelected=player
	configStore.ESP.SpectateTarget=player
	configStore.ESP.SpectateReturnPending=false
	local camera=workspace.CurrentCamera
	if camera then
		camera.CameraType=Enum.CameraType.Custom
		camera.CameraSubject=humanoid
	end
	configStore.ESP.RenderSpectate()
	return true
end

function configStore.ESP.CycleSpectate(step)
	local candidates=configStore.ESP.GetSpectatePlayers()
	if #candidates==0 then
		configStore.ESP.SpectateSelected=nil
		configStore.ESP.StopSpectate()
		return nil
	end
	local index=table.find(candidates,configStore.ESP.SpectateSelected) or (step>0 and 0 or 1)
	index=((index-1+step)%#candidates)+1
	configStore.ESP.SpectateSelected=candidates[index]
	if configStore.ESP.SpectateTarget then configStore.ESP.StartSpectate(candidates[index]) else configStore.ESP.RenderSpectate() end
	return candidates[index]
end

function configStore.ESP.UpdateSpectate(deltaTime)
	configStore.ESP.SpectateElapsed+=deltaTime
	if configStore.ESP.SpectateElapsed<0.2 then return end
	configStore.ESP.SpectateElapsed=0
	local target=configStore.ESP.SpectateTarget
	if not target then
		if configStore.ESP.SpectateReturnPending then configStore.ESP.StopSpectate() end
		return
	end
	if target.Parent~=Players then configStore.ESP.StopSpectate();return end
	local humanoid=target.Character and target.Character:FindFirstChildOfClass("Humanoid")
	if not humanoid or humanoid.Health<=0 then configStore.ESP.StopSpectate();return end
	local camera=workspace.CurrentCamera
	if camera then
		camera.CameraType=Enum.CameraType.Custom
		if camera.CameraSubject~=humanoid then camera.CameraSubject=humanoid end
	end
end

-- BEGIN LEADERBOARD SPECTATE
-- Resolve only the clicked leaderboard row, with live identity on every click.
-- No per-frame UI scans, row overlays, remote calls, or changes to the leaderboard.
function configStore.ESP.ToggleLeaderboardSpectate(player)
	if unloaded or not player or player.Parent~=Players then return false end
	if player==localPlayer or player==configStore.ESP.SpectateTarget then
		return configStore.ESP.StopSpectate()
	end
	return configStore.ESP.StartSpectate(player)
end

-- Verified by the in-game click trace: each native row is a TextButton named
-- after its account, under PlayerGui.KamiLeaderboardGui.Panel.List.
function configStore.ESP.GetNativeLeaderboardRow(object)
	local node=object
	for _=1,8 do
		if not node or node==playerGui then break end
		local list=node.Parent
		local panel=list and list.Parent
		local gui=panel and panel.Parent
		if node:IsA("TextButton") and list and list.Name=="List" and list:IsA("ScrollingFrame")
			and panel and panel.Name=="Panel" and gui and gui.Name=="KamiLeaderboardGui"
			and gui:IsA("ScreenGui") and gui.Parent==playerGui then return node end
		node=node.Parent
	end
	return nil
end

function configStore.ESP.BindNativeLeaderboardRow(object)
	if unloaded or configStore.ESP.GetNativeLeaderboardRow(object)~=object then return end
	local bindings=configStore.ESP.NativeLeaderboardBindings
	if bindings[object] then return end
	bindings[object]=object.Activated:Connect(function()
		if unloaded or configStore.ESP.GetNativeLeaderboardRow(object)~=object then return end
		local node=object
		while node and node~=playerGui do
			if node:IsA("GuiObject") and not node.Visible then return end
			if node:IsA("ScreenGui") and not node.Enabled then return end
			node=node.Parent
		end
		for _,player in ipairs(Players:GetPlayers()) do
			if player.Name==object.Name then
				configStore.ESP.ToggleLeaderboardSpectate(player)
				return
			end
		end
	end)
end

function configStore.ESP.StopNativeLeaderboardBindings()
	for row,connection in pairs(configStore.ESP.NativeLeaderboardBindings) do
		connection:Disconnect()
		configStore.ESP.NativeLeaderboardBindings[row]=nil
	end
end

configStore.ESP.NativeLeaderboardBindings={}
connect(playerGui.DescendantAdded,function(object)
	configStore.ESP.BindNativeLeaderboardRow(object)
end)
connect(playerGui.DescendantRemoving,function(object)
	local connection=configStore.ESP.NativeLeaderboardBindings[object]
	if connection then connection:Disconnect();configStore.ESP.NativeLeaderboardBindings[object]=nil end
end)
do
	local gui=playerGui:FindFirstChild("KamiLeaderboardGui")
	local panel=gui and gui:FindFirstChild("Panel")
	local list=panel and panel:FindFirstChild("List")
	if list then
		for _,row in ipairs(list:GetChildren()) do configStore.ESP.BindNativeLeaderboardRow(row) end
	end
end

function configStore.ESP.IsLeaderboardContainer(object)
	local name=string.lower(object.Name):gsub("[%s_%-]", "")
	if name=="leaderboard" or name=="leaderboardgui" or name=="playerlist"
		or name=="playerlistgui" or name=="playerlistmaster" or name=="fighters" then return true end
	-- The recorded game uses a custom FIGHTERS panel, not Roblox's player list.
	-- Identify its visible header without depending on an unobserved instance path.
	if not (object:IsA("Frame") or object:IsA("ScrollingFrame") or object:IsA("ScreenGui")) then return false end
	local checked=0
	local function header(child)
		checked+=1
		return checked<=96 and (child:IsA("TextLabel") or child:IsA("TextButton")) and child.Visible
			and string.match(string.upper(child.Text:gsub("<[^>]*>","")),"^%s*FIGHTERS%s*$")~=nil
	end
	for _,child in ipairs(object:GetChildren()) do
		if checked>=96 then break end
		if header(child) then return true end
		local childName=string.lower(child.Name)
		if child:IsA("GuiObject") and child.Visible and (childName=="header" or childName=="titlebar" or childName=="topbar") then
			for _,nested in ipairs(child:GetChildren()) do
				if checked>=96 then break end
				if header(nested) then return true end
			end
		end
	end
	return false
end

function configStore.ESP.GetLeaderboardCharacterName(player)
	-- Read replicated/cached identity only; a click must never invoke a stats remote.
	local snapshot=player==localPlayer and configStore.ESP.LocalSnapshot
	if snapshot and type(snapshot.Name)=="string" then return snapshot.Name end
	local stats=player:FindFirstChild("PlayerStats")
	local data=stats and stats:FindFirstChild("CharacterData")
	return configStore.ESP.ReadNamedValue(data,{"Name","CharacterName","InGameName"})
		or configStore.ESP.ReadNamedValue(player.Character,{"CharacterName","InGameName"})
		or player:GetAttribute("CharacterName")
end

function configStore.ESP.ResolveLeaderboardPlayer(object)
	if not object or object:IsDescendantOf(screenGui) then return nil end
	local chain={}
	local node=object
	local container=nil
	for _=1,24 do
		if not node then break end
		if node:IsA("GuiObject") and not node.Visible then return nil end
		if node:IsA("ScreenGui") and not node.Enabled then return nil end
		if configStore.ESP.IsLeaderboardContainer(node) then
			container=node;break
		end
		table.insert(chain,node)
		node=node.Parent
	end
	if not container then return nil end
	local candidates=Players:GetPlayers()
	local characterNames={}
	for _,player in ipairs(candidates) do characterNames[player]=configStore.ESP.GetLeaderboardCharacterName(player) end
	-- Stable row IDs take precedence over display names (which need not be unique).
	local identified=nil
	for _,entry in ipairs(chain) do
		local id=tonumber(entry:GetAttribute("UserId") or entry:GetAttribute("PlayerUserId")
			or string.match(entry.Name,"^PlayerEntry[_%-](%d+)$"))
		for _,player in ipairs(candidates) do
			if (id and player.UserId==id) or entry.Name==player.Name then
				if identified and identified~=player then return nil end
				identified=player
			end
		end
	end
	local function textPlayer(label)
		if not (label:IsA("TextLabel") or label:IsA("TextButton")) then return nil end
		local value=string.match(label.Text:gsub("<[^>]*>",""),"^%s*(.-)%s*$")
		local username=string.match(value,"^@([%w_]+)$")
		if identified then
			if value==identified.Name or value==identified.DisplayName or value==characterNames[identified]
				or username==identified.Name then return identified end
			return nil
		end
		local matched=nil
		for _,player in ipairs(candidates) do
			local match=username and username==player.Name
				or not username and (value==player.Name or value==player.DisplayName or value==characterNames[player])
			if match then
				if matched and matched~=player then return nil end
				matched=player
			end
		end
		return matched
	end
	-- Clicking a stat, icon, menu item, or blank area is not a name click.
	local player=textPlayer(object)
	-- This game's hovered row expands with a separate username line. Resolve
	-- that exact username inside the name's immediate row, not just the clicked
	-- character-name label. Never search the whole roster or hidden tooltips.
	if (object:IsA("TextLabel") or object:IsA("TextButton")) and object.Text:find("%a") then
		local row=object.Parent
		if row==container then row=object end
		if row and row~=container and not row:IsA("ScrollingFrame") and row:IsA("GuiObject") then
			local found=nil
			local count=0
			for _,label in ipairs(row:GetDescendants()) do
				count+=1;if count>64 then break end
				if not (label:IsA("TextLabel") or label:IsA("TextButton")) then continue end
				local visible=true
				local ancestor=label
				while ancestor and ancestor~=row do
					if ancestor:IsA("GuiObject") and not ancestor.Visible then visible=false;break end
					ancestor=ancestor.Parent
				end
				if not visible then continue end
				local value=label.Text:gsub("<[^>]*>",""):match("^%s*@?([%w_]+)%s*$")
				if value then
					for _,candidate in ipairs(candidates) do
						if value:lower()==candidate.Name:lower() then
							if (identified and identified~=candidate) or (found and found~=candidate) then return nil end
							found=candidate
						end
					end
				end
			end
			if found then return found end
		end
	end
	if player then return player end
	if object:IsA("TextLabel") or (object:IsA("TextButton") and object.Text~="") then return nil end
	-- Some leaderboards put a transparent button directly over the name label.
	if object:IsA("GuiButton") or (identified and object:IsA("Frame")) then
		local count=0
		for _,child in ipairs(object:GetDescendants()) do
			count+=1;if count>64 then break end
			if child:IsA("GuiObject") and child.Visible then
				local found=textPlayer(child)
				if found then
					if player and player~=found then return nil end
					player=found
				end
			end
		end
	end
	return player
end

function configStore.ESP.LeaderboardPlayerAt(position)
	-- CoreGui is optional: inaccessible built-in UI must not break custom PlayerGui UI.
	local roots={}
	local ok,core=pcall(game.GetService,game,"CoreGui")
	if ok and core then table.insert(roots,core) end
	table.insert(roots,playerGui)
	for _,root in ipairs(roots) do
		local readable,hits=pcall(function() return root:GetGuiObjectsAtPosition(position.X,position.Y) end)
		if readable and hits and hits[1] then
			for index=1,math.min(#hits,24) do
				local top=hits[index]
				-- Native buttons own their Activated event; the generic fallback must
				-- never toggle the same click a second time.
				if configStore.ESP.GetNativeLeaderboardRow(top) then return nil end
				-- A Frame can precede its clicked name child. Stay inside that
				-- topmost subtree, never search through an unrelated overlay.
				if index>1 and not top:IsDescendantOf(hits[1]) then break end
				local resolved,player=pcall(configStore.ESP.ResolveLeaderboardPlayer,top)
				if resolved and player then return player,top end
				if top:IsA("GuiButton") or top:IsA("TextLabel") or top:IsA("TextBox")
					or top:IsDescendantOf(screenGui) then
					-- Retain only leaderboard text/buttons for a post-click identity check.
					local node=top
					if not top:IsDescendantOf(screenGui) and not top:IsA("TextBox") then
						for _=1,24 do
							if not node then break end
							if configStore.ESP.IsLeaderboardContainer(node) then return nil,top end
							node=node.Parent
						end
					end
					return nil
				end
			end
		end
	end
	return nil
end

connect(UserInputService.InputBegan,function(input)
	if unloaded or configStore.ESP.LeaderboardPress or UserInputService:GetFocusedTextBox() then return end
	if input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch then return end
	-- GUI clicks are processed input, so do not reject gameProcessedEvent here.
	configStore.ESP.LeaderboardClickSerial=(configStore.ESP.LeaderboardClickSerial or 0)+1
	local player,object=configStore.ESP.LeaderboardPlayerAt(input.Position)
	if player or object then configStore.ESP.LeaderboardPress={Input=input,Player=player,Object=object,Position=input.Position,
		Serial=configStore.ESP.LeaderboardClickSerial} end
end)
connect(UserInputService.InputChanged,function(input)
	local press=configStore.ESP.LeaderboardPress
	if not press then return end
	if input==press.Input or (press.Input.UserInputType==Enum.UserInputType.MouseButton1
		and input.UserInputType==Enum.UserInputType.MouseMovement) then
		if (input.Position-press.Position).Magnitude>10 then press.Dragged=true end
	end
end)
connect(UserInputService.InputEnded,function(input)
	local press=configStore.ESP.LeaderboardPress
	if not press then return end
	local mouseRelease=input.UserInputType==Enum.UserInputType.MouseButton1
		and press.Input.UserInputType==Enum.UserInputType.MouseButton1
	if input~=press.Input and not mouseRelease then return end
	configStore.ESP.LeaderboardPress=nil
	if unloaded or press.Dragged or (input.Position-press.Position).Magnitude>10 then return end
	if press.Player then configStore.ESP.ToggleLeaderboardSpectate(press.Player);return end
	-- Activated may reveal @username only after InputEnded. Inspect that same
	-- clicked object next scheduler cycle, never an arbitrary new object under the mouse.
	task.defer(function()
		if unloaded or configStore.ESP.LeaderboardClickSerial~=press.Serial then return end
		local ok,player=pcall(configStore.ESP.ResolveLeaderboardPlayer,press.Object)
		if ok and player then configStore.ESP.ToggleLeaderboardSpectate(player)
		else
			configStore.ESP.SpectateLabel.Text="SPECTATE // could not identify clicked player"
			warn("[Anomaly's Hub] Spectate: leaderboard name could not be matched to a player.")
		end
	end)
end)
connect(UserInputService.WindowFocusReleased,function()
	configStore.ESP.LeaderboardPress=nil
	configStore.ESP.LeaderboardClickSerial=(configStore.ESP.LeaderboardClickSerial or 0)+1
end)
-- END LEADERBOARD SPECTATE

function configStore.ESP.ReadNamedValue(root, names)
	if not root then return nil end
	for _, name in ipairs(names) do
		local object = root:FindFirstChild(name, true)
		if object and object:IsA("ValueBase") then return object.Value end
		local attribute = root:GetAttribute(name)
		if attribute ~= nil then return attribute end
	end
	return nil
end

function configStore.ESP.GetLocalSnapshot()
	local cached=configStore.ESP.LocalSnapshot or {}
	if (configStore.ESP.LocalSnapshot and os.clock()-configStore.ESP.LocalSnapshotAt<1) or configStore.ESP.LocalSnapshotInFlight then
		return cached
	end
	-- InvokeServer yields; fetch off the Heartbeat thread and serve the cached copy meanwhile.
	configStore.ESP.LocalSnapshotInFlight=true
	task.spawn(function()
		pcall(configStore.ESP.FetchLocalSnapshot)
		configStore.ESP.LocalSnapshotInFlight=false
	end)
	return cached
end

function configStore.ESP.FetchLocalSnapshot()
	local snapshot={}
	local okCharacter,characterData=pcall(statRetrieveRemote.InvokeServer,statRetrieveRemote,"CharacterData","TableStat")
	if okCharacter and type(characterData)=="table" then
		snapshot.Name=characterData.Name
		snapshot.Race=type(characterData.Race)=="table" and characterData.Race.Race or characterData.Race
	end
	local okStats,statData=pcall(statRetrieveRemote.InvokeServer,statRetrieveRemote,"StatData","TableStat")
	if okStats and type(statData)=="table" and type(statData.CharacterStats)=="table" then
		snapshot.Ki=statData.CharacterStats.Ki
		snapshot.MaxKi=statData.CharacterStats.MaxKi
	end
	configStore.ESP.LocalSnapshot=snapshot
	configStore.ESP.LocalSnapshotAt=os.clock()
	return snapshot
end

function configStore.ESP.GetRace(player)
	if player==localPlayer then
		local snapshot=configStore.ESP.GetLocalSnapshot()
		if snapshot.Race then return tostring(snapshot.Race) end
	end
	return tostring(configStore.ESP.ReadNamedValue(player:FindFirstChild("PlayerStats"), {"Race"})
		or configStore.ESP.ReadNamedValue(player.Character, {"Race"}) or player:GetAttribute("Race") or "Unknown")
end

function configStore.ESP.GetInGameName(player)
	if player==localPlayer then
		local snapshot=configStore.ESP.GetLocalSnapshot()
		if snapshot.Name then return tostring(snapshot.Name) end
	end
	local stats = player:FindFirstChild("PlayerStats")
	local characterData = stats and stats:FindFirstChild("CharacterData")
	return tostring(configStore.ESP.ReadNamedValue(characterData, {"Name","CharacterName","InGameName"})
		or configStore.ESP.ReadNamedValue(player.Character, {"CharacterName","InGameName"})
		or player:GetAttribute("CharacterName") or player.DisplayName)
end

function configStore.ESP.GetKi(player)
	if player==localPlayer then
		local snapshot=configStore.ESP.GetLocalSnapshot()
		if tonumber(snapshot.Ki) and tonumber(snapshot.MaxKi) then return tonumber(snapshot.Ki),tonumber(snapshot.MaxKi) end
	end
	local current = tonumber(configStore.ESP.ReadNamedValue(player.Character, {"Ki","CurrentKi"})
		or configStore.ESP.ReadNamedValue(player:FindFirstChild("PlayerStats"), {"Ki","CurrentKi"}))
	local maximum = tonumber(configStore.ESP.ReadNamedValue(player.Character, {"MaxKi","MaximumKi"})
		or configStore.ESP.ReadNamedValue(player:FindFirstChild("PlayerStats"), {"MaxKi","MaximumKi"}))
	return current, maximum
end

function configStore.ESP.GetPowerLevel(player)
	return tonumber(configStore.ESP.ReadNamedValue(player:FindFirstChild("PlayerStats"), {"PowerLevel"})
		or configStore.ESP.ReadNamedValue(player.Character, {"PowerLevel"})
		or player:GetAttribute("PowerLevel"))
end

function configStore.ESP.FormatInteger(value)
	local formatted=tostring(math.floor((tonumber(value) or 0)+0.5))
	repeat
		local replaced
		formatted,replaced=string.gsub(formatted,"^(-?%d+)(%d%d%d)","%1,%2")
	until replaced==0
	return formatted
end

function configStore.ESP.GetVisualMetrics(character, root)
	local camera=workspace.CurrentCamera
	local centerOffset=Vector3.zero
	if not camera then return 76,132,1,centerOffset,Vector3.new(0,4.2,0) end
	local rootPoint=camera:WorldToViewportPoint(root.Position)
	if rootPoint.Z<=0 then return 12,20,0.15,centerOffset,Vector3.new(0,4.2,0) end
	local halfWidth,halfHeight=0,0
	local highestPoint=2.8
	local bodyPartCount=0
	for _,part in ipairs(character:GetChildren()) do
		if part:IsA("BasePart") and part~=root and part.Transparency<0.98 then
			bodyPartCount+=1
			local half=part.Size*0.5
			for _,x in ipairs({-1,1}) do
				for _,y in ipairs({-1,1}) do
					for _,z in ipairs({-1,1}) do
						local worldPoint=part.CFrame:PointToWorldSpace(Vector3.new(half.X*x,half.Y*y,half.Z*z))
						local viewportPoint=camera:WorldToViewportPoint(worldPoint)
						if viewportPoint.Z>0 then
							halfWidth=math.max(halfWidth,math.abs(viewportPoint.X-rootPoint.X))
							halfHeight=math.max(halfHeight,math.abs(viewportPoint.Y-rootPoint.Y))
						end
						highestPoint=math.max(highestPoint,worldPoint.Y-root.Position.Y)
					end
				end
			end
		end
	end
	if bodyPartCount==0 then return 76,132,1,centerOffset,Vector3.new(0,4.2,0) end
	local boxWidth=math.clamp(halfWidth*2+4,28,76*1.5)
	local boxHeight=math.clamp(halfHeight*2+4,132*0.15,132*1.15)
	return boxWidth,boxHeight,1,centerOffset,Vector3.new(0,highestPoint+0.8,0)
end

function configStore.ESP.CreateEntry(player)
	if player == localPlayer and not configStore.ESP.Settings.Self then return nil end
	if configStore.ESP.Entries[player] then return configStore.ESP.Entries[player] end
	local entry = {}
	entry.Billboard = create("BillboardGui", {
		Name="GohanPlayerESP", Size=UDim2.fromOffset(240,88), StudsOffsetWorldSpace=Vector3.new(0,4.2,0),
		AlwaysOnTop=true, LightInfluence=0, MaxDistance=configStore.ESP.MaxDistance or 100000, Enabled=false,
	}, screenGui)
	entry.Panel = create("Frame", {AnchorPoint=Vector2.new(0.5,0.5),Position=UDim2.fromScale(0.5,0.5),Size=UDim2.fromOffset(240,88),BackgroundTransparency=1}, entry.Billboard)
	entry.InfoScale=create("UIScale",{Scale=1},entry.Panel)
	local function label(name, y, color, size)
		return create("TextLabel", {
			Name=name, Position=UDim2.fromOffset(0,y), Size=UDim2.new(1,0,0,15), BackgroundTransparency=1,
			Font=Enum.Font.GothamSemibold, Text="", TextColor3=color, TextSize=size or 11,
			TextStrokeColor3=Color3.new(0,0,0), TextStrokeTransparency=0.15,
		}, entry.Panel)
	end
	entry.Username = label("Username",0,Color3.fromRGB(255,255,255),12)
	entry.InGameName = label("InGameName",16,colors.Accent,11)
	entry.Race = label("Race",32,Color3.fromRGB(180,220,255),10)
	entry.PowerLevel = label("PowerLevel",48,Color3.fromRGB(255,214,72),10)
	entry.Distance = label("Distance",64,Color3.fromRGB(225,225,225),10)
