function qolState.SetNoclipEnabled(enabled)
	if type(enabled) ~= "boolean" then
		return false
	end

	qolState.NoclipEnabled = enabled
	qolState.NoclipButton.Text = enabled and "Noclip: ON" or "Noclip: OFF"
	qolState.NoclipButton.BackgroundColor3 = enabled and colors.Accent or colors.Surface
	qolState.NoclipButton.TextColor3 = enabled and colors.Text or colors.Muted

	local character = localPlayer.Character
	if enabled then
		if character then
			for _, descendant in ipairs(character:GetDescendants()) do
				if descendant:IsA("BasePart") then
					if npcCollisionStates[descendant] == nil then
						npcCollisionStates[descendant] = descendant.CanCollide
					end
					descendant.CanCollide = false
				end
			end
		end
	else
		for part, previousCanCollide in pairs(npcCollisionStates) do
			if part and part.Parent then
				pcall(function()
					part.CanCollide = previousCanCollide
				end)
			end
		end
		npcCollisionStates = {}
	end
	return true
end

