end)

function qolState.ResetCharacter()
	local character = localPlayer.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	if not character or not humanoid or humanoid.Health <= 0 or qolState.ResetCharacterPending == character then
		return false
	end
	qolState.ResetCharacterPending = character
	task.spawn(function()
		local nextCharacter = localPlayer.CharacterAdded:Wait()
		if nextCharacter ~= character and qolState.ResetCharacterPending == character then
			qolState.ResetCharacterPending = nil
		end
	end)
	task.delay(8, function()
		if qolState.ResetCharacterPending == character then
			qolState.ResetCharacterPending = nil
		end
	end)
	local resetEvent = remotes:FindFirstChild("ResetEvent")
	if resetEvent and resetEvent:IsA("RemoteEvent") then
		local ok = pcall(resetEvent.FireServer, resetEvent, character)
		if ok then return true end
	end
	pcall(humanoid.ChangeState, humanoid, Enum.HumanoidStateType.Dead)
	pcall(character.BreakJoints, character)
	humanoid.Health = 0
	return true
end

connect(qolState.ResetButton.Activated, qolState.ResetCharacter)

