function configStore.Session.Save()
	local session = configStore.Session
	local encodedOk, body = pcall(HttpService.JSONEncode, HttpService, {
		StartedAt = session.StartedAt,
		SavedAt = os.time(),
		JobId = game.JobId,
		StartLevel = session.StartLevel,
		CurrentLevel = session.CurrentLevel,
		Counters = session.Counters,
	})
	local writefile = configStore.GetFunction("writefile")
	if encodedOk and writefile then
		pcall(configStore.EnsureFolders)
		pcall(writefile, session.File, body)
	end
end

function configStore.Session.Load()
	local session = configStore.Session
	local isfile = configStore.GetFunction("isfile")
	local readfile = configStore.GetFunction("readfile")
	if not isfile or not readfile then
		return false
	end
	local existsOk, exists = pcall(isfile, session.File)
	if not existsOk or not exists then
		return false
	end
	local readOk, body = pcall(readfile, session.File)
	local decodedOk, data = false, nil
	if readOk and type(body) == "string" then
		decodedOk, data = pcall(HttpService.JSONDecode, HttpService, body)
	end
	if not decodedOk or type(data) ~= "table" or type(data.SavedAt) ~= "number"
		or os.time() - data.SavedAt > session.ResumeWindow then
		return false
	end
	session.StartedAt = tonumber(data.StartedAt) or session.StartedAt
	session.StartLevel = tonumber(data.StartLevel)
	session.CurrentLevel = tonumber(data.CurrentLevel)
	if type(data.Counters) == "table" then
		for key in pairs(session.Counters) do
			session.Counters[key] = tonumber(data.Counters[key]) or 0
		end
	end
	if type(data.JobId) == "string" and data.JobId ~= game.JobId then
		session.Counters.Hops += 1
	end
	return true
end

function configStore.Session.Reset()
	local session = configStore.Session
	session.StartedAt = os.time()
	for key in pairs(session.Counters) do
		session.Counters[key] = 0
	end
	session.StartLevel = session.CurrentLevel
	session.Save()
	session.Render()
end

-- Dedupe with a client-local attribute: a weak table keyed by the model can
-- drop the entry while the NPC still exists, double-counting the same kill.
function configStore.Session.RecordKill(model)
	local session = configStore.Session
	if not model or not model.Parent or model:GetAttribute("AnomalyKillCounted") then
		return
	end
	model:SetAttribute("AnomalyKillCounted", true)
	session.Counters.Kills += 1
end

-- Also counts NPCs that die outright (never knocked) while being farmed.
function configStore.Session.StopWatchingTarget()
	local session = configStore.Session
	if session.WatchedConnection then
		session.WatchedConnection:Disconnect()
		session.WatchedConnection = nil
	end
	session.WatchedTarget = nil
end

function configStore.Session.WatchTarget()
	local session = configStore.Session
	local target = npcTargetingEnabled and activeNpcTarget or nil
	if session.WatchedTarget == target then
		return
	end
	session.StopWatchingTarget()
	session.WatchedTarget = target
	local humanoid = target and target:FindFirstChildOfClass("Humanoid")
	if humanoid then
		session.WatchedConnection = humanoid.HealthChanged:Connect(function(health)
			if health <= 0 then
				session.RecordKill(target)
			end
		end)
	end
end

function configStore.Session.RecordChest(receipt)
	if not receipt or receipt.Counted then return false end
	receipt.Counted = true
	local prompt = receipt.Prompt
	if prompt then
		if prompt:GetAttribute("AnomalyChestCounted") then return false end
		prompt:SetAttribute("AnomalyChestCounted", true)
	end
	configStore.Session.Counters.Chests += 1
	return true
end

function configStore.Session.OnLevel(level)
	local session = configStore.Session
	session.CurrentLevel = level
	if not session.StartLevel then
		session.StartLevel = level
	end
end

function configStore.Session.HookZeni()
	local session = configStore.Session
	if session.ZeniValue and session.ZeniValue.Parent then
		return
	end
	local playerStats = localPlayer:FindFirstChild("PlayerStats")
	local zeni = playerStats and playerStats:FindFirstChild("Zeni", true)
	if not zeni or not zeni:IsA("ValueBase") then
		return
	end
	session.ZeniValue = zeni
	session.LastZeni = tonumber(zeni.Value)
	connect(zeni:GetPropertyChangedSignal("Value"), function()
		local current = tonumber(zeni.Value)
		if current and session.LastZeni and current > session.LastZeni then
			session.Counters.ZeniEarned += current - session.LastZeni
		end
		session.LastZeni = current
	end)
end

function configStore.Session.HookCharacter(character)
	task.spawn(function()
		local humanoid = character and character:WaitForChild("Humanoid", 10)
		if not humanoid or unloaded then
			return
		end
		connect(humanoid.Died, function()
			configStore.Session.Counters.Deaths += 1
		end)
	end)
end

function configStore.Session.FormatDuration(seconds)
	seconds = math.max(0, math.floor(seconds))
	local hours = math.floor(seconds / 3600)
	local minutes = math.floor((seconds % 3600) / 60)
	if hours > 0 then
		return string.format("%dh %02dm", hours, minutes)
	end
	return string.format("%dm %02ds", minutes, seconds % 60)
end

function configStore.Session.Render()
	local session = configStore.Session
	local labels = session.Labels
	local elapsed = os.time() - session.StartedAt
	local hours = elapsed / 3600
	local function perHour(count)
		if elapsed < 60 then
			return "--"
		end
		return string.format("%.1f", count / hours)
	end
	local levelsGained = session.StartLevel and session.CurrentLevel and (session.CurrentLevel - session.StartLevel) or 0
	labels.Time.Text = session.FormatDuration(elapsed)
	labels.Level.Text = session.CurrentLevel
		and string.format("%d  (+%d)", session.CurrentLevel, levelsGained)
		or "Not detected"
	labels.LevelRate.Text = session.CurrentLevel and perHour(levelsGained) or "--"
	labels.Kills.Text = string.format("%d  (%s/h)", session.Counters.Kills, perHour(session.Counters.Kills))
	labels.Zeni.Text = string.format("%s  (%s/h)", configStore.ESP.FormatInteger(session.Counters.ZeniEarned),
		elapsed < 60 and "--" or configStore.ESP.FormatInteger(session.Counters.ZeniEarned / hours))
	labels.Chests.Text = tostring(session.Counters.Chests)
	labels.Hops.Text = tostring(session.Counters.Hops)
	labels.Deaths.Text = tostring(session.Counters.Deaths)
end

function configStore.Session.Update(deltaTime)
	local session = configStore.Session
	session.WatchTarget()
	session.UpdateElapsed += deltaTime
	session.SaveElapsed += deltaTime
	if session.UpdateElapsed >= 1 then
		session.UpdateElapsed = 0
		session.HookZeni()
		if homePage.Visible then
			session.Render()
		end
	end
	if session.SaveElapsed >= 15 then
		session.SaveElapsed = 0
		session.Save()
	end
end

