function configStore.NearbyAlert.FindNearest(range)
	local character = localPlayer.Character
	local localRoot = character and character:FindFirstChild("HumanoidRootPart")
	if not localRoot then
		return nil, nil, 0
	end
	local nearest, nearestDistance, count = nil, math.huge, 0
	for _, player in ipairs(Players:GetPlayers()) do
		if player ~= localPlayer then
			local other = player.Character
			local root = other and other:FindFirstChild("HumanoidRootPart")
			local humanoid = other and other:FindFirstChildOfClass("Humanoid")
			if root and (not humanoid or humanoid.Health > 0) then
				local distance = (root.Position - localRoot.Position).Magnitude
				if distance <= range then
					count += 1
					if distance < nearestDistance then
						nearest, nearestDistance = player, distance
					end
				end
			end
		end
	end
	return nearest, nearest and nearestDistance or nil, count
end

function configStore.NearbyAlert.Update(deltaTime)
	local state = configStore.NearbyAlert
	state.UpdateElapsed += deltaTime
	if state.UpdateElapsed < 0.25 then
		return
	end
	state.UpdateElapsed = 0
	if not state.Enabled then
		state.Banner.Visible = false
		return
	end
	local nearest, distance, count = state.FindNearest(state.Range)
	if not nearest then
		state.Banner.Visible = false
		return
	end
	local color = distance < 500 and Color3.fromRGB(239, 68, 68)
		or distance < 1000 and Color3.fromRGB(249, 146, 60)
		or Color3.fromRGB(234, 200, 70)
	state.Stroke.Color = color
	state.TitleLabel.TextColor3 = color
	state.TitleLabel.Text = count > 1
		and string.format("NEARBY PLAYERS: %d WITHIN %s STUDS", count, configStore.ESP.FormatInteger(state.Range))
		or string.format("NEARBY PLAYER WITHIN %s STUDS", configStore.ESP.FormatInteger(state.Range))
	state.DetailLabel.Text = string.format("%s (@%s)  —  %.0f studs", nearest.DisplayName, nearest.Name, distance)
	state.Banner.Visible = true
end

function configStore.NearbyAlert.SetEnabled(enabled)
	configStore.NearbyAlert.Enabled = enabled == true
	if not configStore.NearbyAlert.Enabled then
		configStore.NearbyAlert.Banner.Visible = false
	end
	return configStore.NearbyAlert.Enabled
end

connect(RunService.Heartbeat, configStore.NearbyAlert.Update)

