local cachedFlyHandler
local flightSliderDragging = false

local function getFunctionUpvalues(callback)
	if type(getupvalues) == "function" then
		local ok, values = pcall(getupvalues, callback)
		if ok and type(values) == "table" then
			return values
		end
	end
	if debug and type(debug.getupvalues) == "function" then
		local ok, values = pcall(debug.getupvalues, callback)
		if ok and type(values) == "table" then
			return values
		end
	end
	return nil
end

local function getActiveFlightSession()
	if not cachedFlyHandler then
		local playerScripts = localPlayer:FindFirstChild("PlayerScripts")
		local client = playerScripts and playerScripts:FindFirstChild("Client")
		local core = client and client:FindFirstChild("Core")
		local handlerFolder = core and core:FindFirstChild("Handler")
		local moduleScript = handlerFolder and handlerFolder:FindFirstChild("FlyHandler")
		if not moduleScript then
			return nil
		end
		local ok, result = pcall(require, moduleScript)
		if not ok or type(result) ~= "table" then
			return nil
		end
		cachedFlyHandler = result
	end

	local move = cachedFlyHandler.Move
	local terminate = type(move) == "table" and move.Terminate
	if type(terminate) ~= "function" then
		return nil
	end
	local upvalues = getFunctionUpvalues(terminate)
	local session = upvalues and upvalues[1]
	if type(session) == "table" and session.active and session.character == localPlayer.Character then
		return session
	end
	return nil
end

local function updateFlightSpeedVisual()
	local alpha = (flightSpeed - flightSpeedMin) / (flightSpeedMax - flightSpeedMin)
	flightSpeedFill.Size = UDim2.fromScale(alpha, 1)
	flightSpeedKnob.Position = UDim2.fromScale(alpha, 0.5)
	flightSpeedValueLabel.Text = tostring(flightSpeed)
end

local function applyFlightSpeed()
	local session = getActiveFlightSession()
	if not session then
		controller.FlightWasBoosting = false
		return false
	end
	if session.boosting == true then
		-- FlyHandler's native session starts at speed=40/currentSpeed=15.
		-- Only speed is the boosted target; currentSpeed also drives slow flight.
		session.speed = flightSpeed
		controller.FlightWasBoosting = true
		return true
	end
	-- Repair sessions affected by older versions and preserve native slow flight.
	if controller.FlightWasBoosting or tonumber(session.currentSpeed) and session.currentSpeed > 15 then
		session.currentSpeed = 15
	end
	controller.FlightWasBoosting = false
	return false
end

local function setFlightSpeed(value)
	if type(value) ~= "number" then
		return false
	end
	flightSpeed = math.clamp(math.floor(value + 0.5), flightSpeedMin, flightSpeedMax)
	updateFlightSpeedVisual()
	applyFlightSpeed()
	return true
end

local function setFlightSpeedFromInputX(inputX)
	local width = flightSpeedTrack.AbsoluteSize.X
	if width <= 0 then
		return
	end
	local alpha = math.clamp((inputX - flightSpeedTrack.AbsolutePosition.X) / width, 0, 1)
	setFlightSpeed(flightSpeedMin + (flightSpeedMax - flightSpeedMin) * alpha)
end

updateFlightSpeedVisual()

connect(flightSpeedHitbox.InputBegan, function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
		flightSliderDragging = true
		setFlightSpeedFromInputX(input.Position.X)
	end
end)

connect(UserInputService.InputChanged, function(input)
	if not flightSliderDragging then
		return
	end
	if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
		setFlightSpeedFromInputX(input.Position.X)
	end
end)

connect(UserInputService.InputEnded, function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
		flightSliderDragging = false
	end
end)

connect(RunService.Heartbeat, function(deltaTime)
	flightSyncElapsed += deltaTime
	if flightSyncElapsed >= 0.05 then
		flightSyncElapsed = 0
		applyFlightSpeed()
	end
end)

local function setNpcStatus(text, color)
	if npcStatusLabel.Text ~= text then
		npcStatusLabel.Text = text
	end
	npcStatusLabel.TextColor3 = color or colors.Muted
end

function npcSafety.FindSellItemsShopNpc()
	local world = workspace:FindFirstChild("World")
	local npcs = world and world:FindFirstChild("NPC")
	if not npcs then return nil end
	-- Bulma is under NPC.Tech on the live map, not NPC.Shop. Prefer her exact
	-- model and retain Dende as a fallback for maps that do not spawn Bulma.
	local fallback = nil
	for _, descendant in ipairs(npcs:GetDescendants()) do
		if descendant:IsA("Model") then
			if descendant.Name == "Bulma" then return descendant end
			if descendant.Name == "Dende" then fallback = descendant end
		end
	end
	return fallback
end

function npcSafety.FindSellItemsCommandModule()
	local dialogue = playerGui:FindFirstChild("Dialogue")
	local masterDialogue = dialogue and dialogue:FindFirstChild("MasterDialogue")
	local shopDialogue = masterDialogue and masterDialogue:FindFirstChild("Shop")
	local bulmaDialogue = shopDialogue and shopDialogue:FindFirstChild("Bulma")
	if not masterDialogue then return nil end
	local function findCommand(root)
		if not root then return nil end
		for _, descendant in ipairs(root:GetDescendants()) do
			if descendant:IsA("Configuration") and descendant.Name == "Sell Items"
				and descendant:GetAttribute("Type") == "Command" then
				local moduleScript = descendant:FindFirstChildWhichIsA("ModuleScript", true)
				if moduleScript then return moduleScript end
			end
		end
		return nil
	end
	return findCommand(bulmaDialogue) or findCommand(masterDialogue)
end

function npcSafety.SellItemsToShop()
	if npcSafety.SellItemsBusy then
		return false
	end
	local shopNpc = npcSafety.FindSellItemsShopNpc()
	if not shopNpc then
		setNpcStatus("No item-selling shop NPC is loaded on this planet.", colors.DangerHover)
		return false
	end
	local commandModule = npcSafety.FindSellItemsCommandModule()
	if not commandModule then
		setNpcStatus("The game's Sell Items command is unavailable.", colors.DangerHover)
		return false
	end

	npcSafety.SellItemsBusy = true
	npcSafety.SellItemsRequestSerial += 1
	local serial = npcSafety.SellItemsRequestSerial
	npcSafety.SellItemsButton.Text = "Selling..."
	npcSafety.SellItemsButton.BackgroundColor3 = colors.AccentSoft
	local requireOk, command = pcall(require, commandModule)
	local requestOk, requestError = false, nil
	if requireOk and type(command) == "table" and type(command.Run) == "function" then
		requestOk, requestError = pcall(command.Run, localPlayer)
	else
		requestError = requireOk and "Sell command has no Run function." or command
	end
	if requestOk then
		setNpcStatus("Sell request sent to " .. shopNpc.Name .. "; the server will sell eligible items.", colors.Success)
	else
		setNpcStatus("Sell request failed: " .. tostring(requestError), colors.DangerHover)
	end
	schedule(1.5, function()
		if serial ~= npcSafety.SellItemsRequestSerial then
			return
		end
		npcSafety.SellItemsBusy = false
		if npcSafety.SellItemsButton and npcSafety.SellItemsButton.Parent then
			npcSafety.SellItemsButton.Text = "Sell Items"
			npcSafety.SellItemsButton.BackgroundColor3 = colors.Accent
		end
	end)
	return requestOk
end

connect(npcSafety.SellItemsButton.Activated, npcSafety.SellItemsToShop)

local function getLiveFolder()
	local world = workspace:FindFirstChild("World")
	return world and world:FindFirstChild("Live")
end

local function getNpcRoot(model)
	if not model or not model:IsA("Model") then
		return nil
	end
	local namedRoot = model:FindFirstChild("HumanoidRootPart")
	if namedRoot and namedRoot:IsA("BasePart") then
		return namedRoot
	end
	if model.PrimaryPart and model.PrimaryPart:IsA("BasePart") then
		return model.PrimaryPart
	end
	for _, partName in ipairs({"LowerTorso", "Torso", "UpperTorso"}) do
		local part = model:FindFirstChild(partName)
		if part and part:IsA("BasePart") then
			return part
		end
	end
	return nil
end

function npcSafety.IsNestedNpcNearRealSpawn(model, npcType)
	local root = getNpcRoot(model)
	if not root then
		return false
	end
	local family = npcSafety.SpawnFamilies[npcType]
	if not family then
		for _, tag in ipairs(game:GetService("CollectionService"):GetTags(model)) do
			if tag == "Group Raid" then
				family = "Group Raid Spawns"
			elseif tag == "Raid" then
				family = "Raid Spawns"
			end
		end
	end
	local world = workspace:FindFirstChild("World")
	local map = world and world:FindFirstChild("Map")
	local spawns = map and map:FindFirstChild("Spawns")
	local spawnFolder = family and spawns and spawns:FindFirstChild(family)
	if spawnFolder then
		for _, instance in ipairs(spawnFolder:GetDescendants()) do
			if instance:IsA("BasePart") and (root.Position - instance.Position).Magnitude <= 3500 then
				return true
			end
		end
	end
	local regionName = npcSafety.SpawnRegions[npcType]
	local fastTravel = map and map:FindFirstChild("Fast Travel")
	local region = regionName and fastTravel and fastTravel:FindFirstChild(regionName)
	local location = region and region:FindFirstChild("Location", true)
	if location and location:IsA("BasePart") then
		return (root.Position - location.Position).Magnitude <= 4500
	end
	if region and region:IsA("Model") then
		local ok, pivot = pcall(region.GetPivot, region)
		return ok and (root.Position - pivot.Position).Magnitude <= 4500
	end
	return false
end

function npcSafety.GetNpcPowerLevel(model)
	if not model or not model:IsA("Model") then return nil end
	for _, attributeName in ipairs({"PowerLevel", "Level", "Lvl", "PL"}) do
		local attribute = tonumber(model:GetAttribute(attributeName))
		if attribute and attribute >= 0 then return attribute end
	end
	local playerStats = model:FindFirstChild("PlayerStats")
	local statData = playerStats and playerStats:FindFirstChild("StatData")
	local coreStats = statData and statData:FindFirstChild("CoreStats")
	local powerValue = coreStats and coreStats:FindFirstChild("PowerLevel")
	if not powerValue and playerStats then powerValue = playerStats:FindFirstChild("PowerLevel", true) end
	if powerValue and powerValue:IsA("ValueBase") then
		local value = tonumber(powerValue.Value)
		if value and value >= 0 then return value end
	end
	return nil
end

function configStore.NpcESP.EnumerateModels()
	local models = {}
	local seen = {}
	local function consider(model, humanoid)
		if not model or not model:IsA("Model") or seen[model] or Players:GetPlayerFromCharacter(model) then
			return
		end
		local root = getNpcRoot(model)
		if not root or not humanoid or humanoid.Health <= 0 then
			return
		end
		seen[model] = true
		table.insert(models, {Model = model, Root = root, Humanoid = humanoid})
	end
	local live = getLiveFolder()
	if live then
		for _, descendant in ipairs(live:GetDescendants()) do
			if descendant:IsA("Humanoid") then
				consider(descendant.Parent, descendant)
			end
		end
	end
	local world = workspace:FindFirstChild("World")
	local npcFolder = world and world:FindFirstChild("NPC")
	if npcFolder then
		for _, descendant in ipairs(npcFolder:GetDescendants()) do
			if descendant:IsA("Humanoid") then
				consider(descendant.Parent, descendant)
			end
		end
	end
	return models
end

