-- Records the game's own outgoing remote calls for a short window so the Fast
-- Attack payload can be matched to whatever the current client sends on M1.
npcSafety.RemoteSpy = {Active = false, Until = 0, Lines = {}, File = configStore.Root .. "/remote_log.txt", Count = 0}

function npcSafety.RemoteSpy.Serialize(value, depth, seen)
	depth = depth or 0
	seen = seen or {}
	local kind = typeof(value)
	if kind == "table" then
		if seen[value] or depth > 6 then
			return "{...}"
		end
		seen[value] = true
		local parts = {}
		for key, item in pairs(value) do
			table.insert(parts, "[" .. npcSafety.RemoteSpy.Serialize(key, depth + 1, seen) .. "] = "
				.. npcSafety.RemoteSpy.Serialize(item, depth + 1, seen))
		end
		return "{" .. table.concat(parts, ", ") .. "}"
	elseif kind == "Instance" then
		return "Instance(" .. value:GetFullName() .. " [" .. value.ClassName .. "])"
	elseif kind == "string" then
		return string.format("%q", value)
	end
	return kind .. "(" .. tostring(value) .. ")"
end

function npcSafety.RemoteSpy.Record(remote, method, args)
	local spy = npcSafety.RemoteSpy
	if spy.Count >= 400 then
		return
	end
	spy.Count += 1
	local parts = {}
	for index = 1, args.n do
		parts[index] = npcSafety.RemoteSpy.Serialize(args[index])
	end
	table.insert(spy.Lines, string.format("[%.3f] %s:%s(%s)", os.clock(), remote:GetFullName(), method, table.concat(parts, ", ")))
	spy.Dirty = true
end

function npcSafety.RemoteSpy.Install()
	local spy = npcSafety.RemoteSpy
	if spy.Installed then
		return true
	end
	local hook = environment.hookmetamethod or (type(hookmetamethod) == "function" and hookmetamethod)
	local getMethod = environment.getnamecallmethod or (type(getnamecallmethod) == "function" and getnamecallmethod)
	local wrap = environment.newcclosure or (type(newcclosure) == "function" and newcclosure) or function(fn)
		return fn
	end
	if type(hook) ~= "function" or type(getMethod) ~= "function" then
		return false
	end
	local original
	original = hook(game, "__namecall", wrap(function(self, ...)
		local inspector = configStore.RemoteInspector
		local serverInfoSession
		if (spy.Active or inspector.Active) and not unloaded then
			-- Instrumentation must never prevent the original call or change its returns.
			local methodOk, method = pcall(getMethod)
			if methodOk and (method == "FireServer" or method == "InvokeServer") and typeof(self) == "Instance" then
				pcall(spy.Capture, self, method, table.pack(...), "namecall")
				-- Observe the game's own named-server lookup, without making or
				-- replaying requests. Preserve nil slots and every original return.
				if inspector.Active and method=="InvokeServer" and self.Name=="GetServerInfo"
					and self.Parent==remotes then serverInfoSession=inspector.SessionId end
			end
		end
		if serverInfoSession then
			local values=table.pack(original(self,...))
			pcall(spy.CaptureServerInfoReturn,self,serverInfoSession,values)
			return table.unpack(values,1,values.n)
		end
		return original(self, ...)
	end))
	spy.HookFunction = hook
	spy.Original = original
	spy.Installed = true
	return true
end

function npcSafety.RemoteSpy.CaptureServerInfoReturn(remote, sessionId, values)
	local inspector=configStore.RemoteInspector
	if unloaded or not inspector.Active or inspector.SessionId~=sessionId then return end
	if remote.Parent~=remotes or remote.Name~="GetServerInfo" then return end
	inspector.Observe(remote,"IN GetServerInfo RETURN (passive)",values)
end

function npcSafety.RemoteSpy.Capture(remote, method, args, channel)
	local spy, inspector = npcSafety.RemoteSpy, configStore.RemoteInspector
	if unloaded or typeof(remote) ~= "Instance" then return end
	if not (remote:IsA("RemoteEvent") or remote:IsA("RemoteFunction") or remote:IsA("UnreliableRemoteEvent")) then return end
	local check = environment.checkcaller or (type(checkcaller) == "function" and checkcaller)
	local origin = "unknown"
	if type(check) == "function" then
		local ok, result = pcall(check)
		if ok then origin = result and "executor" or "game" end
	end
	if channel == "namecall" and spy.Active and origin ~= "executor" then pcall(spy.Record, remote, method, args) end
	if not inspector.Active then return end
	if inspector.MissionMode then
		pcall(inspector.Observe, remote, "OUT " .. channel .. "/" .. origin .. " " .. method, args)
	elseif channel == "namecall" and origin ~= "executor" then
		pcall(inspector.Observe, remote, "OUT " .. method, args)
	end
end

function npcSafety.RemoteSpy.InstallDirect()
	local spy, inspector = npcSafety.RemoteSpy, configStore.RemoteInspector
	local hook = environment.hookfunction or (type(hookfunction) == "function" and hookfunction)
	if type(hook) ~= "function" then return "UNAVAILABLE: hookfunction not supported" end
	local wrap = environment.newcclosure or (type(newcclosure) == "function" and newcclosure) or function(fn) return fn end
	spy.DirectHooks = spy.DirectHooks or {}
	local supported = {}
	for remote in pairs(inspector.ByObject) do
		local class = remote.ClassName
		if supported[class] then continue end
		local method = class == "RemoteFunction" and "InvokeServer" or "FireServer"
		local target = remote[method]
		if type(target) ~= "function" then continue end
		if not spy.DirectHooks[target] then
			local original
			local ok, result = pcall(function()
				return hook(target, wrap(function(self, ...)
					if inspector.Active and inspector.MissionMode and not unloaded then
						pcall(spy.Capture, self, method, table.pack(...), "direct")
					end
					return original(self, ...)
				end))
			end)
			if ok and type(result) == "function" then
				original = result
				spy.DirectHooks[target] = {Original = original, Hook = hook}
			end
		end
		if spy.DirectHooks[target] then supported[class] = true end
	end
	local classes = {}; for class in pairs(supported) do table.insert(classes, class) end; table.sort(classes)
	return #classes > 0 and table.concat(classes, ", ") or "UNAVAILABLE: no compatible remote methods hooked"
end

function npcSafety.RemoteSpy.Uninstall()
	local spy = npcSafety.RemoteSpy
	spy.Active = false
	spy.Dirty = false
	for target, record in pairs(spy.DirectHooks or {}) do
		pcall(record.Hook, target, record.Original)
	end
	spy.DirectHooks = nil
	if not spy.Installed then
		return true
	end
	local restored = false
	local restore = environment.restorehookmetamethod
		or (type(restorehookmetamethod) == "function" and restorehookmetamethod)
	if type(restore) == "function" and spy.Original then
		restored = pcall(restore, game, "__namecall", spy.Original)
	end
	if not restored and type(spy.HookFunction) == "function" and spy.Original then
		restored = pcall(spy.HookFunction, game, "__namecall", spy.Original)
	end
	spy.Installed = false
	spy.HookFunction = nil
	spy.Original = nil
	return restored
end

function npcSafety.RemoteSpy.Start()
	local spy = npcSafety.RemoteSpy
	local button = npcSafety.DirectLight.RecordButton
	if not spy.Install() then
		button.Text = "No hook support"
		button.TextColor3 = colors.DangerHover
		return
	end
	table.clear(spy.Lines)
	spy.Count = 0
	spy.Active = true
	spy.Until = os.clock() + 20
	table.insert(spy.Lines, "place=" .. game.PlaceId .. " - punch an NPC normally (Fast Attack OFF) for 20s")
	local decompiler = environment.decompile or (type(decompile) == "function" and decompile)
	local playerScripts = localPlayer:FindFirstChild("PlayerScripts")
	local client = playerScripts and playerScripts:FindFirstChild("Client")
	local combat = client and client:FindFirstChild("Core") and client.Core:FindFirstChild("Combat")
	if combat and type(decompiler) == "function" and type(writefile) == "function" then
		for _, descendant in ipairs(combat:GetDescendants()) do
			if descendant:IsA("ModuleScript") or descendant:IsA("LocalScript") then
				local ok, source = pcall(decompiler, descendant)
				local fileName = configStore.Root .. "/src_" .. string.gsub(descendant:GetFullName(), "[^%w_]", "_") .. ".lua"
				if ok and type(source) == "string" then
					pcall(writefile, fileName, source)
				end
				table.insert(spy.Lines, string.format("decompile %s -> %s", descendant:GetFullName(),
					ok and type(source) == "string" and fileName or ("failed: " .. tostring(source))))
			end
		end
	else
		table.insert(spy.Lines, "decompile unavailable or combat folder missing")
	end
	spy.Dirty = true
	warn("[Anomaly's Hub] Recording remote calls for 20s - punch an NPC normally now.")
end

connect(npcSafety.DirectLight.RecordButton.Activated, npcSafety.RemoteSpy.Start)
connect(RunService.Heartbeat, function()
	local spy = npcSafety.RemoteSpy
	local button = npcSafety.DirectLight.RecordButton
	if spy.Active then
		local left = spy.Until - os.clock()
		if left <= 0 then
			spy.Active = false
			spy.Dirty = true
			warn(string.format("[Anomaly's Hub] Remote recording done: %d calls saved to %s", spy.Count, spy.File))
		end
		button.Text = spy.Active and string.format("REC %ds (%d)", math.ceil(left), spy.Count) or "Record M1"
		button.TextColor3 = spy.Active and colors.DangerHover or colors.Muted
	end
	if spy.Dirty and type(writefile) == "function" and (not spy.Active or os.clock() - (spy.LastWriteAt or 0) >= 0.5) then
		spy.Dirty = false
		spy.LastWriteAt = os.clock()
		pcall(writefile, spy.File, table.concat(spy.Lines, "\n"))
	end
end)

function npcSafety.IsKnocked(target)
	return target and target:FindFirstChild("Knocked") ~= nil and target:FindFirstChild("K.O") ~= nil
end

function npcSafety.ResetPostCombat()
	npcSafety.GripMode = false
	npcSafety.GripElapsed = 0
	npcSafety.GripTarget = nil
	npcSafety.GripConfirmed = false
	npcSafety.LastTargetPosition = nil
	npcSafety.LootMode = false
	npcSafety.LootStartedAt = 0
	npcSafety.LootReceipt = nil
	npcSafety.LootClickedAt = 0
	npcSafety.LootPromptElapsed = 0
	npcSafety.LootPrompt = nil
	npcSafety.LootPosition = nil
	npcSafety.ChestScanElapsed = 0
	npcSafety.ReacquireHoldPosition = nil
end

function npcSafety.ClickGuiButton(button)
	if not button or not button:IsA("GuiButton") or not button.Visible then
		return false
	end

	local position = getVirtualInputPosition(button)
	local guiWasEnabled = screenGui.Enabled

	if guiWasEnabled then
		screenGui.Enabled = false
		task.wait()
	end

	local ok = pcall(function()
		VirtualInputManager:SendMouseButtonEvent(position.X, position.Y, 0, true, game, 0)
		task.wait(0.075)
		VirtualInputManager:SendMouseButtonEvent(position.X, position.Y, 0, false, game, 0)
	end)

	task.delay(0.08, function()
		if guiWasEnabled and screenGui and screenGui.Parent and not unloaded then
			screenGui.Enabled = true
		end
	end)

	return ok
end

npcSafety.TrackedPrompts = {}
for _, instance in ipairs(workspace:GetDescendants()) do
	if instance:IsA("ProximityPrompt") then
		npcSafety.TrackedPrompts[instance] = true
	end
end
connect(workspace.DescendantAdded, function(instance)
	if instance:IsA("ProximityPrompt") then
		npcSafety.TrackedPrompts[instance] = true
	end
end)
connect(workspace.DescendantRemoving, function(instance)
	npcSafety.TrackedPrompts[instance] = nil
	npcSafety.IgnoredChestPrompts[instance] = nil
end)

function npcSafety.FindNearbyChestPrompt(position, radius)
	radius = type(radius) == "number" and radius or 55
	local nearestPrompt, nearestPosition, nearestDistance
	local now = os.clock()
	for instance in pairs(npcSafety.TrackedPrompts) do
		local ignoredUntil = npcSafety.IgnoredChestPrompts[instance]
		if instance.Parent and instance.Enabled
			and (not ignoredUntil or now >= ignoredUntil) then
			local owner = instance.Parent
			local point
			if owner and owner:IsA("BasePart") then
				point = owner.Position
			elseif owner and owner.Parent and owner.Parent:IsA("BasePart") then
				point = owner.Parent.Position
			elseif owner and owner:IsA("Model") then
				local ok, pivot = pcall(owner.GetPivot, owner)
				point = ok and pivot.Position or nil
			end
			if point then
				local label = string.lower(instance.Name .. " " .. instance.ActionText .. " " .. instance.ObjectText .. " " .. (owner and owner.Name or ""))
				local chestLike = string.find(label, "chest", 1, true) or string.find(label, "loot", 1, true)
				local ancestor = owner
				for _ = 1, 5 do
					if not ancestor then
						break
					end
					local ancestorName = string.lower(ancestor.Name)
					if ancestor:GetAttribute("ChestId") ~= nil or string.find(ancestorName, "chest", 1, true) then
						chestLike = true
						break
					end
					ancestor = ancestor.Parent
				end
				local distance = (point - position).Magnitude
				if chestLike and distance <= radius and (not nearestDistance or distance < nearestDistance) then
					nearestPrompt, nearestPosition, nearestDistance = instance, point, distance
				end
			end
		end
	end
	return nearestPrompt, nearestPosition, nearestDistance
end

function npcSafety.ModelMatchesSuper17Watch(model)
	if not model or not model:IsA("Model") then
		return false
	end
	local name = string.lower(model.Name)
	return string.find(name, "super", 1, true) ~= nil and string.find(name, "17", 1, true) ~= nil
end

function npcSafety.GetWatchlistNpcCountsInTravelNpcs()
	local counts = {}
	for _, watchName in ipairs(npcSafety.NpcWatchlist or {}) do
		counts[watchName] = 0
	end
	for model in pairs(npcSafety.Super17Candidates) do
		if model.Parent and model:IsDescendantOf(workspace)
			and npcSafety.ModelMatchesSuper17Watch(model)
			and model:FindFirstChildOfClass("Humanoid") and getNpcRoot(model)
			and not Players:GetPlayerFromCharacter(model) then
			counts["Super 17"] = (counts["Super 17"] or 0) + 1
		end
	end
	return counts
end

npcSafety.Super17Candidates = {}
function npcSafety.TrackSuper17Candidate(instance)
	if instance:IsA("Model") and npcSafety.ModelMatchesSuper17Watch(instance) then
		npcSafety.Super17Candidates[instance] = true
	end
end
for _, instance in ipairs(workspace:GetDescendants()) do
	npcSafety.TrackSuper17Candidate(instance)
end
connect(workspace.DescendantAdded, npcSafety.TrackSuper17Candidate)
connect(workspace.DescendantRemoving, function(instance)
	npcSafety.Super17Candidates[instance] = nil
end)

function npcSafety.AlertSuper17InNpcs(count)
	count = math.max(1, tonumber(count) or 1)
	local message = string.format(
		"Super 17 detected in this server (%d instance%s). Model name contains \"super\" and \"17\". Talk NPC, not a farm target.",
		count,
		count == 1 and "" or "s"
	)
	warn("[GohanHub] SUPER 17 ALERT:", message)
	pcall(function()
		game:GetService("StarterGui"):SetCore("SendNotification", {
			Title = "Super 17 detected",
			Text = "Open Travel → NPCs if he is a talk NPC",
			Duration = 14,
		})
	end)
	if type(setNpcStatus) == "function" then
		setNpcStatus("ALERT: Super 17 detected in this server.", colors.DangerHover)
	end
	if configStore and configStore.Webhook then
		configStore.Webhook.Send("Super 17 detected", message, 16744192)
	end
end

function npcSafety.UpdateWatchlistNpcAlerts()
	npcSafety.WatchlistPresenceCounts = npcSafety.WatchlistPresenceCounts or {}
	local counts = npcSafety.GetWatchlistNpcCountsInTravelNpcs()
	for _, watchName in ipairs(npcSafety.NpcWatchlist or {}) do
		local count = counts[watchName] or 0
		local previous = npcSafety.WatchlistPresenceCounts[watchName] or 0
		if count > 0 and previous == 0 then
			local lastAlertAt = npcSafety.LastWatchlistAlertAt and npcSafety.LastWatchlistAlertAt[watchName]
			-- Streaming can drop and re-add the model; only re-alert after a real absence.
			if watchName == "Super 17" and (not lastAlertAt or os.clock() - lastAlertAt >= 300) then
				npcSafety.LastWatchlistAlertAt = npcSafety.LastWatchlistAlertAt or {}
				npcSafety.LastWatchlistAlertAt[watchName] = os.clock()
				npcSafety.AlertSuper17InNpcs(count)
			end
		end
		npcSafety.WatchlistPresenceCounts[watchName] = count
	end
end

function npcSafety.UpdateChestLootButton()
	local button = npcSafety.ChestLootButton
	if not button then return end
	button.Text = npcSafety.ChestLootEnabled and "Chest Loot: ON" or "Chest Loot: OFF"
	button.BackgroundColor3 = npcSafety.ChestLootEnabled and colors.Accent or colors.Surface
	button.TextColor3 = npcSafety.ChestLootEnabled and colors.Text or colors.Muted
end

function npcSafety.SetChestLootEnabled(enabled)
	npcSafety.ChestLootEnabled = enabled == true
	if not npcSafety.ChestLootEnabled and npcSafety.LootMode then
		npcSafety.FinishLootWait("Chest loot disabled; reacquiring " .. tostring(selectedNpcType) .. "...")
	end
	npcSafety.UpdateChestLootButton()
	return npcSafety.ChestLootEnabled
end

function npcSafety.BeginLootWait(character, humanoid, characterRoot, position, prompt, message)
	if not npcSafety.ChestLootEnabled then return false end
	npcSafety.GripMode = false
	npcSafety.GripTarget = nil
	npcSafety.GripConfirmed = false
	npcSafety.LootMode = true
	npcSafety.LootStartedAt = os.clock()
	npcSafety.LootReceipt = nil
	npcSafety.LootClickedAt = 0
	npcSafety.LootPromptElapsed = prompt and 0 or 1
	npcSafety.LootPrompt = prompt
	npcSafety.LootPosition = position or npcSafety.LastTargetPosition or characterRoot.Position
	if position then
		npcSafety.LastTargetPosition = position
	end
	activeNpcTarget = nil
	npcApproachPhase = "LootWait"
	npcSafety.EnsureMovementRig(character, humanoid, characterRoot)
	if npcLinearVelocity then
		npcLinearVelocity.Enabled = true
		npcLinearVelocity.VectorVelocity = Vector3.zero
	end
	if npcAlignOrientation then
		npcAlignOrientation.Enabled = false
	end
	humanoid.PlatformStand = false
	setNpcStatus(message or "Grip complete; checking for a dropped chest before reacquiring...", colors.Success)
end

function npcSafety.FinishLootWait(message)
	-- Cancel the receipt before Close can yield or disable the UI. Cleanup and
	-- timeouts must never masquerade as a successful loot-window transition.
	npcSafety.LootMode = false
	npcSafety.LootReceipt = nil
	if npcSafety.LootPrompt then
		npcSafety.IgnoredChestPrompts[npcSafety.LootPrompt] = os.clock() + npcSafety.ChestRetryDelay
	end
	local staleChestGui = playerGui:FindFirstChild("DropChestGui")
	if staleChestGui and staleChestGui:IsA("ScreenGui") and staleChestGui.Enabled then
		local closeButton = staleChestGui:FindFirstChild("Close", true)
		if closeButton and closeButton:IsA("GuiButton") then
			npcSafety.ClickGuiButton(closeButton)
		end
		staleChestGui.Enabled = false
	end
	npcSafety.LootScanCooldownUntil = os.clock() + 8
	npcSafety.LootMode = false
	npcSafety.LootStartedAt = 0
	npcSafety.LootReceipt = nil
	npcSafety.LootClickedAt = 0
	npcSafety.LootPromptElapsed = 0
	npcSafety.LootPrompt = nil
	npcSafety.LootPosition = nil
	npcSafety.LastTargetPosition = nil
	local character = localPlayer.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local characterRoot = character and character:FindFirstChild("HumanoidRootPart")
	if humanoid and humanoid.Health > 0 and characterRoot then
		npcSafety.ReacquireHoldPosition = characterRoot.Position
		npcSafety.HoldWhileReacquiring(character, humanoid, characterRoot)
	else
		clearNpcConstraintRig()
	end
	npcAcquireElapsed = 1
	setNpcStatus(message or ("Chest check complete; reacquiring " .. tostring(selectedNpcType) .. "..."), colors.Success)
end

-- A receipt starts only on a non-empty Take All attempt, never on opening a prompt.
-- UI completion is a client observation, not a server reward acknowledgement.
function npcSafety.IsChestUiEmpty(gui)
	local title = gui and gui:FindFirstChild("Title", true)
	return title and title:IsA("TextLabel") and string.match(string.upper(title.Text), "^%s*EMPTY%s*$") ~= nil
end

function npcSafety.ConfirmChestReceipt(gui, now)
	local receipt = npcSafety.LootReceipt
	if not receipt or not receipt.Sent or receipt.Busy or now - receipt.StartedAt < 0.6 then return false end
	local original = receipt.Gui
	local closed = not original.Parent or not original.Enabled
	if gui ~= original and not closed then return false end
	local takeAll = original:FindFirstChild("TakeAll", true)
	if closed or npcSafety.IsChestUiEmpty(original) or (takeAll and not takeAll.Visible) then
		configStore.Session.RecordChest(receipt)
		return true
	end
	return false
end

function npcSafety.UpdateLootWait(deltaTime, character, humanoid, characterRoot)
	if not npcSafety.LootMode then
		return false
	end
	npcSafety.EnsureMovementRig(character, humanoid, characterRoot)
	humanoid.PlatformStand = false
	if npcLinearVelocity then
		npcLinearVelocity.Enabled = true
	end
	if npcAlignOrientation then
		npcAlignOrientation.Enabled = false
	end

	local chestGui = playerGui:FindFirstChild("DropChestGui")
	if npcSafety.ConfirmChestReceipt(chestGui, os.clock()) then
		npcSafety.FinishLootWait("Dropped chest looted; reacquiring " .. tostring(selectedNpcType) .. "...")
		return true
	end
	if chestGui and chestGui:IsA("ScreenGui") and chestGui.Enabled then
		local takeAll = chestGui:FindFirstChild("TakeAll", true)
		if npcSafety.IsChestUiEmpty(chestGui) and not npcSafety.LootReceipt then
			npcSafety.FinishLootWait("Chest already empty; reacquiring " .. tostring(selectedNpcType) .. "...")
			return true
		end
		local receipt = npcSafety.LootReceipt
		if receipt and receipt.Busy then return true end
		if takeAll and takeAll:IsA("GuiButton") and takeAll.Visible
			and not npcSafety.IsChestUiEmpty(chestGui)
			and (not receipt or os.clock() - receipt.LastAttemptAt >= 0.8) then
			if not receipt then
				receipt = {Gui = chestGui, Prompt = npcSafety.LootPrompt, StartedAt = os.clock()}
				npcSafety.LootReceipt = receipt
			end
			receipt.LastAttemptAt = os.clock()
			receipt.Busy = true
			local sent = npcSafety.ClickGuiButton(takeAll)
			receipt.Busy = false
			if unloaded or not npcSafety.LootMode or npcSafety.LootReceipt ~= receipt then return true end
			receipt.Sent = receipt.Sent or sent
			setNpcStatus(sent and "Dropped chest opened; taking all loot..." or "Loot click failed; retrying...", colors.Success)
		end
	else
		npcSafety.LootPromptElapsed += deltaTime
		if npcSafety.LootPromptElapsed >= 0.25 then
			npcSafety.LootPromptElapsed = 0
			local searchOrigin = npcSafety.LootPosition or npcSafety.LastTargetPosition or characterRoot.Position
			local foundPrompt, foundPosition = npcSafety.FindNearbyChestPrompt(searchOrigin)
			if foundPrompt then
				npcSafety.LootPrompt = foundPrompt
				npcSafety.LootPosition = foundPosition
			elseif not npcSafety.LootPrompt or not npcSafety.LootPrompt.Parent then
				npcSafety.LootPrompt = nil
			end
		end
	end

	local destination = npcSafety.LootPosition or npcSafety.LastTargetPosition or characterRoot.Position
	-- Move close enough for short-range chest prompts. Noclip already prevents the
	-- chest model or terrain from physically blocking this approach point.
	local desiredY = destination.Y - npcSafety.ChestApproachOffset
	local desiredPosition = Vector3.new(destination.X, desiredY, destination.Z)
	local movementDelta = desiredPosition - characterRoot.Position
	local movementDistance = movementDelta.Magnitude
	local speed = getNpcGlideSpeed(movementDistance)
	npcLinearVelocity.VectorVelocity = movementDistance > 0.35
		and movementDelta.Unit * math.min(speed, math.max(18, movementDistance * 5))
		or Vector3.zero

	if not (chestGui and chestGui:IsA("ScreenGui") and chestGui.Enabled)
		and not npcSafety.LootReceipt and npcSafety.LootPrompt and npcSafety.LootPrompt.Parent then
		local promptDistance = npcSafety.LootPosition and (npcSafety.LootPosition - characterRoot.Position).Magnitude or math.huge
		if promptDistance <= math.max(4, npcSafety.LootPrompt.MaxActivationDistance - 0.25)
			and os.clock() - npcSafety.LootClickedAt >= 0.9 then
			npcSafety.LootClickedAt = os.clock()
			npcSafety.TriggerChestPrompt(npcSafety.LootPrompt)
			setNpcStatus("Interacting with the dropped chest...", colors.Success)
		end
	else
		setNpcStatus("Grip complete; waiting briefly for a dropped chest...", colors.Success)
	end

	local timeout = npcSafety.LootPrompt and 20 or 12
	if os.clock() - npcSafety.LootStartedAt >= timeout then
		npcSafety.FinishLootWait("No lootable chest remained; reacquiring " .. tostring(selectedNpcType) .. "...")
	end
	return true
end

function npcSafety.GetNearbyPlayer(position, range)
	local nearestPlayer = nil
	local nearestDistance = range
	for _, player in ipairs(Players:GetPlayers()) do
		if player ~= localPlayer then
			local character = player.Character
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			local root = character and (character:FindFirstChild("HumanoidRootPart")
				or character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso"))
			if humanoid and humanoid.Health > 0 and root then
				-- Proximity protection is horizontal: a player visibly nearby on a
				-- ledge or while flying still counts even if their Y offset is large.
				local offset = root.Position - position
				local distance = Vector2.new(offset.X, offset.Z).Magnitude
				if distance <= nearestDistance then
					nearestPlayer = player
					nearestDistance = distance
				end
			end
		end
	end
	return nearestPlayer, nearestDistance
end

function npcSafety.RetargetContestedNpc()
	if not activeNpcTarget or npcSafety.IsNpcOutsidePlayerRange(activeNpcTarget) then return false end
	-- Run before attacks, grips, hide/hop checks and movement on every heartbeat.
	-- A moving player or an edited radius invalidates the old target immediately.
	clearNpcConstraintRig()
	npcAttackElapsed = 0
	npcAcquireElapsed = 1
	npcSafety.GripMode = false
	npcSafety.GripTarget = nil
	npcSafety.GripElapsed = 0
	npcSafety.GripConfirmed = false
	npcSafety.LastTargetPosition = nil
	npcSafety.SpawnDestination = nil
	npcSafety.SpawnSource = nil
	npcSafety.SpawnWaitReason = nil
	local nextTarget = findNearestNpc(selectedNpcType)
	if nextTarget and attachToNpc(nextTarget) then
		setNpcStatus("Player range breached; switching to safe " .. nextTarget.Name .. ".", colors.Success)
	end
	return true
end

function npcSafety.HttpGetJson(url)
	local environmentRequest = environment.request or environment.http_request
	local synTable = environment.syn
	if not environmentRequest and type(synTable) == "table" then
		environmentRequest = synTable.request
	end
	if type(environmentRequest) == "function" then
		local ok, response = pcall(environmentRequest, {
			Url = url,
			Method = "GET",
			Headers = {Accept = "application/json"},
		})
		if ok then
			local body = type(response) == "table" and (response.Body or response.body) or response
			if type(body) == "string" then
				local decodedOk, decoded = pcall(HttpService.JSONDecode, HttpService, body)
				if decodedOk then
					return decoded
				end
			end
		end
	end
	local ok, body = pcall(function()
		return game:HttpGet(url)
	end)
	if ok and type(body) == "string" then
		local decodedOk, decoded = pcall(HttpService.JSONDecode, HttpService, body)
		if decodedOk then
			return decoded
		end
	end
	return nil
end

function npcSafety.HttpPostJson(url, bodyTable)
	if type(url) ~= "string" or type(bodyTable) ~= "table" then
		return nil
	end
	local encodedOk, encodedBody = pcall(HttpService.JSONEncode, HttpService, bodyTable)
	if not encodedOk or type(encodedBody) ~= "string" then
		return nil
	end
	local environmentRequest = environment.request or environment.http_request
	local synTable = environment.syn
	if not environmentRequest and type(synTable) == "table" then
		environmentRequest = synTable.request
	end
	if type(environmentRequest) == "function" then
		local ok, response = pcall(environmentRequest, {
			Url = url,
			Method = "POST",
			Headers = {
				Accept = "application/json",
				["Content-Type"] = "application/json",
			},
			Body = encodedBody,
		})
		if ok then
			local body = type(response) == "table" and (response.Body or response.body) or response
			if type(body) == "string" then
				local decodedOk, decoded = pcall(HttpService.JSONDecode, HttpService, body)
				if decodedOk then
					return decoded
				end
			end
		end
	end
	local ok, body = pcall(function()
		return HttpService:PostAsync(url, encodedBody, Enum.HttpContentType.ApplicationJson, false)
	end)
	if ok and type(body) == "string" then
		local decodedOk, decoded = pcall(HttpService.JSONDecode, HttpService, body)
		if decodedOk then
			return decoded
		end
	end
	return nil
end

function qolState.ServerNavigation.SetStatus(message,color)
	qolState.ServerNavigation.StatusLabel.Text=tostring(message)
	qolState.ServerNavigation.StatusLabel.TextColor3=color or colors.Muted
end

function qolState.ServerNavigation.SetBusy(busy)
	qolState.ServerNavigation.Busy=busy==true
	for _,button in pairs(qolState.ServerNavigation.Buttons) do
		button.Active=not qolState.ServerNavigation.Busy
		button.BackgroundColor3=qolState.ServerNavigation.Busy and colors.SurfaceRaised or colors.Surface
		button.TextColor3=qolState.ServerNavigation.Busy and colors.Muted or colors.Text
	end
	local joinButton = qolState.ServerNavigation.JoinFriendButton
	if joinButton then
		joinButton.Active = not qolState.ServerNavigation.Busy
		joinButton.BackgroundColor3 = qolState.ServerNavigation.Busy and colors.SurfaceRaised or colors.Accent
		joinButton.TextColor3 = qolState.ServerNavigation.Busy and colors.Muted or colors.Background
	end
	local pickButton = qolState.ServerNavigation.PickFriendButton
	if pickButton then
		pickButton.Active = not qolState.ServerNavigation.Busy
		pickButton.BackgroundColor3 = qolState.ServerNavigation.Busy and colors.SurfaceRaised or colors.Surface
		pickButton.TextColor3 = qolState.ServerNavigation.Busy and colors.Muted or colors.Text
	end
	local friendBox = qolState.ServerNavigation.FriendUsernameBox
	if friendBox then
		friendBox.Active = not qolState.ServerNavigation.Busy
	end
end

function qolState.ServerNavigation.NormalizeFriendIdentifier(raw)
	if type(raw) ~= "string" then
		return ""
	end
	local trimmed = string.match(raw, "^%s*(.-)%s*$") or ""
	trimmed = string.gsub(trimmed, "^@", "")
	return trimmed
end

function qolState.ServerNavigation.ResolveUserId(identifier)
	local normalized = qolState.ServerNavigation.NormalizeFriendIdentifier(identifier)
	if normalized == "" then
		return nil, "Enter a Roblox username."
	end
	local numericId = tonumber(normalized)
	if numericId and numericId > 0 then
		return math.floor(numericId), nil
	end
	local ok, userId = pcall(Players.GetUserIdFromNameAsync, Players, normalized)
	if ok and type(userId) == "number" and userId > 0 then
		return userId, nil
	end
	return nil, "Could not resolve @" .. normalized .. "."
end

function qolState.ServerNavigation.IsKnownGamePlace(placeId)
	if placeId == game.PlaceId then
		return true
	end
	for _, knownPlaceId in pairs(planetData) do
		if knownPlaceId == placeId then
			return true
		end
	end
	return false
end

function qolState.ServerNavigation.RefreshOnlineFriends()
	local now = os.clock()
	if qolState.ServerNavigation.OnlineFriendsFetchedAt
		and now - qolState.ServerNavigation.OnlineFriendsFetchedAt < 15 then
		return #qolState.ServerNavigation.OnlineFriends
	end
	qolState.ServerNavigation.OnlineFriends = {}
	local ok, online = pcall(function()
		return localPlayer:GetFriendsOnline(200)
	end)
	if not ok or type(online) ~= "table" then
		return 0
	end
	qolState.ServerNavigation.OnlineFriendsFetchedAt = now
	-- GetFriendsOnline's GameId is the friend's server JobId, not the universe id.
	for _, friend in ipairs(online) do
		if type(friend) == "table" and type(friend.VisitorId) == "number" and friend.VisitorId ~= localPlayer.UserId
			and type(friend.PlaceId) == "number" and qolState.ServerNavigation.IsKnownGamePlace(friend.PlaceId)
			and type(friend.GameId) == "string" and friend.GameId ~= "" then
			table.insert(qolState.ServerNavigation.OnlineFriends, friend)
		end
	end
	table.sort(qolState.ServerNavigation.OnlineFriends, function(a, b)
		local aName = string.lower(tostring(a.UserName or a.DisplayName or a.VisitorId))
		local bName = string.lower(tostring(b.UserName or b.DisplayName or b.VisitorId))
		return aName < bName
	end)
	return #qolState.ServerNavigation.OnlineFriends
end

function qolState.ServerNavigation.CycleOnlineFriend(step)
	if qolState.ServerNavigation.Busy then
		return false
	end
	local count = qolState.ServerNavigation.RefreshOnlineFriends()
	if count == 0 then
		qolState.ServerNavigation.SetStatus("No friends are online in this game right now.", colors.DangerHover)
		return false
	end
	local index = (qolState.ServerNavigation.PickFriendIndex or 0) + (step or 1)
	if index < 1 then
		index = count
	elseif index > count then
		index = 1
	end
	qolState.ServerNavigation.PickFriendIndex = index
	local friend = qolState.ServerNavigation.OnlineFriends[index]
	local displayName = friend.UserName or friend.DisplayName or tostring(friend.VisitorId)
	if qolState.ServerNavigation.FriendUsernameBox then
		qolState.ServerNavigation.FriendUsernameBox.Text = displayName
	end
	qolState.ServerNavigation.SetStatus(
		string.format("Friend %d/%d selected: @%s", index, count, displayName),
		colors.Success
	)
	return true
end

function qolState.ServerNavigation.FetchUserPresence(userId)
	if type(userId) ~= "number" then
		return nil
	end
	local function fromFriendList()
		for _, friend in ipairs(qolState.ServerNavigation.OnlineFriends) do
			if friend.VisitorId == userId then
				return {
					userId = userId,
					userPresenceType = 2,
					placeId = friend.PlaceId,
					gameId = friend.GameId,
					userName = friend.UserName or friend.DisplayName,
				}
			end
		end
		return nil
	end
	local cached = fromFriendList()
	if cached then
		return cached
	end
	qolState.ServerNavigation.OnlineFriendsFetchedAt = nil
	qolState.ServerNavigation.RefreshOnlineFriends()
	cached = fromFriendList()
	if cached then
		return cached
	end
	local payload = npcSafety.HttpPostJson("https://presence.roblox.com/v1/presence/users", {userIds = {userId}})
	if type(payload) == "table" and type(payload.userPresences) == "table" then
		return payload.userPresences[1]
	end
	return nil
end

function qolState.ServerNavigation.GetHeadshotUrl(userId)
	local payload = npcSafety.HttpGetJson(string.format(
		"https://thumbnails.roblox.com/v1/users/avatar-headshot?userIds=%d&size=150x150&format=Png&isCircular=false",
		userId
	))
	local entry = type(payload) == "table" and type(payload.data) == "table" and payload.data[1]
	return type(entry) == "table" and type(entry.imageUrl) == "string" and entry.imageUrl or nil
end

-- Public server listings only expose per-player thumbnail tokens, so a player is
-- located by matching their avatar headshot URL against each server's tokens.
function qolState.ServerNavigation.FindUserServerByScan(userId, preferredPlaceId)
	local targetUrl = qolState.ServerNavigation.GetHeadshotUrl(userId)
	if not targetUrl then
		return nil, nil, "could not load their avatar to search with."
	end
	local places, seenPlaces = {}, {}
	local function addPlace(placeId)
		if type(placeId) == "number" and placeId > 0 and not seenPlaces[placeId] then
			seenPlaces[placeId] = true
			table.insert(places, placeId)
		end
	end
	addPlace(preferredPlaceId)
	addPlace(game.PlaceId)
	for _, placeId in pairs(planetData) do
		addPlace(placeId)
	end
	local scanned = 0
	for _, placeId in ipairs(places) do
		local cursor = nil
		for _ = 1, 10 do
			if unloaded then
				return nil, nil, "hub unloaded."
			end
			local url = string.format("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Desc&limit=100", placeId)
			if cursor then
				url ..= "&cursor=" .. HttpService:UrlEncode(cursor)
			end
			local page = npcSafety.HttpGetJson(url)
			if type(page) ~= "table" or type(page.data) ~= "table" then
				break
			end
			local batch, tokenServers = {}, {}
			for _, server in ipairs(page.data) do
				if type(server) == "table" and type(server.id) == "string" and type(server.playerTokens) == "table" then
					scanned += 1
					for _, token in ipairs(server.playerTokens) do
						if type(token) == "string" then
							table.insert(batch, {
								requestId = token,
								token = token,
								type = "AvatarHeadShot",
								size = "150x150",
								format = "png",
								isCircular = false,
							})
							tokenServers[token] = server.id
						end
					end
				end
			end
			for startIndex = 1, #batch, 100 do
				local chunk = table.move(batch, startIndex, math.min(startIndex + 99, #batch), 1, {})
				local result = npcSafety.HttpPostJson("https://thumbnails.roblox.com/v1/batch", chunk)
				if type(result) == "table" and type(result.data) == "table" then
					for _, item in ipairs(result.data) do
						if type(item) == "table" and item.imageUrl == targetUrl and tokenServers[item.requestId] then
							return placeId, tokenServers[item.requestId], nil
						end
					end
				end
			end
			qolState.ServerNavigation.SetStatus(string.format("Searching... %d servers checked", scanned), colors.Warning)
			cursor = page.nextPageCursor
			if type(cursor) ~= "string" or cursor == "" then
				break
			end
		end
	end
	return nil, nil, string.format("not found in %d public servers.", scanned)
end

function qolState.ServerNavigation.TeleportToUserServer(targetPlaceId, jobId)
	if type(targetPlaceId) ~= "number" or type(jobId) ~= "string" or jobId == "" then
		return false, "Their server is hidden (join privacy or not a friend)."
	end
	if targetPlaceId == game.PlaceId and jobId == game.JobId then
		return false, "You are already in their server."
	end
	return pcall(TeleportService.TeleportToPlaceInstance, TeleportService, targetPlaceId, jobId, localPlayer)
end

function qolState.ServerNavigation.JoinFriend(identifier)
	if qolState.ServerNavigation.Busy then
		return false
	end
	local rawIdentifier = identifier
	if rawIdentifier == nil and qolState.ServerNavigation.FriendUsernameBox then
		rawIdentifier = qolState.ServerNavigation.FriendUsernameBox.Text
	end
	qolState.ServerNavigation.SetBusy(true)
	task.spawn(function()
		local runOk, runError = pcall(qolState.ServerNavigation.RunJoinFriend, rawIdentifier)
		if not runOk then
			qolState.ServerNavigation.SetBusy(false)
			qolState.ServerNavigation.SetStatus("Join player failed: " .. tostring(runError), colors.DangerHover)
		end
	end)
	return true
end

function qolState.ServerNavigation.RunJoinFriend(rawIdentifier)
	do
		qolState.ServerNavigation.SetStatus("Looking up player...", colors.Warning)
		local userId, resolveError = qolState.ServerNavigation.ResolveUserId(tostring(rawIdentifier or ""))
		if not userId then
			qolState.ServerNavigation.SetBusy(false)
			qolState.ServerNavigation.SetStatus(resolveError or "Could not resolve that username.", colors.DangerHover)
			return
		end
		if userId == localPlayer.UserId then
			qolState.ServerNavigation.SetBusy(false)
			qolState.ServerNavigation.SetStatus("You are already on this account.", colors.DangerHover)
			return
		end
		for _, player in ipairs(Players:GetPlayers()) do
			if player.UserId == userId then
				qolState.ServerNavigation.SetBusy(false)
				qolState.ServerNavigation.SetStatus("@" .. player.Name .. " is already in your server.", colors.Success)
				return
			end
		end
		local presence = qolState.ServerNavigation.FetchUserPresence(userId)
		local targetPlaceId = presence and tonumber(presence.placeId)
		local targetJobId = presence and type(presence.gameId) == "string" and presence.gameId ~= "" and presence.gameId or nil
		local targetLabel = presence and presence.userName or qolState.ServerNavigation.NormalizeFriendIdentifier(tostring(rawIdentifier or ""))
		if not targetJobId then
			qolState.ServerNavigation.SetStatus("Their server is hidden; searching public servers for @" .. targetLabel .. "...", colors.Warning)
			local foundPlaceId, foundJobId, scanError = qolState.ServerNavigation.FindUserServerByScan(userId, targetPlaceId)
			if not foundJobId then
				qolState.ServerNavigation.SetBusy(false)
				qolState.ServerNavigation.SetStatus(
					"Could not find @" .. targetLabel .. ": " .. tostring(scanError or "not in a public server of this game."),
					colors.DangerHover
				)
				return
			end
			targetPlaceId, targetJobId = foundPlaceId, foundJobId
		end
		qolState.ServerNavigation.SetStatus(
			string.format("Found @%s; joining (place %d)...", targetLabel, targetPlaceId),
			colors.Success
		)
		if not qolState.ServerNavigation.PrepareTeleport(nil, qolState.ServerNavigation.SetStatus) then
			qolState.ServerNavigation.SetBusy(false)
			return
		end
		local ok, teleportError = qolState.ServerNavigation.TeleportToUserServer(targetPlaceId, targetJobId)
		if not ok then
			qolState.ServerNavigation.SetBusy(false)
			qolState.ServerNavigation.SetStatus(
				"Join player failed: " .. tostring(teleportError),
				colors.DangerHover
			)
		else
			task.delay(12, function()
				if not unloaded then
					qolState.ServerNavigation.SetBusy(false)
				end
			end)
		end
	end
end

-- BEGIN SERVER BROWSER LOGIC
-- Native GetServerInfo("Get") returns {key=serverId,value={Name,Planet,...}}.
-- Names only decorate exact public-API IDs; native capacity/ordering is not trusted.
function qolState.ServerNavigation.ParseServerNames(records, planet)
	local names, duplicates = {}, {}
	if type(records)~="table" or type(planet)~="string" then return names end
	local function clean(value, limit)
		if type(value)~="string" then return nil end
		value=value:gsub("%c"," "):match("^%s*(.-)%s*$")
		return #value>0 and #value<=limit and value or nil
	end
	for index, record in ipairs(records) do
		if index>1000 then break end
		local data=type(record)=="table" and record.value
		local id=type(record)=="table" and record.key
		if type(id)=="string" and #id>0 and #id<=128 and id:match("^[%w%-]+$")
			and type(data)=="table" and data.Pool=="Default" and type(data.Planet)=="string"
			and data.Planet:lower()==planet:lower() then
			local name=clean(data.Name,96)
			if names[id] then duplicates[id]=true;names[id]=nil end
			if name and not duplicates[id] then names[id]={Name=name,Region=clean(data.ServerRegion,64)} end
		end
	end
	return names
end

function qolState.ServerNavigation.FetchServerNames(placeId, planet)
	local nav=qolState.ServerNavigation
	local b=nav.Browser
	b.NameSerial=(b.NameSerial or 0)+1
	local serial=b.NameSerial
	if b.NameWorker then pcall(task.cancel,b.NameWorker);b.NameWorker=nil end
	b.Names={};b.NameState="loading"
	local function alive() return not unloaded and b.NameSerial==serial and b.PlaceId==placeId and game.PlaceId==placeId end
	b.NameWorker=task.defer(function()
		local ok, records=pcall(function()
			local remote=remotes:FindFirstChild("GetServerInfo")
			if not remote or not remote:IsA("RemoteFunction") then error("Name lookup unavailable here") end
			return remote.InvokeServer(remote,"Get")
		end)
		if not alive() then return end
		b.NameWorker=nil
		b.Names=ok and nav.ParseServerNames(records,planet) or {}
		b.NameState=next(b.Names) and "ready" or "unavailable"
		nav.RenderServers()
	end)
	task.delay(8,function()
		if not alive() or b.NameState~="loading" then return end
		b.NameSerial+=1;b.NameState="unavailable"
		if b.NameWorker then pcall(task.cancel,b.NameWorker);b.NameWorker=nil end
		nav.RenderServers()
	end)
end

function qolState.ServerNavigation.ClearServerRows()
	local b = qolState.ServerNavigation.Browser
	for _, connection in ipairs(b.RowConnections) do connection:Disconnect() end
	table.clear(b.RowConnections)
	for _, child in ipairs(b.List:GetChildren()) do if child:IsA("Frame") then child:Destroy() end end
end

function qolState.ServerNavigation.RenderServers()
	local nav = qolState.ServerNavigation
	local b = nav.Browser
	if unloaded then return end
	nav.ClearServerRows()
	for index, row in ipairs(b.Rows) do
		local current = row.id == game.JobId
		local full = row.playing >= row.maxPlayers
		local metadata=b.Names and b.Names[row.id]
		local title=metadata and metadata.Name or (b.NameState=="loading" and "Loading server name..." or "Name unavailable")
		local detail=string.format("%s // %d/%d players // %s",metadata and metadata.Region or "Region unknown",row.playing,row.maxPlayers,row.id:sub(1,8))
		local frame = create("Frame", {Name="Server", LayoutOrder=index, Size=UDim2.new(1,-8,0,52),
			BackgroundColor3=colors.SurfaceRaised, BorderSizePixel=0}, b.List)
		create("UICorner", {CornerRadius=UDim.new(0,5)}, frame)
		create("TextLabel", {Name="ServerName",Position=UDim2.fromOffset(8,4), Size=UDim2.new(1,-86,0,21), BackgroundTransparency=1,
			Font=Enum.Font.GothamSemibold, Text=title, RichText=false,
			TextSize=11, TextColor3=colors.Text, TextXAlignment=Enum.TextXAlignment.Left, TextTruncate=Enum.TextTruncate.AtEnd},frame)
		create("TextLabel", {Name="ServerDetails",Position=UDim2.fromOffset(8,26), Size=UDim2.new(1,-86,0,20), BackgroundTransparency=1,
			Font=Enum.Font.Gotham, Text=detail, RichText=false,
			TextSize=10, TextColor3=colors.Muted, TextXAlignment=Enum.TextXAlignment.Left, TextTruncate=Enum.TextTruncate.AtEnd},frame)
		-- Transient rows own their connections instead of adding contrast
		-- watchers to the hub-wide lifetime list on every refresh.
		local button=Instance.new("TextButton")
		for property,value in pairs({Name="JoinListedServer",Position=UDim2.new(1,-76,0,12), Size=UDim2.fromOffset(70,28),
			AutoButtonColor=false, BackgroundColor3=(current or full) and colors.Surface or colors.Accent,
			Font=Enum.Font.GothamBold, Text=current and "CURRENT" or (full and "FULL" or "JOIN"),
			TextSize=9, TextColor3=(current or full) and colors.Muted or colors.Background, BorderSizePixel=0,
			Active=not current and not full}) do button[property]=value end
		button.Parent=frame
		create("UICorner", {CornerRadius=UDim.new(0,5)},button)
		if not current and not full then
			table.insert(b.RowConnections,button.Activated:Connect(function() nav.JoinListedServer(row.id) end))
		end
	end
	b.More.Visible = type(b.Cursor)=="string" and b.Cursor~="" and #b.Rows<500
	b.More.Active = not b.Busy
	b.Refresh.Active = not b.Busy
	b.Refresh.Text = b.Busy and "LOADING..." or "REFRESH"
end

function qolState.ServerNavigation.MergeServerPage(page, placeId)
	local b = qolState.ServerNavigation.Browser
	if placeId~=game.PlaceId or b.PlaceId~=placeId or type(page)~="table" or type(page.data)~="table" then return false end
	for _, row in ipairs(page.data) do
		if #b.Rows>=500 then break end
		if type(row)=="table" and type(row.id)=="string" and #row.id>0 and #row.id<=128
			and row.id:match("^[%w%-]+$")
			and not b.Seen[row.id] and type(row.playing)=="number" and type(row.maxPlayers)=="number"
			and row.playing>=0 and row.playing<math.huge and row.maxPlayers>0 and row.maxPlayers<math.huge
			and row.playing%1==0 and row.maxPlayers%1==0 then
			b.Seen[row.id]=true
			table.insert(b.Rows,{id=row.id,playing=row.playing,maxPlayers=row.maxPlayers})
		end
	end
	local cursor = page.nextPageCursor
	b.Cursors=b.Cursors or {}
	b.Cursor = type(cursor)=="string" and cursor~="" and not b.Cursors[cursor] and cursor or nil
	if b.Cursor then b.Cursors[b.Cursor]=true end
	b.Loaded=true
	return true
end

function qolState.ServerNavigation.RefreshServerList(loadMore)
	local nav = qolState.ServerNavigation
	local b = nav.Browser
	if unloaded or b.Busy then return false end
	local now = os.clock()
	if b.LastRequest and now-b.LastRequest<2 then return false end
	if loadMore and (not b.Cursor or #b.Rows>=500 or b.PlaceId~=game.PlaceId) then return false end
	b.LastRequest, b.Busy = now, true
	b.Serial += 1
	local serial, placeId = b.Serial, game.PlaceId
	if not loadMore then
		b.Rows, b.Seen, b.Cursor, b.Loaded, b.Cursors = {}, {}, nil, false, {}
		b.PlaceId=placeId
		b.List.CanvasPosition=Vector2.zero
		nav.FetchServerNames(placeId,currentPlanet)
	end
	local cursor = b.Cursor
	b.Status.Text="Loading public "..tostring(currentPlanet).." servers..."
	nav.RenderServers()
	local function alive() return not unloaded and serial==b.Serial and game.PlaceId==placeId end
	b.Worker=task.defer(function()
		local ok, page=pcall(function()
			local url=string.format("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&excludeFullGames=false&limit=100",placeId)
			if cursor then url..="&cursor="..HttpService:UrlEncode(cursor) end
			return npcSafety.HttpGetJson(url)
		end)
		if not alive() then return end
		b.Worker, b.Busy=nil,false
		if ok and nav.MergeServerPage(page,placeId) then
			b.Status.Text=string.format("%s // %d servers%s",tostring(currentPlanet),#b.Rows,
				#b.Rows>=500 and " (limit; refresh for latest)" or (#b.Rows==0 and " found" or " shown"))
		else b.Status.Text="Server list unavailable; try Refresh." end
		nav.RenderServers()
	end)
	task.delay(20,function()
		if not alive() or not b.Busy then return end
		b.Serial+=1;b.Busy=false
		if b.Worker then pcall(task.cancel,b.Worker);b.Worker=nil end
		b.Status.Text="Server list timed out; try Refresh."
		nav.RenderServers()
	end)
	return true
end

function qolState.ServerNavigation.JoinListedServer(jobId)
	local nav = qolState.ServerNavigation
	local b = nav.Browser
	if unloaded or nav.Busy or b.PlaceId~=game.PlaceId or jobId==game.JobId then return false end
	local destination
	for _, row in ipairs(b.Rows) do if row.id==jobId then destination=row;break end end
	if not destination or destination.playing>=destination.maxPlayers then return false end
	local placeId=game.PlaceId
	nav.SetBusy(true)
	task.spawn(function()
		if unloaded then return end
		local ok, reason=pcall(function()
			if not nav.PrepareTeleport(nil,nav.SetStatus) then error("Could not prepare teleport") end
			if unloaded or game.PlaceId~=placeId then return end
			TeleportService:TeleportToPlaceInstance(placeId,jobId,localPlayer)
		end)
		if unloaded then return end
		if not ok then nav.SetBusy(false);nav.SetStatus("Join failed; refresh the server list.",colors.DangerHover)
		else
			nav.SetStatus("Joining selected server...",colors.Success)
			task.delay(12,function() if not unloaded then nav.SetBusy(false) end end)
		end
	end)
	return true
end

function qolState.ServerNavigation.StopServerBrowser()
	local b=qolState.ServerNavigation.Browser
	b.Serial+=1;b.Busy=false
	if b.Worker then pcall(task.cancel,b.Worker);b.Worker=nil end
	b.NameSerial=(b.NameSerial or 0)+1;b.NameState="unavailable";b.Names={}
	if b.NameWorker then pcall(task.cancel,b.NameWorker);b.NameWorker=nil end
	qolState.ServerNavigation.ClearServerRows()
end

connect(qolState.ServerNavigation.Browser.Refresh.Activated,function() qolState.ServerNavigation.RefreshServerList(false) end)
connect(qolState.ServerNavigation.Browser.More.Activated,function() qolState.ServerNavigation.RefreshServerList(true) end)
-- END SERVER BROWSER LOGIC

function qolState.ServerNavigation.FetchServers(sortOrder,maxPages)
	local candidates={}
	local seen={}
	local cursor=nil
	for _=1,math.clamp(tonumber(maxPages) or 3,1,10) do
		local url=string.format(
			"https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=%s&excludeFullGames=true&limit=100",
			game.PlaceId,
			sortOrder=="Desc" and "Desc" or "Asc"
		)
		if cursor then url..="&cursor="..HttpService:UrlEncode(cursor) end
		local page=npcSafety.HttpGetJson(url)
		if type(page)~="table" or type(page.data)~="table" then break end
		for _,server in ipairs(page.data) do
			if type(server)=="table" and type(server.id)=="string" and server.id~=game.JobId and not seen[server.id]
				and type(server.playing)=="number" and type(server.maxPlayers)=="number" and server.playing<server.maxPlayers then
				seen[server.id]=true
				table.insert(candidates,server)
			end
		end
		cursor=page.nextPageCursor
		if type(cursor)~="string" or cursor=="" then break end
	end
	return candidates
end

function qolState.ServerNavigation.FindServer(mode)
	mode=string.lower(tostring(mode or "random"))
	local sortOrder=mode=="highest" and "Desc" or "Asc"
	if mode=="random" and math.random(1,2)==2 then sortOrder="Desc" end
	local candidates=qolState.ServerNavigation.FetchServers(sortOrder,3)
	if #candidates==0 then return nil,0 end
	if mode=="random" then return candidates[math.random(1,#candidates)],#candidates end
	table.sort(candidates,function(a,b)
		if a.playing~=b.playing then
			if mode=="highest" then return a.playing>b.playing end
			return a.playing<b.playing
		end
		local aPing=type(a.ping)=="number" and a.ping or math.huge
		local bPing=type(b.ping)=="number" and b.ping or math.huge
		return aPing<bPing
	end)
	return candidates[1],#candidates
end

function qolState.ServerNavigation.Rejoin()
	if qolState.ServerNavigation.Busy then return false end
	qolState.ServerNavigation.SetBusy(true)
	task.spawn(function()
		qolState.ServerNavigation.SetStatus("Preparing safe rejoin...",colors.Warning)
		if not qolState.ServerNavigation.PrepareTeleport(nil,qolState.ServerNavigation.SetStatus) then
			qolState.ServerNavigation.SetBusy(false)
			return
		end
		local ok=pcall(function()
			if type(game.JobId)=="string" and game.JobId~="" then
				TeleportService:TeleportToPlaceInstance(game.PlaceId,game.JobId,localPlayer)
			else
				TeleportService:Teleport(game.PlaceId,localPlayer)
			end
		end)
		if not ok then
			qolState.ServerNavigation.SetBusy(false)
			qolState.ServerNavigation.SetStatus("Rejoin request failed.",colors.DangerHover)
		else
			task.delay(12,function() if not unloaded then qolState.ServerNavigation.SetBusy(false) end end)
		end
	end)
	return true
end

function qolState.ServerNavigation.Hop(mode)
	if qolState.ServerNavigation.Busy then return false end
	mode=string.lower(tostring(mode or "random"))
	if mode~="random" and mode~="highest" and mode~="lowest" then return false end
	qolState.ServerNavigation.SetBusy(true)
	qolState.ServerNavigation.SetStatus("Scanning public "..tostring(currentPlanet).." servers...",colors.Warning)
	task.spawn(function()
		local destination,count=qolState.ServerNavigation.FindServer(mode)
		if not destination then
			qolState.ServerNavigation.SetBusy(false)
			qolState.ServerNavigation.SetStatus("No different non-full server was found.",colors.DangerHover)
			return
		end
		local pingText=type(destination.ping)=="number" and string.format("%.0f ms",destination.ping) or "unknown ping"
		qolState.ServerNavigation.SetStatus(string.format(
			"%s route: %d/%d players, %s  //  %d checked",
			string.upper(mode),destination.playing,destination.maxPlayers,pingText,count
		),colors.Success)
		if not qolState.ServerNavigation.PrepareTeleport(nil,qolState.ServerNavigation.SetStatus) then
			qolState.ServerNavigation.SetBusy(false)
			return
		end
		local ok=pcall(TeleportService.TeleportToPlaceInstance,TeleportService,game.PlaceId,destination.id,localPlayer)
		if not ok then
			qolState.ServerNavigation.SetBusy(false)
			qolState.ServerNavigation.SetStatus("Server teleport request failed.",colors.DangerHover)
		else
			task.delay(12,function() if not unloaded then qolState.ServerNavigation.SetBusy(false) end end)
		end
	end)
	return true
end

connect(qolState.ServerNavigation.Buttons.Rejoin.Activated,qolState.ServerNavigation.Rejoin)
connect(qolState.ServerNavigation.Buttons.Random.Activated,function() qolState.ServerNavigation.Hop("random") end)
connect(qolState.ServerNavigation.Buttons.Highest.Activated,function() qolState.ServerNavigation.Hop("highest") end)
