function npcSafety.SetServerHopEnabled(enabled)
	if type(enabled) ~= "boolean" then
		return false
	end
	npcSafety.ServerHopEnabled = enabled
	npcSafety.ServerHopButton.Text = enabled and "Server Hop: ON" or "Server Hop: OFF"
	npcSafety.ServerHopButton.BackgroundColor3 = enabled and colors.Accent or colors.Surface
	npcSafety.ServerHopButton.TextColor3 = enabled and colors.Text or colors.Muted
	return true
end

function npcSafety.IsCombatActive()
	local now = os.clock()
	local character = localPlayer.Character
	local activeTargetStillRelevant = activeNpcTarget
		and (isLivingNpcOfType(activeNpcTarget, selectedNpcType)
			or npcSafety.IsKnocked(activeNpcTarget))
	local recentAttack = npcSafety.LastAttackInputAt > 0
		and now - npcSafety.LastAttackInputAt <= 5
	local recentCombatStart = npcSafety.TargetCombatStartedAt > 0
		and now - npcSafety.TargetCombatStartedAt <= 8
	local combatMarker = character and (
		character:FindFirstChild("Combat")
		or character:FindFirstChild("Attacking")
		or character:FindFirstChild("Gripping")
	)
	-- The live client exposes combat logging protection as a character attribute,
	-- not a child instance. Keep the player at the evade point while it is true.
	local combatAttribute = character and character:GetAttribute("State_InCombat") == true
	return activeTargetStillRelevant == true
		or recentAttack
		or recentCombatStart
		or npcSafety.GripMode
		or npcSafety.LootMode
		or npcSafety.RecoveryMode
		or combatMarker ~= nil
		or combatAttribute
end

function npcSafety.FinishPlayerEvade(message)
	npcSafety.PlayerEvadeMode = false
	npcSafety.PlayerEvadePosition = nil
	npcSafety.PlayerEvadeThreatPlayer = nil
	npcSafety.PlayerEvadeThreatNpc = nil
	npcSafety.PlayerEvadeStartedAt = 0
	npcSafety.CombatClearSince = 0
	npcSafety.PendingServerHopReason = nil
	clearNpcConstraintRig()
	if npcTargetingEnabled then
		npcAcquireElapsed = 1
	end
	if message then
		setNpcStatus(message, colors.Muted)
	end
end

function npcSafety.FinishHideMode(message, keepTarget)
	npcSafety.HideMode = false
	npcSafety.HideModePlayer = nil
	npcSafety.HideModePosition = nil
	npcSafety.HideModeStartedAt = 0
	npcSafety.HideClearSince = 0
	npcSafety.HideServerHopTriggered = false
	if not keepTarget then clearNpcConstraintRig() end
	npcAcquireElapsed = 1
	if message then
		setNpcStatus(message, colors.Success)
	end
end

function npcSafety.TryRetargetAfterHide()
	if not selectedNpcType then
		return false
	end
	local characterRoot = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
	local origin = characterRoot and characterRoot.Position or Vector3.zero
	local nearest, distance, _, contestedCount, targetPower = findNearestNpc(selectedNpcType)
	if nearest and attachToNpc(nearest) then
		npcSafety.FinishHideMode(
			selectedNpcType == npcSafety.StrongestOptionName
				and string.format("Hide: switched to safe strongest %s (%.0f PL, %.0f studs).", nearest.Name, targetPower or 0, distance)
				or string.format("Hide: switched to safe %s (%.0f studs away).", nearest.Name, distance),
			true
		)
		-- The old threat belongs to the abandoned spot, not this safe target.
		npcSafety.UpdatePlayerProximityThreat()
		return true
	end
	if contestedCount and contestedCount > 0 then
		npcSafety.SpawnWaitReason = string.format(
			"No uncontested %s (%d contested); seeking another server or spawn...",
			tostring(selectedNpcType),
			contestedCount
		)
		if npcSafety.ServerHopEnabled and not npcSafety.HideServerHopTriggered then
			npcSafety.HideServerHopTriggered = true
			npcSafety.RequestServerHop(npcSafety.SpawnWaitReason, npcSafety.ProximityThreatPlayer)
		end
		return false
	end
	npcSafety.SpawnDestination, npcSafety.SpawnSource = npcSafety.FindSpawnAnchor(selectedNpcType, origin)
	if npcSafety.SpawnDestination then
		npcSafety.FinishHideMode(
			string.format("Hide: routing underground to %s for %s...", npcSafety.SpawnSource or "spawn", selectedNpcType)
		)
		npcAcquireElapsed = 1
		return true
	end
	setNpcStatus(
		string.format("Hide: scanning for safe %s (none uncontested yet)...", tostring(selectedNpcType)),
		colors.Warning
	)
	return false
end

function npcSafety.BeginHideMode(detectedPlayer, reason)
	if npcSafety.HideMode then
		if detectedPlayer then
			npcSafety.HideModePlayer = detectedPlayer
		end
		return true
	end
	local character = localPlayer.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local characterRoot = character and character:FindFirstChild("HumanoidRootPart")
	if not humanoid or humanoid.Health <= 0 or not characterRoot then
		return false
	end
	clearNpcConstraintRig()
	activeNpcTarget = nil
	npcSafety.SpawnDestination = nil
	npcSafety.SpawnSource = nil
	npcSafety.GripMode = false
	npcSafety.GripTarget = nil
	npcSafety.LootMode = false
	npcAttackElapsed = 0
	local groundY = getGroundYAt(characterRoot.Position, character)
	local hideY = groundY and groundY - npcSafety.RecoveryDepth
		or characterRoot.Position.Y - npcSafety.RecoveryDepth
	npcSafety.HideModePosition = Vector3.new(characterRoot.Position.X, hideY, characterRoot.Position.Z)
	npcSafety.HideMode = true
	npcSafety.HideModePlayer = detectedPlayer
	npcSafety.HideModeStartedAt = os.clock()
	npcSafety.HideClearSince = 0
	npcSafety.HideServerHopTriggered = false
	applyNpcNoclip(character, true)
	npcSafety.EnsureMovementRig(character, humanoid, characterRoot)
	if configStore.FeatureAccess.UpdatedAutofarm then
		characterRoot.CFrame = CFrame.new(npcSafety.HideModePosition) * characterRoot.CFrame.Rotation
		characterRoot.AssemblyLinearVelocity = Vector3.zero
		characterRoot.AssemblyAngularVelocity = Vector3.zero
	end
	local distance = npcSafety.ProximityThreatDistance or npcSafety.PlayerRange
	setNpcStatus(
		string.format(
			"Hide mode: @%s near %s (%.0f studs). Finding safe %s...",
			detectedPlayer and detectedPlayer.Name or "player",
			tostring(npcSafety.ProximityWatchAnchor or "farm spot"),
			distance,
			tostring(selectedNpcType)
		),
		colors.DangerHover
	)
	npcSafety.LastHideRetargetAt = 0
	npcSafety.TryRetargetAfterHide()
	return true
end

function npcSafety.UpdateHideMode(character, humanoid, characterRoot)
	local threat = npcSafety.ProximityThreatPlayer
	if npcSafety.ShouldEnterHideMode(characterRoot) then
		npcSafety.BeginHideMode(threat, "player watch breach")
	end
	if not npcSafety.HideMode then
		return false
	end
	if not threat and not activeNpcTarget then
		if npcSafety.HideClearSince == 0 then
			npcSafety.HideClearSince = os.clock()
		elseif os.clock() - npcSafety.HideClearSince >= npcSafety.HideModeClearHold then
			npcSafety.FinishHideMode("Watch range clear; resuming autofarm...")
			return false
		end
	elseif threat then
		npcSafety.HideClearSince = 0
		npcSafety.HideModePlayer = threat
	end
	local now = os.clock()
	if now - npcSafety.LastHideRetargetAt >= npcSafety.HideRetargetInterval then
		npcSafety.LastHideRetargetAt = now
		if npcSafety.TryRetargetAfterHide() then
			return false
		end
	end
	if activeNpcTarget then
		npcSafety.FinishHideMode(nil, true)
		return false
	end
	applyNpcNoclip(character, true)
	npcSafety.EnsureMovementRig(character, humanoid, characterRoot)
	local destination = npcSafety.HideModePosition or characterRoot.Position
	local movementDelta = destination - characterRoot.Position
	local movementDistance = movementDelta.Magnitude
	if npcLinearVelocity then
		npcLinearVelocity.Enabled = true
		if configStore.FeatureAccess.UpdatedAutofarm and movementDistance > 0.35 then
			characterRoot.CFrame = CFrame.new(destination) * characterRoot.CFrame.Rotation
			characterRoot.AssemblyLinearVelocity = Vector3.zero
			characterRoot.AssemblyAngularVelocity = Vector3.zero
			npcLinearVelocity.VectorVelocity = Vector3.zero
		else
			npcLinearVelocity.VectorVelocity = movementDistance > 0.35
				and movementDelta.Unit * math.min(400, math.max(40, movementDistance * 3))
				or Vector3.zero
		end
	end
	humanoid.PlatformStand = true
	return false
end

function qolState.ServerNavigation.SetAutoBlockPlayers(enabled)
	if type(enabled) ~= "boolean" then return false end
	qolState.ServerNavigation.AutoBlockPlayers = enabled
	qolState.ServerNavigation.AutoBlockButton.Text = enabled
		and "AUTO BLOCK PLAYERS BEFORE HOP: ON"
		or "AUTO BLOCK PLAYERS BEFORE HOP: OFF"
	qolState.ServerNavigation.AutoBlockButton.BackgroundColor3 = enabled and colors.Accent or colors.Surface
	qolState.ServerNavigation.AutoBlockButton.TextColor3 = enabled and colors.Background or colors.Muted
	return true
end

function qolState.ServerNavigation.GetQueueFunction()
	if type(environment.queue_on_teleport) == "function" then return environment.queue_on_teleport end
	if type(environment.queueonteleport) == "function" then return environment.queueonteleport end
	if type(environment.syn) == "table" and type(environment.syn.queue_on_teleport) == "function" then
		return environment.syn.queue_on_teleport
	end
	return nil
end

function qolState.ServerNavigation.QueueSelfForTeleport()
	if qolState.ServerNavigation.TeleportQueueArmed then return true end
	local queueFunction = qolState.ServerNavigation.GetQueueFunction()
	local loaderUrl = environment.__GohanHubLoaderUrl
	-- Runs in the destination only; never sleeps during injection or queuing.
	local reloadDelay = "if not game:IsLoaded() then game.Loaded:Wait() end;task.wait(10);"
	if queueFunction and type(loaderUrl) == "string" and string.match(loaderUrl, "^https://") then
		local ok = pcall(queueFunction, reloadDelay .. "loadstring(game:HttpGet(" .. string.format("%q", loaderUrl) .. "))()")
		if ok then qolState.ServerNavigation.TeleportQueueArmed = true end
		if ok then
			return true
		end
		return false, "The executor rejected the teleport queue request."
	end
	local source = environment.__GohanHubSource
	if not queueFunction or type(source) ~= "string" or #source < 1000 then
		return false, "The executor teleport queue or self-source is unavailable."
	end
	local queuedSource = reloadDelay .. "local e=(getgenv and getgenv()) or shared;local s="
		.. string.format("%q", source)
		.. ";e.__GohanHubSource=s;local f,er=loadstring(s);if f then f() else warn('[GohanHub Queue] '..tostring(er)) end"
	local ok = pcall(queueFunction, queuedSource)
	if ok then qolState.ServerNavigation.TeleportQueueArmed = true end
	if ok then
		return true
	end
	return false, "The executor rejected the teleport queue request."
end

function qolState.ServerNavigation.BlockPlayerProfile(player)
	if not player or player == localPlayer or player.UserId <= 0 then return true end
	if type(environment.__GohanHubBlockedUserIds) ~= "table" then environment.__GohanHubBlockedUserIds = {} end
	if environment.__GohanHubBlockedUserIds[player.UserId] then return true end
	local httpRbxApiService = game:GetService("HttpRbxApiService")
	local ok, response = pcall(httpRbxApiService.PostAsyncFullUrl, httpRbxApiService,
		"https://apis.roblox.com/user-blocking-api/v1/users/" .. tostring(player.UserId) .. "/block-user", "")
	local accepted = false
	if ok and type(response) == "string" and response ~= "" then
		local decodedOk, decoded = pcall(HttpService.JSONDecode, HttpService, response)
		accepted = decodedOk and type(decoded) == "table" and decoded.errors == nil
	end
	if accepted then
		environment.__GohanHubBlockedUserIds[player.UserId] = true
		local blockListRemote = game:GetService("RobloxReplicatedStorage"):FindFirstChild("UpdatePlayerBlockList")
		if blockListRemote then pcall(blockListRemote.FireServer, blockListRemote, player.UserId, true) end
		return true
	end
	-- Fallback to Roblox's official confirmation prompt. The hop stays paused
	-- until PlayerBlockedEvent confirms the profile was genuinely blocked.
	local blockedEvent
	pcall(function() blockedEvent = game:GetService("StarterGui"):GetCore("PlayerBlockedEvent") end)
	local confirmed = false
	local promptConnection
	if blockedEvent and blockedEvent.Event then
		promptConnection = blockedEvent.Event:Connect(function(blockedPlayer)
			if blockedPlayer == player then confirmed = true end
		end)
	end
	pcall(game:GetService("StarterGui").SetCore, game:GetService("StarterGui"), "PromptBlockPlayer", player)
	local deadline = os.clock() + 15
	while not confirmed and os.clock() < deadline and player.Parent do task.wait(0.1) end
	if promptConnection then promptConnection:Disconnect() end
	if confirmed then environment.__GohanHubBlockedUserIds[player.UserId] = true end
	return confirmed
end

function qolState.ServerNavigation.BlockPlayersBeforeTeleport(priorityPlayer, statusCallback)
	if not qolState.ServerNavigation.AutoBlockPlayers then return true end
	local targets, seen = {}, {}
	local function add(player)
		if player and player ~= localPlayer and player.UserId > 0 and not seen[player.UserId] then
			seen[player.UserId] = true
			table.insert(targets, player)
		end
	end
	add(priorityPlayer)
	for _, player in ipairs(Players:GetPlayers()) do add(player) end
	if #targets == 0 then return true end
	qolState.ServerNavigation.BlockingBusy = true
	for index, player in ipairs(targets) do
		if type(statusCallback) == "function" then
			statusCallback(string.format("Blocking @%s before hop (%d/%d)...", player.Name, index, #targets), colors.Warning)
		end
		if not qolState.ServerNavigation.BlockPlayerProfile(player) then
			qolState.ServerNavigation.BlockingBusy = false
			if type(statusCallback) == "function" then
				statusCallback("Could not confirm @" .. player.Name .. " was blocked; server hop cancelled.", colors.DangerHover)
			end
			return false
		end
		task.wait(0.1)
	end
	qolState.ServerNavigation.BlockingBusy = false
	return true
end

function qolState.ServerNavigation.PrepareTeleport(priorityPlayer, statusCallback)
	if not qolState.ServerNavigation.BlockPlayersBeforeTeleport(priorityPlayer, statusCallback) then return false end
	local queued, queueError = qolState.ServerNavigation.QueueSelfForTeleport()
	if not queued then
		if type(statusCallback) == "function" then
			statusCallback(queueError or "Could not queue the hub after teleport.", colors.DangerHover)
		end
		return false
	end
	return true
end

connect(qolState.ServerNavigation.AutoBlockButton.Activated,function()
	qolState.ServerNavigation.SetAutoBlockPlayers(not qolState.ServerNavigation.AutoBlockPlayers)
end)
qolState.ServerNavigation.SetAutoBlockPlayers(qolState.ServerNavigation.AutoBlockPlayers)

function npcSafety.BeginPlayerEvade(detectedPlayer, reason)
	if npcSafety.PlayerEvadeMode then
		if detectedPlayer then
			npcSafety.PlayerEvadeThreatPlayer = detectedPlayer
		end
		npcSafety.PendingServerHopReason = reason or npcSafety.PendingServerHopReason
		return true
	end
	local character = localPlayer.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local characterRoot = character and character:FindFirstChild("HumanoidRootPart")
	if not humanoid or humanoid.Health <= 0 or not characterRoot then
		return false
	end
	local threatNpc = activeNpcTarget
	local threatRoot = detectedPlayer and detectedPlayer.Character
		and (detectedPlayer.Character:FindFirstChild("HumanoidRootPart")
			or detectedPlayer.Character:FindFirstChild("UpperTorso")
			or detectedPlayer.Character:FindFirstChild("Torso"))
	local npcRoot = threatNpc and getNpcRoot(threatNpc)
	local threatPosition = threatRoot and threatRoot.Position or npcRoot and npcRoot.Position
	local away = threatPosition and (characterRoot.Position - threatPosition) or characterRoot.CFrame.RightVector
	away = Vector3.new(away.X, 0, away.Z)
	if away.Magnitude < 1 then
		away = Vector3.new(characterRoot.CFrame.RightVector.X, 0, characterRoot.CFrame.RightVector.Z)
	end
	if away.Magnitude < 1 then
		away = Vector3.new(1, 0, 0)
	end
	local escapeDistance = math.max(npcSafety.PlayerEvadeDistance, npcSafety.PlayerRange + 250)
	local escapeY = math.max(characterRoot.Position.Y + 100,
		threatPosition and threatPosition.Y + 100 or characterRoot.Position.Y + 100)

	clearNpcConstraintRig()
	npcSafety.ResetPostCombat()
	npcSafety.RecoveryMode = false
	npcSafety.RecoveryPosition = nil
	npcSafety.RecoveryResumeRatio = nil
	npcSafety.PlayerEvadeMode = true
	npcSafety.PlayerEvadeThreatPlayer = detectedPlayer
	npcSafety.PlayerEvadeThreatNpc = threatNpc
	npcSafety.PlayerEvadeStartedAt = os.clock()
	npcSafety.CombatClearSince = 0
	npcSafety.PendingServerHopReason = reason or "player proximity"
	npcSafety.PlayerEvadePosition = Vector3.new(
		characterRoot.Position.X + away.Unit.X * escapeDistance,
		escapeY,
		characterRoot.Position.Z + away.Unit.Z * escapeDistance
	)
	applyNpcNoclip(character, true)
	npcSafety.EnsureMovementRig(character, humanoid, characterRoot)
	npcAttackElapsed = 0
	setNpcStatus("Player detected during combat; disengaging and moving away before the lowest-population hop...", colors.DangerHover)
	return true
end

function npcSafety.UpdatePlayerEvade(character, humanoid, characterRoot)
	if not npcSafety.PlayerEvadeMode then
		return false
	end
	applyNpcNoclip(character, true)
	npcSafety.EnsureMovementRig(character, humanoid, characterRoot)
	local destination = npcSafety.PlayerEvadePosition or characterRoot.Position
	local movementDelta = destination - characterRoot.Position
	local movementDistance = movementDelta.Magnitude
	if npcLinearVelocity then
		npcLinearVelocity.Enabled = true
		npcLinearVelocity.VectorVelocity = movementDistance > 1
			and movementDelta.Unit * math.min(500, math.max(60, movementDistance * 2.5))
			or Vector3.zero
	end
	if npcAlignOrientation then
		npcAlignOrientation.Enabled = true
	end
	humanoid.PlatformStand = true

	local now = os.clock()
	local elapsed = now - npcSafety.PlayerEvadeStartedAt
	if npcSafety.IsCombatActive() then
		npcSafety.CombatClearSince = 0
		if elapsed >= npcSafety.PlayerEvadeMinimumDuration then
			setNpcStatus("Still in combat; holding at the safe spot before hopping...", colors.Warning)
		end
	elseif elapsed >= npcSafety.PlayerEvadeMinimumDuration then
		if npcSafety.CombatClearSince == 0 then
			npcSafety.CombatClearSince = now
		end
		local clearedFor = now - npcSafety.CombatClearSince
		if clearedFor >= npcSafety.CombatClearHoldDuration and not npcSafety.ServerHopBusy then
			setNpcStatus("Combat cleared; requesting the smallest available server...", colors.Success)
			npcSafety.RequestServerHop(npcSafety.PendingServerHopReason or "player proximity", nil, true)
		else
			setNpcStatus(string.format("Combat clear; holding safe for %.1fs before hopping...",
				math.max(0, npcSafety.CombatClearHoldDuration - clearedFor)), colors.Success)
		end
	end
	return true
end

function npcSafety.RequestServerHop(reason, detectedPlayer, skipEvade)
	local now = os.clock()
	if npcSafety.IsCombatActive() then
		if not skipEvade then
			return npcSafety.BeginPlayerEvade(detectedPlayer, reason)
		end
		if now - npcSafety.LastCombatHopNoticeAt >= 2 then
			npcSafety.LastCombatHopNoticeAt = now
			setNpcStatus("Still in combat; continuing escape before server hop.", colors.Muted)
		end
		return false
	end
	if npcSafety.ServerHopBusy or now - npcSafety.LastServerHopAt < 20 then
		return false
	end
	npcSafety.ServerHopBusy = true
	npcSafety.LastServerHopAt = now
	setNpcStatus("Player nearby; finding a low-population, low-ping server...", colors.DangerHover)
	task.spawn(function()
		local candidates = {}
		local cursor = nil
		for _ = 1, 3 do
			local url = string.format(
				"https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&excludeFullGames=true&limit=100",
				game.PlaceId
			)
			if cursor then
				url ..= "&cursor=" .. HttpService:UrlEncode(cursor)
			end
			local page = npcSafety.HttpGetJson(url)
			if type(page) ~= "table" or type(page.data) ~= "table" then
				break
			end
			for _, server in ipairs(page.data) do
				if type(server) == "table" and type(server.id) == "string" and server.id ~= game.JobId
					and type(server.playing) == "number" and type(server.maxPlayers) == "number"
					and server.playing < server.maxPlayers then
					table.insert(candidates, server)
				end
			end
			cursor = page.nextPageCursor
			if type(cursor) ~= "string" or cursor == "" then
				break
			end
		end

		table.sort(candidates, function(a, b)
			if a.playing ~= b.playing then
				return a.playing < b.playing
			end
			local aPing = type(a.ping) == "number" and a.ping or math.huge
			local bPing = type(b.ping) == "number" and b.ping or math.huge
			return aPing < bPing
		end)
		local destination = candidates[1]
		if destination then
			-- Combat can begin while the HTTP server search is in progress. Recheck
			-- immediately before teleporting so an in-flight request cannot hop out
			-- of a fight.
			if npcSafety.IsCombatActive() then
				npcSafety.ServerHopBusy = false
				npcSafety.LastServerHopAt = 0
				setNpcStatus("Combat returned; continuing escape before server hop.", colors.Muted)
				return
			end
			if not qolState.ServerNavigation.PrepareTeleport(detectedPlayer, setNpcStatus) then
				npcSafety.ServerHopBusy = false
				npcSafety.LastServerHopAt = 0
				if npcSafety.PlayerEvadeMode then
					npcSafety.FinishPlayerEvade("Player blocking or teleport queue failed; autofarm resumed safely.")
				end
				return
			end
			if npcSafety.IsCombatActive() then
				npcSafety.ServerHopBusy = false
				npcSafety.LastServerHopAt = 0
				setNpcStatus("Combat returned while blocking players; continuing escape before server hop.", colors.Muted)
				return
			end
			local pingText = type(destination.ping) == "number" and string.format("%.0f ms", destination.ping) or "unknown ping"
			setNpcStatus(string.format(
				"Hopping: %d player%s, %s (%s)",
				destination.playing,
				destination.playing == 1 and "" or "s",
				pingText,
				reason or "player proximity"
			), colors.Success)
			local teleportOk = pcall(function()
				TeleportService:TeleportToPlaceInstance(game.PlaceId, destination.id, localPlayer)
			end)
			if teleportOk then
				task.delay(12, function()
					if not unloaded then
						npcSafety.ServerHopBusy = false
						if npcSafety.PlayerEvadeMode then
							npcSafety.FinishPlayerEvade("Teleport did not complete; resumed autofarm safely.")
						end
					end
				end)
				return
			end
		end
		npcSafety.ServerHopBusy = false
		npcSafety.FinishPlayerEvade("Server hop failed; resumed autofarm and will retry on the next detection.")
	end)
	return true
end

function npcSafety.BeginRecovery(character, humanoid, characterRoot)
	local lockedRecoveryRoot = npcSafety.LockedAboveTarget and getNpcRoot(npcSafety.LockedAboveTarget)
	clearNpcConstraintRig()
	applyNpcNoclip(character)
	if npcPreviousAutoRotate == nil then
		npcPreviousAutoRotate = humanoid.AutoRotate
	end
	if npcPreviousPlatformStand == nil then
		npcPreviousPlatformStand = humanoid.PlatformStand
	end
	humanoid.AutoRotate = false
	humanoid.PlatformStand = true

	npcRootAttachment = create("Attachment", {
		Name = "DoctorNpcRootAttachment",
	}, characterRoot)
	local assemblyMass = math.max(characterRoot.AssemblyMass, 1)
	npcLinearVelocity = create("LinearVelocity", {
		Name = "DoctorNpcLinearVelocity",
		Attachment0 = npcRootAttachment,
		RelativeTo = Enum.ActuatorRelativeTo.World,
		MaxForce = math.max(90000, assemblyMass * workspace.Gravity * 12),
		VectorVelocity = Vector3.zero,
		VelocityConstraintMode = Enum.VelocityConstraintMode.Vector,
	}, characterRoot)
	npcAlignOrientation = create("AlignOrientation", {
		Name = "DoctorNpcAlignOrientation",
		Mode = Enum.OrientationAlignmentMode.OneAttachment,
		Attachment0 = npcRootAttachment,
		CFrame = CFrame.Angles(math.rad(lockedRecoveryRoot and -90 or 90), 0, 0),
		MaxAngularVelocity = 10,
		MaxTorque = math.max(90000, assemblyMass * 12000),
		Responsiveness = 16,
		RigidityEnabled = false,
	}, characterRoot)
	if lockedRecoveryRoot then
		npcSafety.RecoveryPosition = lockedRecoveryRoot.Position + Vector3.new(0, 20, 0)
	else
		local groundY = getGroundYAt(characterRoot.Position, character)
		local hidingY = groundY and groundY - npcSafety.RecoveryDepth or characterRoot.Position.Y - npcSafety.RecoveryDepth
		npcSafety.RecoveryPosition = Vector3.new(characterRoot.Position.X, hidingY, characterRoot.Position.Z)
	end
	npcSafety.RecoveryResumeRatio = math.min(1, npcSafety.PanicHealthRatio + npcSafety.RecoveryResumeBufferRatio)
	npcSafety.RecoveryMode = true
	npcAttackElapsed = 0
	setNpcStatus(string.format(lockedRecoveryRoot
		and "Panic HP active; recovering above the locked target until health reaches %.0f%%..."
		or "Panic HP active; hiding until health reaches %.0f%%...",
		npcSafety.RecoveryResumeRatio * 100), colors.DangerHover)
end

function npcSafety.UpdateProfileVisual()
	local profile = npcSafety.GetProfile(selectedNpcType)
	for _, definition in ipairs(npcSafety.TuningDefinitions) do
		local value = profile[definition.Key]
		local alpha = math.clamp((value - definition.Min) / (definition.Max - definition.Min), 0, 1)
		npcSafety.TuningFills[definition.Key].Size = UDim2.fromScale(alpha, 1)
		npcSafety.TuningKnobs[definition.Key].Position = UDim2.fromScale(alpha, 0.5)
		npcSafety.TuningValues[definition.Key].Text = definition.Decimals == 0
			and tostring(math.floor(value + 0.5))
			or string.format("%." .. definition.Decimals .. "f", value)
	end
	npcSafety.DetailsLabel.Text = selectedNpcType
		and (selectedNpcType .. " profile - values below are saved per NPC type")
		or "Choose an NPC type; values below are saved per NPC type."
end

function npcSafety.SetProfileFromSlider(definition, inputX)
	local profile = npcSafety.GetProfile(selectedNpcType)
	local track = npcSafety.TuningTracks[definition.Key]
	if track.AbsoluteSize.X > 0 then
		local alpha = math.clamp((inputX - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1)
		local raw = definition.Min + (definition.Max - definition.Min) * alpha
		profile[definition.Key] = math.clamp(math.floor(raw / definition.Step + 0.5) * definition.Step, definition.Min, definition.Max)
	end
	npcSafety.UpdateProfileVisual()
end

local npcTypeButtons = {}

local function collectNpcTypes()
	local live = getLiveFolder()
	local counts = {}
	if live then
		for _, descendant in ipairs(live:GetDescendants()) do
			if descendant:IsA("Humanoid") then
				local model = descendant.Parent
				if model and model:IsA("Model") and not Players:GetPlayerFromCharacter(model)
					and not npcSafety.IsExcludedFarmTarget(model) then
					counts[model.Name] = (counts[model.Name] or 0) + 1
				end
			end
		end
	end
	local names = {}
	for name in pairs(counts) do
		table.insert(names, name)
	end
	table.sort(names)
	return names, counts
end

local function refreshNpcTypes()
	for _, button in ipairs(npcTypeButtons) do
		button:Destroy()
	end
	table.clear(npcTypeButtons)

	local names, counts = collectNpcTypes()
	if #names > 0 and selectedNpcType ~= npcSafety.StrongestOptionName and not counts[selectedNpcType] then
		local previousSelection = selectedNpcType
		local bestName = names[1]
		for _, name in ipairs(names) do
			if counts[name] > counts[bestName] then
				bestName = name
			end
		end
		selectedNpcType = bestName
		npcSelectorButton.Text = bestName .. "  v"
		clearNpcConstraintRig()
		npcSafety.ResetPostCombat()
		npcSafety.SpawnDestination = nil
		npcSafety.SpawnSource = nil
		npcAcquireElapsed = 1
		npcSafety.UpdateProfileVisual()
		if previousSelection then
			setNpcStatus(tostring(previousSelection) .. " is unavailable on " .. getCurrentPlanet()
				.. "; switched to live target " .. bestName .. ".", colors.Success)
		end
	end
	local poweredNpcCount = 0
	local strongestPower = nil
	local live = getLiveFolder()
	if live then
		for _, descendant in ipairs(live:GetDescendants()) do
			if descendant:IsA("Humanoid") and descendant.Health > 0 then
				local model = descendant.Parent
				local power = model and model:IsA("Model") and not Players:GetPlayerFromCharacter(model)
					and npcSafety.GetNpcPowerLevel(model) or nil
				if power then
					poweredNpcCount += 1
					strongestPower = math.max(strongestPower or power, power)
				end
			end
		end
	end
	local strongestButton = create("TextButton", {
		Name = "StrongestNpc",
		LayoutOrder = 0,
		Size = UDim2.new(1, 0, 0, 34),
		AutoButtonColor = false,
		BackgroundColor3 = selectedNpcType == npcSafety.StrongestOptionName and colors.Accent or colors.AccentSoft,
		BorderSizePixel = 0,
		Font = Enum.Font.GothamSemibold,
		Text = strongestPower and string.format("Strongest NPC  (%.0f PL // %d live)", strongestPower, poweredNpcCount)
			or "Strongest NPC  (no replicated PL)",
		TextColor3 = colors.Text,
		TextSize = 11,
		TextXAlignment = Enum.TextXAlignment.Left,
		ZIndex = 31,
	}, npcDropdownList)
	create("UICorner", {CornerRadius = UDim.new(0, 5)}, strongestButton)
	create("UIPadding", {PaddingLeft = UDim.new(0, 9)}, strongestButton)
	table.insert(npcTypeButtons, strongestButton)
	connect(strongestButton.Activated, function()
		selectedNpcType = npcSafety.StrongestOptionName
		npcSelectorButton.Text = npcSafety.StrongestOptionName .. "  v"
		npcDropdownList.Visible = false
		clearNpcConstraintRig()
		npcSafety.ResetPostCombat()
		npcSafety.SpawnDestination = nil
		npcSafety.SpawnSource = nil
		npcAcquireElapsed = 1
		npcSafety.UpdateProfileVisual()
		setNpcStatus("Selected Strongest NPC. The highest safe replicated Power Level will be targeted.", colors.Success)
		refreshNpcTypes()
	end)
	for order, name in ipairs(names) do
		local button = create("TextButton", {
			Name = name,
			LayoutOrder = order,
			Size = UDim2.new(1, 0, 0, 30),
			AutoButtonColor = false,
			BackgroundColor3 = name == selectedNpcType and colors.Accent or colors.Surface,
			BorderSizePixel = 0,
			Font = Enum.Font.GothamMedium,
			Text = string.format("%s  (%d)", name, counts[name]),
			TextColor3 = colors.Text,
			TextSize = 11,
			TextXAlignment = Enum.TextXAlignment.Left,
			ZIndex = 31,
		}, npcDropdownList)
		create("UICorner", {CornerRadius = UDim.new(0, 5)}, button)
		create("UIPadding", {PaddingLeft = UDim.new(0, 9)}, button)
		table.insert(npcTypeButtons, button)
		connect(button.Activated, function()
			selectedNpcType = name
			npcSelectorButton.Text = name .. "  v"
			npcDropdownList.Visible = false
			clearNpcConstraintRig()
			npcSafety.ResetPostCombat()
			npcSafety.SpawnDestination = nil
			npcSafety.SpawnSource = nil
			npcAcquireElapsed = 1
			npcSafety.UpdateProfileVisual()
			setNpcStatus("Selected " .. name .. ". Toggle autofarm when ready.", colors.Success)
			refreshNpcTypes()
		end)
	end
	if #names == 0 then
		setNpcStatus("No NPC types are currently replicated in World.Live.", colors.DangerHover)
	end
	return #names
end

local function setNpcTargetingEnabled(enabled)
	if type(enabled) ~= "boolean" then
		return false
	end
	if enabled and npcSafety.IsExcludedFarmName(selectedNpcType) then
		selectedNpcType = npcSafety.StrongestOptionName
		npcSelectorButton.Text = selectedNpcType .. "  v"
	end
	if enabled and not selectedNpcType then
		setNpcStatus("Choose an NPC type before enabling autofarm.", colors.DangerHover)
		return false
	end

	npcTargetingEnabled = enabled
	npcToggleButton.Text = enabled and "Autofarm: ON" or "Autofarm: OFF"
	npcToggleButton.BackgroundColor3 = enabled and colors.Accent or colors.SurfaceRaised
	npcToggleButton.TextColor3 = enabled and colors.Text or colors.Muted
	if autoTransformState.Render then
		autoTransformState.Render()
	end
	npcAcquireElapsed = enabled and 1 or 0
	npcAttackElapsed = 0
	npcSafety.BurstHits = 0
	npcSafety.BurstResetUntil = 0
	npcSafety.ComboResetToken = nil
	npcSafety.LastAttackInputAt = 0
	npcSafety.PendingHit = false
	npcSafety.ObservedTargetHealth = nil
	npcSafety.LastConfirmedHitAt = 0
	npcSafety.AttackAnchorY = nil
	npcSafety.CrowdScanElapsed = 0
	npcSafety.CloseNpcCount = 0
	npcSafety.LurePoint = nil
	npcSafety.LureUntil = 0
	npcSafety.LureArrivedAt = 0
	npcSafety.NextLureSearchAt = 0
	npcSafety.CliffBadElapsed = 0
	npcSafety.PositionMode = npcSafety.SelectedPositionMode
	npcSafety.FrontBehindPhase = "Front"
	npcSafety.FrontBehindConfirmedHits = 0
	npcSafety.FrontBehindRecoverUntil = 0
	npcSafety.PreferAbove = npcSafety.SelectedPositionMode == "Above"
	npcSafety.AdaptiveFallbackActive = false
	npcSafety.LockedAboveTarget = nil
	npcSafety.LastAttachedTarget = nil
	npcSafety.TargetCombatStartedAt = 0
	npcSafety.TargetLastConfirmedHitAt = 0
	npcSafety.LoopWindowStartedAt = 0
	npcSafety.LoopJumpCount = 0
	npcSafety.LoopTargetPosition = nil
	npcSafety.LoopPlayerPosition = nil
	npcSafety.BelowProbeActive = false
	npcSafety.ModeEnteredAt = os.clock()
	npcSafety.ModeFirstAttackAt = 0
	npcSafety.ModeConfirmedHits = 0
	npcSafety.LastModeConfirmedHitAt = 0
	npcSafety.NextBelowProbeAt = 0
	npcSafety.CurrentAboveDistance = npcSafety.AboveAttackDistance
	npcSafety.AboveDistanceConfirmed = false
	npcSafety.NoclipFailureCount = 0
	npcSafety.MovementSampleElapsed = 0
	npcSafety.MovementSamplePosition = nil
	npcSafety.MovementSampleDistance = nil
	npcSafety.MovementStallElapsed = 0
	npcSafety.LastCharacterHealth = nil
	if enabled then
		if npcSafety.DirectLight.Authorized and not npcSafety.DirectLight.Enabled then
			npcSafety.StartDirectLightDiagnostic()
		end
		npcSafety.ResetPostCombat()
		npcSafety.SpawnDestination = nil
		npcSafety.SpawnSource = nil
		suppressNpcCameraShake()
		setNpcStatus("Searching for the nearest " .. selectedNpcType .. "...", colors.Success)
	else
		if npcSafety.DirectLight.Enabled then
			npcSafety.StopDirectLightDiagnostic("Autofarm OFF")
		end
		npcSafety.ResetPostCombat()
		npcSafety.PlayerEvadeMode = false
		npcSafety.PlayerEvadePosition = nil
		npcSafety.PlayerEvadeThreatPlayer = nil
		npcSafety.PlayerEvadeThreatNpc = nil
		npcSafety.PendingServerHopReason = nil
		npcSafety.RecoveryMode = false
		npcSafety.RecoveryPosition = nil
		npcSafety.RecoveryResumeRatio = nil
		npcSafety.SpawnDestination = nil
		npcSafety.SpawnSource = nil
		restoreNpcMovementState()
		restoreNpcCameraShake()
		setNpcStatus("Autofarm disabled; movement and collisions restored.", colors.Muted)
	end
	return true
end

do
local function getTpPosition(instance)
	if not instance or not instance.Parent then
		return nil
	end
	if instance:IsA("BasePart") then
		return instance.Position
	end
	if instance:IsA("Model") then
		local marker = instance:FindFirstChild("Location", true)
			or instance:FindFirstChild("Teleport", true)
			or instance:FindFirstChild("Spawn", true)
			or instance:FindFirstChild("HumanoidRootPart", true)
		if marker and marker:IsA("BasePart") then
			return marker.Position
		end
		local ok, pivot = pcall(instance.GetPivot, instance)
		return ok and pivot.Position or nil
	end
	local part = instance:FindFirstChildWhichIsA("BasePart", true)
	return part and part.Position or nil
end

local function getTpEntryWorldPosition(instance)
	if not instance or not instance.Parent then
		return nil
	end
	if instance:IsA("Model") then
		local root = getNpcRoot(instance)
		if root then
			return root.Position
		end
	end
	return getTpPosition(instance)
end

local function addTpEntry(entries, seen, name, instance, category)
	local position = getTpEntryWorldPosition(instance)
	if type(name) ~= "string" or name == "" or not position then
		return
	end
	local key = string.lower(name) .. string.format("|%.0f|%.0f|%.0f", position.X, position.Y, position.Z)
	if seen[key] then
		return
	end
	seen[key] = true
	table.insert(entries, {Name = name, Instance = instance, Category = category})
end

local function collectTpEntries(category)
	local entries, seen = {}, {}
	local world = workspace:FindFirstChild("World")
	local map = world and world:FindFirstChild("Map")
	if category == "Worlds" then
		for planetName, placeId in pairs(planetData) do
			if type(planetName) == "string" and type(placeId) == "number" then
				table.insert(entries, {
					Name = planetName,
					PlaceId = placeId,
					IsCurrent = placeId == game.PlaceId,
					Category = category,
				})
			end
		end
	elseif category == "Bus Stops" then
		local fastTravel = map and map:FindFirstChild("Fast Travel")
		if fastTravel then
			for _, destination in ipairs(fastTravel:GetChildren()) do
				addTpEntry(entries, seen, destination.Name, destination, category)
			end
		end
	elseif category == "Locations" then
		local roots = {}
		local realMap = world and world:FindFirstChild("Real Map")
		local realLocations = realMap and realMap:FindFirstChild("Locations")
		local mapLocations = map and map:FindFirstChild("Locations")
		local realLandmarks = realLocations and realLocations:FindFirstChild("LandMarks")
		local mapLandmarks = mapLocations and mapLocations:FindFirstChild("LandMarks")
		local zoneLocations = map and map:FindFirstChild("Zone Locations")
		for _, root in ipairs({realLandmarks, mapLandmarks, zoneLocations}) do
			if root then table.insert(roots, root) end
		end
		for _, root in ipairs(roots) do
			for _, destination in ipairs(root:GetChildren()) do
				addTpEntry(entries, seen, destination.Name, destination, category)
			end
		end
	elseif category == "NPCs" then
		local counts = {}
		local live = getLiveFolder()
		if live then
			for _, descendant in ipairs(live:GetDescendants()) do
				if descendant:IsA("Humanoid") and descendant.Health > 0 then
					local model = descendant.Parent
					if model and model:IsA("Model") and getNpcRoot(model)
						and not Players:GetPlayerFromCharacter(model) then
						counts[model.Name] = (counts[model.Name] or 0) + 1
						local suffix = counts[model.Name] > 1 and (" #" .. counts[model.Name]) or ""
						addTpEntry(entries, seen, model.Name .. suffix, model, category)
					end
				end
			end
		end
		local npcFolder = world and world:FindFirstChild("NPC")
		if npcFolder then
			for _, descendant in ipairs(npcFolder:GetDescendants()) do
				if descendant:IsA("Humanoid") then
					local model = descendant.Parent
					if model and model:IsA("Model") and getNpcRoot(model) then
						counts[model.Name] = (counts[model.Name] or 0) + 1
						local suffix = counts[model.Name] > 1 and (" #" .. counts[model.Name]) or ""
						addTpEntry(entries, seen, model.Name .. suffix, model, category)
					end
				end
			end
		end
	elseif category == "Players" then
		for _, player in ipairs(Players:GetPlayers()) do
			if player ~= localPlayer and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
				addTpEntry(entries, seen, player.DisplayName .. "  (@" .. player.Name .. ")", player.Character, category)
			end
		end
	end
	table.sort(entries, function(a, b)
		return string.lower(a.Name) < string.lower(b.Name)
	end)
	return entries
end

local function teleportToTpEntry(entry)
	if entry and entry.PlaceId then
		if entry.IsCurrent then
			tpState.StatusLabel.Text = "Already on " .. entry.Name .. "."
			tpState.StatusLabel.TextColor3 = colors.Muted
			return false
		end
		if npcTargetingEnabled then
			setNpcTargetingEnabled(false)
		else
			restoreNpcMovementState()
		end
		qolState.AutoFood.TravelActive = false
		qolState.AutoFood.TravelPhase = "Idle"
		local queued = qolState.ServerNavigation.QueueSelfForTeleport()
		tpState.StatusLabel.Text = queued
			and ("Teleporting to " .. entry.Name .. "; Gohan Hub queued...")
			or ("Teleporting to " .. entry.Name .. "...")
		tpState.StatusLabel.TextColor3 = colors.Warning
		local ok = pcall(TeleportService.Teleport, TeleportService, entry.PlaceId, localPlayer)
		if not ok then
			tpState.StatusLabel.Text = "Could not teleport to " .. entry.Name .. "."
			tpState.StatusLabel.TextColor3 = colors.DangerHover
			return false
		end
		return true
	end
	local character = localPlayer.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local root = character and character:FindFirstChild("HumanoidRootPart")
	local destination
	if entry.Category == "NPCs" then
		local pivot = getTpEntryWorldPosition(entry.Instance)
		if pivot then
			destination = Vector3.new(
				pivot.X,
				pivot.Y - npcSafety.ChestApproachOffset,
				pivot.Z
			)
		end
	else
		destination = entry and getTpPosition(entry.Instance)
		if destination then
			destination = destination + Vector3.new(0, 4, 0)
		end
	end
	if not character or not humanoid or humanoid.Health <= 0 or not root or not destination then
		tpState.StatusLabel.Text = "Destination is no longer available; refresh the list."
		tpState.StatusLabel.TextColor3 = colors.DangerHover
		return false
	end
	if npcTargetingEnabled then
		setNpcTargetingEnabled(false)
	else
		restoreNpcMovementState()
	end
	qolState.AutoFood.TravelActive = false
	qolState.AutoFood.TravelPhase = "Idle"
	if entry.Category == "NPCs" then
		applyNpcNoclip(character, true)
	end
	local rotation = character:GetPivot().Rotation
	character:PivotTo(CFrame.new(destination) * rotation)
	root.AssemblyLinearVelocity = Vector3.zero
	root.AssemblyAngularVelocity = Vector3.zero
	humanoid.PlatformStand = false
	humanoid.AutoRotate = true
	tpState.StatusLabel.Text = "Teleported to " .. entry.Name .. "."
	tpState.StatusLabel.TextColor3 = colors.Success
	return true
end

function tpState.Refresh()
	for _, button in ipairs(tpState.DestinationButtons) do
		button:Destroy()
	end
	table.clear(tpState.DestinationButtons)
	tpState.Entries = collectTpEntries(tpState.Category)
	local query = string.lower(tpState.SearchBox.Text or "")
	local shown = 0
	for _, entry in ipairs(tpState.Entries) do
		if query == "" or string.find(string.lower(entry.Name), query, 1, true) then
			shown += 1
			local button = create("TextButton", {
				Name = "Destination",
				LayoutOrder = shown,
				Size = UDim2.new(1, -2, 0, 34),
				AutoButtonColor = false,
				BackgroundColor3 = colors.SurfaceRaised,
				BorderSizePixel = 0,
				Font = Enum.Font.GothamMedium,
				Text = entry.Name .. (entry.IsCurrent and "  (CURRENT)" or ""),
				TextColor3 = colors.Text,
				TextSize = 10,
				TextXAlignment = Enum.TextXAlignment.Left,
			}, tpState.List)
			create("UICorner", {CornerRadius = UDim.new(0, 6)}, button)
			create("UIPadding", {PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10)}, button)
			table.insert(tpState.DestinationButtons, button)
			connect(button.Activated, function()
				teleportToTpEntry(entry)
			end)
		end
	end
	tpState.StatusLabel.Text = shown > 0
		and string.format("%d %s destination%s available.", shown, tpState.Category, shown == 1 and "" or "s")
		or ("No " .. string.lower(tpState.Category) .. " matched the current search.")
	tpState.StatusLabel.TextColor3 = shown > 0 and colors.Muted or colors.DangerHover
	if tpState.Category == "NPCs" then
		npcSafety.UpdateWatchlistNpcAlerts()
	end
	return shown
end

for category, button in pairs(tpState.CategoryButtons) do
	connect(button.Activated, function()
		tpState.Category = category
		for name, categoryButton in pairs(tpState.CategoryButtons) do
			local selected = name == category
			categoryButton.BackgroundColor3 = selected and colors.Accent or colors.SurfaceRaised
			categoryButton.TextColor3 = selected and colors.Text or colors.Muted
		end
		tpState.Refresh()
	end)
end
connect(tpState.RefreshButton.Activated, tpState.Refresh)
connect(tpState.SearchBox:GetPropertyChangedSignal("Text"), tpState.Refresh)

function tpState.TeleportTo(category, destinationName)
	if type(category) ~= "string" or type(destinationName) ~= "string" then
		return false
	end
	for _, entry in ipairs(collectTpEntries(category)) do
		if entry.Name == destinationName then
			return teleportToTpEntry(entry)
		end
	end
	return false
end
end


function qolState.StatAllocate.GetEnhancedValue(statName)
	local definition = qolState.StatAllocate.Definitions[statName or qolState.StatAllocate.Selected]
	if not definition then
		return nil
	end

	-- Boosters.*Boost values are temporary/runtime modifiers, not allocated stats.
	-- StatRetrieveRemote exposes the persisted enhanced value used by stat allocation.
	local serial = qolState.StatAllocate.RequestSerial
	local ok, enhanced = configStore.ReadStatBounded(5, function()
		return serial == qolState.StatAllocate.RequestSerial
	end, definition.EnhancedKey)
	if unloaded or serial ~= qolState.StatAllocate.RequestSerial then return nil end
	if ok and tonumber(enhanced) then
		return tonumber(enhanced)
	end

	-- Fallback for brief remote failures; this may lag and must not be preferred.
	local playerStats = localPlayer:FindFirstChild("PlayerStats")
	local statData = playerStats and playerStats:FindFirstChild("StatData")
	local folder = definition and statData and statData:FindFirstChild(definition.BoostFolder or "Boosters")
	local valueObject = folder and folder:FindFirstChild(definition.BoostName)
	return valueObject and valueObject:IsA("ValueBase") and tonumber(valueObject.Value) or nil
end

function qolState.StatAllocate.SetTargetEnhanced(value)
	if value == nil or value == "" then
		qolState.StatAllocate.TargetEnhanced = nil
		qolState.StatAllocate.BuildTargets[qolState.StatAllocate.Selected] = nil
		qolState.StatAllocate.TargetBox.Text = ""
		qolState.StatAllocate.SetStatus("Enhanced target cleared; auto allocation has no stat cap.", colors.Muted)
		return true
	end
	value = tonumber(value)
	if not value or value < 0 or value ~= value or value == math.huge then
		qolState.StatAllocate.TargetBox.Text = qolState.StatAllocate.TargetEnhanced
			and tostring(qolState.StatAllocate.TargetEnhanced) or ""
		qolState.StatAllocate.SetStatus("Enter a valid enhanced-stat target of 0 or higher.", colors.DangerHover)
		return false
	end
	value = math.clamp(value, 0, 1000000000)
	qolState.StatAllocate.TargetEnhanced = value
	qolState.StatAllocate.BuildTargets[qolState.StatAllocate.Selected] = value
	qolState.StatAllocate.TargetBox.Text = tostring(value)
	local buildBox = qolState.StatAllocate.BuildTargetBoxes[qolState.StatAllocate.Selected]
	if buildBox then buildBox.Text = tostring(value) end
	local current = qolState.StatAllocate.GetEnhancedValue()
	qolState.StatAllocate.SetStatus(
		string.format("%s enhanced: %s / %s target.",
			qolState.StatAllocate.DisplayNames[qolState.StatAllocate.Selected],
			current and string.format("%.2f", current) or "unavailable",
			tostring(value)),
		colors.Success
	)
	return true
end

function qolState.StatAllocate.GetPriorityOrder()
	local ordered = table.clone(qolState.StatAllocate.Order)
	table.sort(ordered, function(a, b)
		local pa = tonumber(qolState.StatAllocate.BuildPriority[a]) or 99
		local pb = tonumber(qolState.StatAllocate.BuildPriority[b]) or 99
		return pa == pb and table.find(qolState.StatAllocate.Order, a) < table.find(qolState.StatAllocate.Order, b) or pa < pb
	end)
	return ordered
end

function qolState.StatAllocate.SelectNextBuildStat()
	local serial = qolState.StatAllocate.RequestSerial
	for _, statName in ipairs(qolState.StatAllocate.GetPriorityOrder()) do
		local target = qolState.StatAllocate.BuildTargets[statName]
		if type(target) == "number" then
			local current = qolState.StatAllocate.GetEnhancedValue(statName)
			if unloaded or serial ~= qolState.StatAllocate.RequestSerial then return nil end
			if current == nil or current < target then
				qolState.StatAllocate.Select(statName)
				return statName, current, target
			end
		end
	end
	return nil
end

function qolState.StatAllocate.CheckTargetReached()
	local serial = qolState.StatAllocate.RequestSerial
	local target = qolState.StatAllocate.TargetEnhanced
	if target == nil then
		return false
	end
	local current = qolState.StatAllocate.GetEnhancedValue()
	if unloaded or serial ~= qolState.StatAllocate.RequestSerial then return false end
	if not current or current < target then
		return false, current
	end
	local completedName = qolState.StatAllocate.Selected
	local nextStat, nextCurrent, nextTarget = qolState.StatAllocate.SelectNextBuildStat()
	if unloaded or (not nextStat and serial ~= qolState.StatAllocate.RequestSerial) then return false end
	if nextStat then
		qolState.StatAllocate.WaitingForGtp = false
		qolState.StatAllocate.SetStatus(string.format(
			"%s complete. Next: %s enhanced %s / %s.",
			qolState.StatAllocate.DisplayNames[completedName],
			qolState.StatAllocate.DisplayNames[nextStat],
			nextCurrent and string.format("%.2f", nextCurrent) or "unavailable", tostring(nextTarget)), colors.Success)
		return false, current
	end
	qolState.StatAllocate.AutoEnabled = false
	qolState.StatAllocate.PersistentAutoEnabled = false
	qolState.StatAllocate.WaitingForGtp = false
	qolState.StatAllocate.RenderAuto()
	qolState.StatAllocate.SetStatus("Full enhanced-stat build complete.", colors.Success)
	return true, current
end

function qolState.StatAllocate.RenderAuto()
	local button = qolState.StatAllocate.AutoButton
	if button then
		button.Text = qolState.StatAllocate.AutoEnabled and "Auto: ON" or "Auto: OFF"
		button.BackgroundColor3 = qolState.StatAllocate.AutoEnabled and colors.Accent or colors.SurfaceRaised
		button.TextColor3 = qolState.StatAllocate.AutoEnabled and colors.Text or colors.Muted
	end
	local persistentButton = qolState.StatAllocate.PersistentAutoButton
	if persistentButton then
		persistentButton.Text = qolState.StatAllocate.PersistentAutoEnabled and "Auto Build: ON" or "Auto Build: OFF"
		persistentButton.BackgroundColor3 = qolState.StatAllocate.PersistentAutoEnabled and colors.Accent or colors.SurfaceRaised
		persistentButton.TextColor3 = qolState.StatAllocate.PersistentAutoEnabled and colors.Text or colors.Muted
	end
end


function qolState.StatAllocate.RenderRapid()
	local button = qolState.StatAllocate.RapidButton
	if button then
		button.Text = qolState.StatAllocate.RapidEnabled and "Rapid: ON" or "Rapid: OFF"
		button.BackgroundColor3 = qolState.StatAllocate.RapidEnabled and colors.Accent or colors.Surface
		button.TextColor3 = qolState.StatAllocate.RapidEnabled and colors.Text or colors.Muted
	end
end

function qolState.StatAllocate.SetRapidEnabled(enabled)
	qolState.StatAllocate.RapidEnabled = enabled == true
	qolState.StatAllocate.AutoElapsed = 0
	qolState.StatAllocate.RenderRapid()
	qolState.StatAllocate.SetStatus(qolState.StatAllocate.RapidEnabled
		and "Rapid allocation enabled; the next point starts after server confirmation."
		or "Rapid allocation disabled; using conservative pacing.",
		qolState.StatAllocate.RapidEnabled and colors.Success or colors.Muted)
	return qolState.StatAllocate.RapidEnabled
end

function qolState.StatAllocate.RenderMotivation()
	local button = qolState.StatAllocate.MotivationAutoButton
	if button then
		button.Text = qolState.StatAllocate.MotivationAutoEnabled and "Auto Motivation: ON" or "Auto Motivation: OFF"
		button.BackgroundColor3 = qolState.StatAllocate.MotivationAutoEnabled and colors.Accent or colors.Surface
		button.TextColor3 = qolState.StatAllocate.MotivationAutoEnabled and colors.Text or colors.Muted
	end
end

function qolState.StatAllocate.CancelMotivation()
	local state = qolState.StatAllocate
	state.MotivationSerial = (state.MotivationSerial or 0) + 1
	state.MotivationBusy = false
	if state.MotivationButton then
		state.MotivationButton.Text = "Increase Once"
		state.MotivationButton.BackgroundColor3 = colors.Accent
	end
end

function qolState.StatAllocate.SetMotivationAutoEnabled(enabled)
	qolState.StatAllocate.CancelMotivation()
	qolState.StatAllocate.MotivationAutoEnabled = enabled == true
	qolState.StatAllocate.MotivationElapsed = 0
	qolState.StatAllocate.RenderMotivation()
	if qolState.StatAllocate.MotivationStatusLabel then
		qolState.StatAllocate.MotivationStatusLabel.Text = qolState.StatAllocate.MotivationAutoEnabled
			and "Auto motivation enabled; sending one bounded request at a time."
			or "Auto motivation disabled."
		qolState.StatAllocate.MotivationStatusLabel.TextColor3 = qolState.StatAllocate.MotivationAutoEnabled
			and colors.Success or colors.Muted
	end
	return qolState.StatAllocate.MotivationAutoEnabled
end

function qolState.StatAllocate.RequestMotivation()
	if not configStore.FeatureAccess.Motivation then return false end
	if unloaded or qolState.StatAllocate.MotivationBusy or os.clock() < (qolState.StatAllocate.MotivationRetryAt or 0) then
		return false
	end
	qolState.StatAllocate.MotivationBusy = true
	qolState.StatAllocate.MotivationSerial = (qolState.StatAllocate.MotivationSerial or 0) + 1
	local serial = qolState.StatAllocate.MotivationSerial
	local function current() return not unloaded and serial == qolState.StatAllocate.MotivationSerial end
	if qolState.StatAllocate.MotivationButton then
		qolState.StatAllocate.MotivationButton.Text = "Requesting..."
		qolState.StatAllocate.MotivationButton.BackgroundColor3 = colors.AccentSoft
	end
	local sent, sendError = pcall(serverRemote.FireServer, serverRemote, nil, {
		Module = "StatManager",
		Action = "IncreaseMotivation",
	})
	if not sent then
		qolState.StatAllocate.MotivationBusy = false
		qolState.StatAllocate.MotivationButton.Text = "Increase Once"
		qolState.StatAllocate.MotivationButton.BackgroundColor3 = colors.Accent
		if qolState.StatAllocate.MotivationStatusLabel then
			qolState.StatAllocate.MotivationStatusLabel.Text = "Motivation request failed: " .. tostring(sendError)
			qolState.StatAllocate.MotivationStatusLabel.TextColor3 = colors.DangerHover
		end
		return false
	end
	local requestThread = task.spawn(function()
		task.wait(0.15)
		if not current() then return end
		local ok, value = configStore.ReadStatBounded(5, current, "Motivation")
		if not current() then return end
		qolState.StatAllocate.MotivationBusy = false
		qolState.StatAllocate.MotivationRetryAt = ok and 0 or os.clock() + 5
		if qolState.StatAllocate.MotivationButton then
			qolState.StatAllocate.MotivationButton.Text = "Increase Once"
			qolState.StatAllocate.MotivationButton.BackgroundColor3 = colors.Accent
		end
		if qolState.StatAllocate.MotivationStatusLabel then
			qolState.StatAllocate.MotivationStatusLabel.Text = ok and tonumber(value)
				and ("Motivation confirmed: " .. tostring(value))
				or ("Motivation confirmation " .. tostring(value) .. "; retry available in 5s.")
			qolState.StatAllocate.MotivationStatusLabel.TextColor3 = ok and colors.Success or colors.Warning
		end
	end)
	table.insert(scheduledThreads, requestThread)
	return true
end

function qolState.StatAllocate.CancelAllocation()
	local state = qolState.StatAllocate
	state.RequestSerial += 1
	state.Busy = false
	state.PreChecking = false
	if state.AllocateButton then
		state.AllocateButton.Text = "Allocate 1"
		state.AllocateButton.BackgroundColor3 = colors.Accent
	end
end

function qolState.StatAllocate.SetAutoEnabled(enabled)
	qolState.StatAllocate.CancelAllocation()
	qolState.StatAllocate.AutoEnabled = enabled == true
	qolState.StatAllocate.WaitingForGtp = false
	qolState.StatAllocate.GtpEmptyAlertSent = false
	if qolState.StatAllocate.AutoEnabled then
		qolState.StatAllocate.PersistentAutoEnabled = false
	end
	qolState.StatAllocate.AutoElapsed = 0
	qolState.StatAllocate.RenderAuto()
	qolState.StatAllocate.SetStatus(
		qolState.StatAllocate.AutoEnabled and "Auto allocation enabled for the selected stat." or "Auto allocation disabled.",
		qolState.StatAllocate.AutoEnabled and colors.Success or colors.Muted
	)
	return qolState.StatAllocate.AutoEnabled
end

function qolState.StatAllocate.ReleaseAutoBuildHold()
	local root = qolState.StatAllocate.AutoBuildHoldRoot
	qolState.StatAllocate.AutoBuildHoldRoot = nil
	if root and root.Parent then
		root.Anchored = false
	end
end

function qolState.StatAllocate.SetPersistentAutoEnabled(enabled)
	local state = qolState.StatAllocate
	if enabled ~= true then
		state.ReleaseAutoBuildHold()
	end
	-- Cancel any in-flight allocation and reset the training launcher on every
	-- toggle so pause -> start always begins a fresh, usable cycle.
	state.CancelAllocation()
	state.PersistentAutoEnabled = enabled == true
	state.WaitingForGtp = false
	state.AutoBuildSafeWaitUntil = 0
	state.AutoBuildElapsed = 0
	state.AutoBuildResumeAutofarm = enabled == true and selectedNpcType ~= nil
	state.GtpEmptyAlertSent = false
	state.AutoElapsed = 0
	autoStartBusy = false
	autoStartFailedLaunches = 0
	autoStartLastAttemptAt = 0
	if state.PersistentAutoEnabled then
		state.AutoEnabled = false
		local stopTraining = state.StopTrainingSession
		if activeTrainingButton and type(stopTraining) == "function" then stopTraining("Auto Build restarting training session...") end
	else
		local setTrainingEnabled = state.SetTrainingEnabled
		if autoStartEnabled and type(setTrainingEnabled) == "function" then
			state.InternalTrainingToggle = true
			setTrainingEnabled(false)
			state.InternalTrainingToggle = false
		end
		local stopTraining = state.StopTrainingSession
		if activeTrainingButton and type(stopTraining) == "function" then stopTraining("Auto Build paused.") end
	end
	state.RenderAuto()
	state.SetStatus(
		state.PersistentAutoEnabled
			and "Auto Build enabled; training starts now and each earned GTP is allocated safely."
			or "Auto Build disabled.",
		state.PersistentAutoEnabled and colors.Success or colors.Muted
	)
	return state.PersistentAutoEnabled
end


function qolState.StatAllocate.SetStatus(text, color)
	if qolState.StatAllocate.StatusLabel then
		qolState.StatAllocate.StatusLabel.Text = text
		qolState.StatAllocate.StatusLabel.TextColor3 = color or colors.Muted
	end
end

function qolState.StatAllocate.Select(statName)
	if not qolState.StatAllocate.Definitions[statName] then
		return false
	end
	if qolState.StatAllocate.Selected ~= statName then qolState.StatAllocate.CancelAllocation() end
	qolState.StatAllocate.Selected = statName
	qolState.StatAllocate.TargetEnhanced = qolState.StatAllocate.BuildTargets[statName]
	qolState.StatAllocate.TargetBox.Text = qolState.StatAllocate.TargetEnhanced and tostring(qolState.StatAllocate.TargetEnhanced) or ""
	qolState.StatAllocate.SelectorButton.Text = qolState.StatAllocate.DisplayNames[statName] .. "  v"
	qolState.StatAllocate.Dropdown.Visible = false
	for optionName, button in pairs(qolState.StatAllocate.OptionButtons) do
		button.BackgroundColor3 = optionName == statName and colors.Accent or colors.SurfaceRaised
		button.TextColor3 = optionName == statName and colors.Text or colors.Muted
	end
	local current = qolState.StatAllocate.GetEnhancedValue(statName)
	local target = qolState.StatAllocate.TargetEnhanced
	qolState.StatAllocate.SetStatus(
		string.format("%s enhanced: %s%s",
			qolState.StatAllocate.DisplayNames[statName],
			current and string.format("%.2f", current) or "unavailable",
			target and (" / " .. tostring(target) .. " target") or ""),
		colors.Success
	)
	return true
end

function qolState.StatAllocate.Allocate()
	if unloaded or os.clock() < (qolState.StatAllocate.AllocationRetryAt or 0) then return false end
	if qolState.StatAllocate.Busy or qolState.StatAllocate.PreChecking then
		qolState.StatAllocate.SetStatus("An allocation request is already pending.", colors.Muted)
		return false
	end
	-- The pre-checks below yield on InvokeServer; hold a flag so Heartbeat can't start a second pass.
	qolState.StatAllocate.PreChecking = true
	qolState.StatAllocate.RequestSerial += 1
	local serial = qolState.StatAllocate.RequestSerial
	local ok, result = pcall(qolState.StatAllocate.AllocateUnguarded, serial)
	if unloaded or serial ~= qolState.StatAllocate.RequestSerial then return false end
	qolState.StatAllocate.PreChecking = false
	if not ok then
		qolState.StatAllocate.Busy = false
		qolState.StatAllocate.AllocationRetryAt = os.clock() + 5
		qolState.StatAllocate.SetStatus("Allocation error: " .. tostring(result), colors.DangerHover)
		return false
	end
	return result
end

function qolState.StatAllocate.AllocateUnguarded(requestSerial)
	local statName = qolState.StatAllocate.Selected
	local function current()
		return not unloaded and requestSerial == qolState.StatAllocate.RequestSerial and statName == qolState.StatAllocate.Selected
	end
	local definition = qolState.StatAllocate.Definitions[statName]
	if not definition then
		qolState.StatAllocate.SetStatus("Select a valid stat first.", colors.DangerHover)
		return false
	end
	if qolState.StatAllocate.AutoEnabled or qolState.StatAllocate.PersistentAutoEnabled then
		local finished = qolState.StatAllocate.CheckTargetReached()
		if finished or qolState.StatAllocate.Selected ~= statName then
			return false
		end
	end

	local okBefore, gtpBefore = configStore.ReadStatBounded(5, current, "Gained TP")
	if not current() then return false end
	local readError = gtpBefore
	gtpBefore = okBefore and tonumber(gtpBefore) or nil
	if not gtpBefore then
		qolState.StatAllocate.AllocationRetryAt = os.clock() + 5
		qolState.StatAllocate.SetStatus("GTP read " .. tostring(readError) .. "; retry available in 5s.", colors.DangerHover)
		return false
	end
	if qolState.StatAllocate.PersistentAutoEnabled then
		if gtpBefore < qolState.StatAllocate.AutoBuildBatchMinimum then
			if gtpBefore < 1 and not qolState.StatAllocate.GtpEmptyAlertSent then
				qolState.StatAllocate.GtpEmptyAlertSent = true
				configStore.Webhook.Send("GTP Depleted", "Auto Build spent its available GTP and resumed Autofarm.", 15105570)
			end
			qolState.StatAllocate.WaitingForGtp = true
			if qolState.StatAllocate.AutoBuildResumeAutofarm and not npcTargetingEnabled then
				qolState.StatAllocate.ReleaseAutoBuildHold()
				setNpcTargetingEnabled(true)
			end
			qolState.StatAllocate.SetStatus(string.format("Auto Build farming: %d / %d GTP before the next safe allocation batch.",
				gtpBefore, qolState.StatAllocate.AutoBuildBatchMinimum), colors.Muted)
			return false
		end
		if npcTargetingEnabled then
			setNpcTargetingEnabled(false)
			local character = localPlayer.Character
			local characterRoot = character and character:FindFirstChild("HumanoidRootPart")
			local groundY = characterRoot and getGroundYAt(characterRoot.Position, character)
			if characterRoot and groundY then
				-- Use the same underground safe layer as Autofarm before spending a batch.
				-- Autofarm's rig is gone at this point, so anchor to stop the fall through terrain.
				characterRoot.CFrame = CFrame.new(characterRoot.Position.X, groundY - npcSafety.TravelDepth,
					characterRoot.Position.Z) * characterRoot.CFrame.Rotation
				characterRoot.AssemblyLinearVelocity = Vector3.zero
				characterRoot.Anchored = true
				qolState.StatAllocate.AutoBuildHoldRoot = characterRoot
			end
			qolState.StatAllocate.AutoBuildSafeWaitUntil = os.clock() + 1.25
			qolState.StatAllocate.SetStatus("Auto Build earned GTP; pausing Autofarm for a safe allocation window...", colors.Success)
			return false
		end
		if os.clock() < qolState.StatAllocate.AutoBuildSafeWaitUntil then
			return false
		end
	end
	if gtpBefore < 1 then
		local automated = qolState.StatAllocate.AutoEnabled or qolState.StatAllocate.PersistentAutoEnabled
		if automated and not qolState.StatAllocate.GtpEmptyAlertSent then
			qolState.StatAllocate.GtpEmptyAlertSent = true
			configStore.Webhook.Send("GTP Depleted", string.format(
				"Auto stat allocation stopped because GTP reached 0 while training %s.",
				qolState.StatAllocate.DisplayNames[statName]
			), 15105570)
		end
		qolState.StatAllocate.WaitingForGtp = qolState.StatAllocate.PersistentAutoEnabled
		qolState.StatAllocate.SetStatus(
			qolState.StatAllocate.PersistentAutoEnabled and "Waiting for newly earned GTP..." or "No GTP is available to allocate.",
			qolState.StatAllocate.PersistentAutoEnabled and colors.Muted or colors.DangerHover
		)
		if qolState.StatAllocate.AutoEnabled then
			qolState.StatAllocate.SetAutoEnabled(false)
		end
		return false
	end
	qolState.StatAllocate.WaitingForGtp = false
	qolState.StatAllocate.GtpEmptyAlertSent = false

	qolState.StatAllocate.Busy = true
	qolState.StatAllocate.AllocateButton.Text = "Working..."
	qolState.StatAllocate.AllocateButton.BackgroundColor3 = colors.AccentSoft
	qolState.StatAllocate.SetStatus("Server request: " .. qolState.StatAllocate.DisplayNames[statName] .. "...", colors.Muted)

	local payload = {
		Module = "StatManager",
		Action = "Gain",
		ClientVerified = true,
		Stat = statName,
		StatType = definition.StatType,
	}
	if definition.ItemType then
		payload.ItemType = definition.ItemType
	end

	local retryThread = task.spawn(function()
		local gtpAfter = gtpBefore
		local sendError = nil
		local attempts = 0
		for attempt = 1, 10 do
			if not current() then
				return
			end
			attempts = attempt
			qolState.StatAllocate.SetStatus(
				string.format("Allocating %s - retry %d/10...", qolState.StatAllocate.DisplayNames[statName], attempt),
				colors.Muted
			)
			local sent, currentError = pcall(function()
				serverRemote:FireServer(nil, payload)
			end)
			if not sent then
				sendError = currentError
				break
			end
			local confirmationDeadline = os.clock() + 0.28
			repeat
				task.wait(qolState.StatAllocate.RapidEnabled and 0.04 or 0.28)
				if not current() then return end
				local okAfter, currentGtp = configStore.ReadStatBounded(5, current, "Gained TP")
				if not current() then return end
				if not okAfter then
					sendError = "Confirmation " .. tostring(currentGtp) .. "; stopping retries to avoid duplicate spending"
					qolState.StatAllocate.AllocationRetryAt = os.clock() + 5
					break
				end
				currentGtp = okAfter and tonumber(currentGtp) or nil
				if currentGtp then
					gtpAfter = currentGtp
				end
			until gtpAfter < gtpBefore or os.clock() >= confirmationDeadline
			if sendError or gtpAfter < gtpBefore then
				break
			end
		end

		if not current() then
			return
		end
		qolState.StatAllocate.Busy = false
		qolState.StatAllocate.AllocateButton.Text = "Allocate 1"
		qolState.StatAllocate.AllocateButton.BackgroundColor3 = colors.Accent
		if sendError then
			qolState.StatAllocate.SetStatus("Allocation failed: " .. tostring(sendError), colors.DangerHover)
			return
		end
		local spent = gtpBefore - gtpAfter
		if spent == 1 then
			local completedStat = qolState.StatAllocate.Selected
			if qolState.StatAllocate.CheckTargetReached() then
				return
			end
			if qolState.StatAllocate.Selected ~= completedStat then
				return
			end
			qolState.StatAllocate.SetStatus(
				string.format("Allocated 1 to %s after %d tries - GTP remaining: %d", qolState.StatAllocate.DisplayNames[statName], attempts, gtpAfter),
				colors.Success
			)
		elseif spent <= 0 then
			qolState.StatAllocate.SetStatus("No point spent after 10 native retries.", colors.DangerHover)
		else
			qolState.StatAllocate.SetStatus(string.format("Server spent %d GTP; remaining: %d", spent, gtpAfter), colors.DangerHover)
		end
	end)
	table.insert(scheduledThreads, retryThread)
	return true
end

connect(qolState.StatAllocate.SelectorButton.Activated, function()
	qolState.StatAllocate.Dropdown.Visible = not qolState.StatAllocate.Dropdown.Visible
end)

for statName, button in pairs(qolState.StatAllocate.OptionButtons) do
	connect(button.Activated, function()
		qolState.StatAllocate.Select(statName)
	end)
end

connect(qolState.StatAllocate.AllocateButton.Activated, function()
	qolState.StatAllocate.Allocate()
end)

connect(qolState.StatAllocate.AutoButton.Activated, function()
	qolState.StatAllocate.SetAutoEnabled(not qolState.StatAllocate.AutoEnabled)
end)

connect(qolState.StatAllocate.PersistentAutoButton.Activated, function()
	qolState.StatAllocate.SetPersistentAutoEnabled(not qolState.StatAllocate.PersistentAutoEnabled)
end)

connect(qolState.StatAllocate.RapidButton.Activated, function()
	qolState.StatAllocate.SetRapidEnabled(not qolState.StatAllocate.RapidEnabled)
end)

connect(qolState.StatAllocate.MotivationButton.Activated, qolState.StatAllocate.RequestMotivation)
connect(qolState.StatAllocate.MotivationAutoButton.Activated, function()
	qolState.StatAllocate.SetMotivationAutoEnabled(not qolState.StatAllocate.MotivationAutoEnabled)
end)

connect(qolState.StatAllocate.TargetBox.FocusLost, function()
	qolState.StatAllocate.SetTargetEnhanced(qolState.StatAllocate.TargetBox.Text)
end)

for statName, targetBox in pairs(qolState.StatAllocate.BuildTargetBoxes) do
	connect(targetBox.FocusLost, function()
		local value = tonumber(targetBox.Text)
		if value and value >= 0 then
			qolState.StatAllocate.BuildTargets[statName] = math.clamp(value, 0, 1000000000)
			targetBox.Text = tostring(qolState.StatAllocate.BuildTargets[statName])
		elseif targetBox.Text == "" then
			qolState.StatAllocate.BuildTargets[statName] = nil
		else
			targetBox.Text = qolState.StatAllocate.BuildTargets[statName]
				and tostring(qolState.StatAllocate.BuildTargets[statName]) or ""
		end
		if statName == qolState.StatAllocate.Selected then
			qolState.StatAllocate.TargetEnhanced = qolState.StatAllocate.BuildTargets[statName]
			qolState.StatAllocate.TargetBox.Text = targetBox.Text
		end
		qolState.StatAllocate.SelectNextBuildStat()
	end)
end

for statName, priorityBox in pairs(qolState.StatAllocate.BuildPriorityBoxes) do
	connect(priorityBox.FocusLost, function()
		local priority = math.floor(tonumber(priorityBox.Text) or qolState.StatAllocate.BuildPriority[statName] or 5)
		priority = math.clamp(priority, 1, 5)
		qolState.StatAllocate.BuildPriority[statName] = priority
		priorityBox.Text = tostring(priority)
	end)
end

qolState.StatAllocate.RenderAuto()
qolState.StatAllocate.RenderRapid()
qolState.StatAllocate.RenderMotivation()

connect(RunService.Heartbeat, function(deltaTime)
	if not qolState.StatAllocate.AutoEnabled then
		qolState.StatAllocate.AutoElapsed = 0
		return
	end
	qolState.StatAllocate.AutoElapsed += deltaTime
	local interval = qolState.StatAllocate.WaitingForGtp and 1.5
		or (qolState.StatAllocate.RapidEnabled and 0.05 or 0.45)
	if qolState.StatAllocate.AutoElapsed >= interval and not qolState.StatAllocate.Busy then
		qolState.StatAllocate.AutoElapsed = 0
		qolState.StatAllocate.Allocate()
	end
end)

connect(RunService.Heartbeat, function(deltaTime)
	if not qolState.StatAllocate.MotivationAutoEnabled then
		qolState.StatAllocate.MotivationElapsed = 0
		return
	end
	qolState.StatAllocate.MotivationElapsed += deltaTime
	if qolState.StatAllocate.MotivationElapsed >= 0.25 and not qolState.StatAllocate.MotivationBusy then
		qolState.StatAllocate.MotivationElapsed = 0
		qolState.StatAllocate.RequestMotivation()
	end
end)

function qolState.ProfileEditor.SetStatus(text, color)
	if qolState.ProfileEditor.StatusLabel then
		qolState.ProfileEditor.StatusLabel.Text = text
		qolState.ProfileEditor.StatusLabel.TextColor3 = color or colors.Muted
	end
end

function qolState.ProfileEditor.ClearOptions(container, buttonTable)
	for _, button in pairs(buttonTable) do
		if button and button.Parent then
			button:Destroy()
		end
	end
	table.clear(buttonTable)
end

function qolState.ProfileEditor.CreateOption(parent, text, layoutOrder, selected, callback)
	local button = create("TextButton", {
		Name = text,
		Size = UDim2.new(1, -6, 0, 25),
		AutoButtonColor = false,
		BackgroundColor3 = selected and colors.Accent or colors.SurfaceRaised,
		BorderSizePixel = 0,
		Font = Enum.Font.GothamMedium,
		Text = text,
		TextColor3 = selected and colors.Text or colors.Muted,
		TextSize = 9,
		LayoutOrder = layoutOrder,
		ZIndex = 61,
	}, parent)
	create("UICorner", {CornerRadius = UDim.new(0, 5)}, button)
	connect(button.Activated, callback)
	return button
end

function qolState.ProfileEditor.PopulateTraits()
	qolState.ProfileEditor.ClearOptions(qolState.ProfileEditor.TraitDropdown, qolState.ProfileEditor.TraitButtons)
	local traits = qolState.ProfileEditor.TraitsByRace[qolState.ProfileEditor.SelectedRace] or {}
	if not table.find(traits, qolState.ProfileEditor.SelectedTrait) then
		qolState.ProfileEditor.SelectedTrait = traits[1]
	end
	qolState.ProfileEditor.TraitSelectorButton.Text = (qolState.ProfileEditor.SelectedTrait or "No trait") .. "  v"
	for index, trait in ipairs(traits) do
		qolState.ProfileEditor.TraitButtons[trait] = qolState.ProfileEditor.CreateOption(
			qolState.ProfileEditor.TraitDropdown,
			trait,
			index,
			trait == qolState.ProfileEditor.SelectedTrait,
			function()
				qolState.ProfileEditor.SelectedTrait = trait
				qolState.ProfileEditor.TraitSelectorButton.Text = trait .. "  v"
				qolState.ProfileEditor.TraitDropdown.Visible = false
				for optionName, optionButton in pairs(qolState.ProfileEditor.TraitButtons) do
					local isSelected = optionName == trait
					optionButton.BackgroundColor3 = isSelected and colors.Accent or colors.SurfaceRaised
					optionButton.TextColor3 = isSelected and colors.Text or colors.Muted
				end
				qolState.ProfileEditor.SetStatus(
					string.format("Ready to set %s / %s.", qolState.ProfileEditor.SelectedRace, trait),
					colors.Success
				)
			end
		)
	end
end

function qolState.ProfileEditor.ResolveRaceKey(raceName)
	local needle = string.lower(tostring(raceName))
	for _, race in ipairs(qolState.ProfileEditor.RaceOrder) do
		if string.lower(tostring(race)) == needle then
			return race
		end
	end
	for race in pairs(qolState.ProfileEditor.TraitsByRace) do
		if string.lower(tostring(race)) == needle then
			return race
		end
	end
	return nil
end

function qolState.ProfileEditor.ApplyRace(raceName, traitName)
	if next(qolState.ProfileEditor.RaceOrder) == nil then
		local loaded = qolState.ProfileEditor.LoadMetadata()
		if not loaded then
			return false
		end
	end
	local race = qolState.ProfileEditor.ResolveRaceKey(raceName)
	if not race then
		qolState.ProfileEditor.SetStatus("Race not found: " .. tostring(raceName), colors.DangerHover)
		return false
	end
	qolState.ProfileEditor.SelectRace(race)
	if type(traitName) == "string" and table.find(qolState.ProfileEditor.TraitsByRace[race] or {}, traitName) then
		qolState.ProfileEditor.SelectedTrait = traitName
	end
	qolState.ProfileEditor.PopulateTraits()
	return qolState.ProfileEditor.Apply()
end

function qolState.ProfileEditor.SelectRace(race)
if string.lower(tostring(race)) == "angel" and not configStore.FeatureAccess.AngelRace then
qolState.ProfileEditor.SetStatus("That race is unavailable.", colors.DangerHover)
return false
end

	if not qolState.ProfileEditor.TraitsByRace[race] then
		return false
	end
	qolState.ProfileEditor.SelectedRace = race
	qolState.ProfileEditor.RaceSelectorButton.Text = race .. "  v"
	qolState.ProfileEditor.RaceDropdown.Visible = false
	for optionName, optionButton in pairs(qolState.ProfileEditor.RaceButtons) do
		local isSelected = optionName == race
		optionButton.BackgroundColor3 = isSelected and colors.Accent or colors.SurfaceRaised
		optionButton.TextColor3 = isSelected and colors.Text or colors.Muted
	end
	qolState.ProfileEditor.PopulateTraits()
	qolState.ProfileEditor.SetStatus(
		string.format("Ready to set %s / %s.", race, qolState.ProfileEditor.SelectedTrait or "None"),
		colors.Success
	)
	return true
end

function qolState.ProfileEditor.LoadMetadata()
	local raceFolder = ReplicatedStorage:FindFirstChild("Modules")
		and ReplicatedStorage.Modules:FindFirstChild("Metadata")
		and ReplicatedStorage.Modules.Metadata:FindFirstChild("RaceData")
	local raceBuffModule = raceFolder and raceFolder:FindFirstChild("RaceBuffs")
	local subTypeModule = raceFolder and raceFolder:FindFirstChild("SubTypeData")
	if not raceBuffModule or not subTypeModule then
		qolState.ProfileEditor.SetStatus("Race metadata is unavailable.", colors.DangerHover)
		return false
	end
	local okBuffs, raceBuffs = pcall(require, raceBuffModule)
	local okSubTypes, subTypeData = pcall(require, subTypeModule)
	if not okBuffs or type(raceBuffs) ~= "table" or not okSubTypes or type(subTypeData) ~= "table" then
		qolState.ProfileEditor.SetStatus("Race metadata could not be loaded.", colors.DangerHover)
		return false
	end

	table.clear(qolState.ProfileEditor.RaceOrder)
	table.clear(qolState.ProfileEditor.TraitsByRace)
	for race in pairs(raceBuffs) do
		if string.lower(tostring(race)) == "angel" and not configStore.FeatureAccess.AngelRace then continue end
		local subtypeList = subTypeData[race .. "SubTypes"]
		if type(subtypeList) == "table" then
			local traits = {}
			for _, entry in ipairs(subtypeList) do
				if type(entry) == "table" and type(entry[1]) == "string" then
					table.insert(traits, entry[1])
				end
			end
			if #traits > 0 then
				qolState.ProfileEditor.TraitsByRace[race] = traits
				table.insert(qolState.ProfileEditor.RaceOrder, race)
			end
		end
	end
	table.sort(qolState.ProfileEditor.RaceOrder)

	local okRace, currentRace = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "Race")
	local okTrait, currentTrait = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "SubType")
	currentRace = okRace and currentRace or nil
	currentTrait = okTrait and currentTrait or nil
	qolState.ProfileEditor.SelectedRace = qolState.ProfileEditor.TraitsByRace[currentRace] and currentRace
		or qolState.ProfileEditor.RaceOrder[1]
	qolState.ProfileEditor.SelectedTrait = currentTrait

	qolState.ProfileEditor.ClearOptions(qolState.ProfileEditor.RaceDropdown, qolState.ProfileEditor.RaceButtons)
	for index, race in ipairs(qolState.ProfileEditor.RaceOrder) do
		qolState.ProfileEditor.RaceButtons[race] = qolState.ProfileEditor.CreateOption(
			qolState.ProfileEditor.RaceDropdown,
			race,
			index,
			race == qolState.ProfileEditor.SelectedRace,
			function()
				qolState.ProfileEditor.SelectRace(race)
			end
		)
	end
	qolState.ProfileEditor.RaceSelectorButton.Text = (qolState.ProfileEditor.SelectedRace or "No race") .. "  v"
	qolState.ProfileEditor.PopulateTraits()
	qolState.ProfileEditor.SetStatus(
		string.format("Current: %s / %s. Hidden races are included.", tostring(currentRace), tostring(currentTrait)),
		colors.Success
	)
	return true
end

function qolState.ProfileEditor.Apply()
	if qolState.ProfileEditor.Busy then
		qolState.ProfileEditor.SetStatus("A profile request is already pending.", colors.Muted)
		return false
	end
	local race = qolState.ProfileEditor.SelectedRace
	local trait = qolState.ProfileEditor.SelectedTrait
	if not race or not trait or not table.find(qolState.ProfileEditor.TraitsByRace[race] or {}, trait) then
		qolState.ProfileEditor.SetStatus("Select a valid race and matching trait.", colors.DangerHover)
		return false
	end

	qolState.ProfileEditor.Busy = true
	qolState.ProfileEditor.RequestSerial += 1
	local requestSerial = qolState.ProfileEditor.RequestSerial
	qolState.ProfileEditor.ApplyButton.Text = "Setting..."
	qolState.ProfileEditor.ApplyButton.BackgroundColor3 = colors.AccentSoft
	qolState.ProfileEditor.SetStatus(string.format("Requesting %s / %s...", race, trait), colors.Muted)

	local thread = task.spawn(function()
		local sent, sendError = pcall(function()
			serverRemote:FireServer(nil, {
				Module = "DragonballManager",
				Action = "HardcodePlayer",
				change_Race = true,
				change_Trait = true,
				selected_Race = race,
				selected_Trait = trait,
			})
		end)
		local applied = false
		local finalRace, finalTrait
		if sent then
			for _ = 1, 10 do
				task.wait(0.35)
				local okRace, raceValue = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "Race")
				local okTrait, traitValue = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "SubType")
				finalRace = okRace and raceValue or finalRace
				finalTrait = okTrait and traitValue or finalTrait
				if finalRace == race and finalTrait == trait then
					applied = true
					break
				end
			end
		end
		if qolState.ProfileEditor.RequestSerial ~= requestSerial then
			return
		end
		qolState.ProfileEditor.Busy = false
		qolState.ProfileEditor.ApplyButton.Text = "Set Race + Trait"
		qolState.ProfileEditor.ApplyButton.BackgroundColor3 = colors.Accent
		if not sent then
			qolState.ProfileEditor.SetStatus("Profile request failed: " .. tostring(sendError), colors.DangerHover)
		elseif applied then
			qolState.ProfileEditor.SetStatus(
				string.format("Applied %s / %s. Respawn or rejoin to refresh visuals.", race, trait),
				colors.Success
			)
		else
			qolState.ProfileEditor.SetStatus(
				string.format("Server kept %s / %s; request was rejected.", tostring(finalRace), tostring(finalTrait)),
				colors.DangerHover
			)
		end
	end)
	table.insert(scheduledThreads, thread)
	return true
end

function qolState.Unlocks.SetStatus(text, color)
	if qolState.Unlocks.StatusLabel then
		qolState.Unlocks.StatusLabel.Text = text
		qolState.Unlocks.StatusLabel.TextColor3 = color or colors.Muted
	end
end

function qolState.Unlocks.IsSkillUnlocked(skillName)
	local ok, result = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, skillName, "SkillStat")
	if not ok or type(result) ~= "table" then
		ok, result = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, skillName, "Skill Stat")
	end
	return ok and type(result) == "table" and result.Unlocked == true
end

function qolState.Unlocks.UnlockSkillNode(skillName, nodeData, skillType)
	if qolState.Unlocks.IsSkillUnlocked(skillName) then
		return true, "already"
	end
	local ok, result = pcall(remotes.SkillTreeRemote.InvokeServer, remotes.SkillTreeRemote, {
		Name = skillName,
		SkillPoint_Req = 0,
		Requirements = {},
		SkillType = skillType,
		GivesSkill = nodeData.GivesSkill,
		GivesPassive = nodeData.GivesPassive,
		PassiveInfo = nodeData.PassiveInfo,
		Transformation = nodeData.Transformation,
	})
	if not ok or result ~= true then
		return false, ok and tostring(result) or tostring(result)
	end
	task.wait(0.08)
	return qolState.Unlocks.IsSkillUnlocked(skillName), "requested"
end

function qolState.Unlocks.Begin(button, busyText)
	if qolState.Unlocks.Busy then
		qolState.Unlocks.SetStatus("Another unlock request is already running.", colors.Muted)
		return nil
	end
	qolState.Unlocks.Busy = true
	qolState.Unlocks.RequestSerial += 1
	button.Text = busyText
	button.BackgroundColor3 = colors.AccentSoft
	return qolState.Unlocks.RequestSerial
end

function qolState.Unlocks.Finish(button, normalText, requestSerial)
	if qolState.Unlocks.RequestSerial ~= requestSerial then
		return false
	end
	qolState.Unlocks.Busy = false
	button.Text = normalText
	button.BackgroundColor3 = colors.Accent
	return true
end

function qolState.Unlocks.UnlockKi()
	local requestSerial = qolState.Unlocks.Begin(qolState.Unlocks.KiButton, "Unlocking...")
	if not requestSerial then return false end
	local thread = task.spawn(function()
		local okCurrent, current = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "KiUnlocked")
		if okCurrent and current == true then
			qolState.Unlocks.Finish(qolState.Unlocks.KiButton, "Unlock Ki", requestSerial)
			qolState.Unlocks.SetStatus("Ki is already unlocked.", colors.Success)
			return
		end
		local sent, sendError = pcall(function()
			serverRemote:FireServer(nil, {Module = "KiManager", Action = "Unlock"})
		end)
		local unlocked = false
		if sent then
			for _ = 1, 8 do
				task.wait(0.3)
				local ok, value = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "KiUnlocked")
				if ok and value == true then unlocked = true break end
			end
		end
		if not qolState.Unlocks.Finish(qolState.Unlocks.KiButton, "Unlock Ki", requestSerial) then return end
		if unlocked then
			qolState.Unlocks.SetStatus("Ki unlocked and verified by the server.", colors.Success)
		else
			qolState.Unlocks.SetStatus("Ki unlock rejected: " .. tostring(sendError or "server state unchanged"), colors.DangerHover)
		end
	end)
	table.insert(scheduledThreads, thread)
	return true
end

function qolState.Unlocks.UnlockFlight()
	local requestSerial = qolState.Unlocks.Begin(qolState.Unlocks.FlightButton, "Unlocking...")
	if not requestSerial then return false end
	local thread = task.spawn(function()
		local okKi, kiUnlocked = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "KiUnlocked")
		if not okKi or kiUnlocked ~= true then
			pcall(function()
				serverRemote:FireServer(nil, {Module = "KiManager", Action = "Unlock"})
			end)
			task.wait(0.4)
			okKi, kiUnlocked = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "KiUnlocked")
		end
		local skillDataModule = ReplicatedStorage.Modules.Metadata.CharacterData:FindFirstChild("SkillTreeData")
		local okData, skillTreeData = pcall(require, skillDataModule)
		local node = okData and skillTreeData.Ki and skillTreeData.Ki["Ki Fly"] or nil
		local unlocked, reason = false, okKi and kiUnlocked == true and "skill metadata unavailable" or "Ki prerequisite rejected"
		if node and okKi and kiUnlocked == true then
			unlocked, reason = qolState.Unlocks.UnlockSkillNode("Ki Fly", node, "KiSkills")
		end
		if not qolState.Unlocks.Finish(qolState.Unlocks.FlightButton, "Unlock Flight", requestSerial) then return end
		if unlocked then
			qolState.Unlocks.SetStatus("Ki flight unlocked and verified. Double-tap Space to fly.", colors.Success)
		else
			qolState.Unlocks.SetStatus("Flight unlock rejected: " .. tostring(reason), colors.DangerHover)
		end
	end)
	table.insert(scheduledThreads, thread)
	return true
end

function qolState.Unlocks.UnlockAllSkillTree()
	local requestSerial = qolState.Unlocks.Begin(qolState.Unlocks.SkillTreeButton, "Unlocking tree...")
	if not requestSerial then return false end
	local thread = task.spawn(function()
		local skillDataModule = ReplicatedStorage.Modules.Metadata.CharacterData:FindFirstChild("SkillTreeData")
		local okData, skillTreeData = pcall(require, skillDataModule)
		if not okData or type(skillTreeData) ~= "table" then
			qolState.Unlocks.Finish(qolState.Unlocks.SkillTreeButton, "Unlock All Skill Tree", requestSerial)
			qolState.Unlocks.SetStatus("Skill-tree metadata is unavailable.", colors.DangerHover)
			return
		end
		local okRace, race = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "Race")
		race = okRace and race or nil
		local branches = {
			{Name = "Basic", Type = "BasicSkills", Nodes = skillTreeData.Basic},
			{Name = "Ki", Type = "KiSkills", Nodes = skillTreeData.Ki},
			{Name = tostring(race), Type = "RaceSkills", Nodes = race and skillTreeData.Race and skillTreeData.Race[race]},
		}
		local nodes = {}
		for _, branch in ipairs(branches) do
			for skillName, nodeData in pairs(branch.Nodes or {}) do
				table.insert(nodes, {Name = skillName, Data = nodeData, Type = branch.Type, Branch = branch.Name})
			end
		end
		table.sort(nodes, function(a, b)
			if a.Branch == b.Branch then
				local aPriority = tonumber(a.Data.Priority) or 0
				local bPriority = tonumber(b.Data.Priority) or 0
				return aPriority == bPriority and a.Name < b.Name or aPriority < bPriority
			end
			return a.Branch < b.Branch
		end)

		local unlockedCount, alreadyCount = 0, 0
		local failed = {}
		for index, entry in ipairs(nodes) do
			if unloaded or qolState.Unlocks.RequestSerial ~= requestSerial then return end
			qolState.Unlocks.SetStatus(
				string.format("Unlocking %s (%d/%d)...", entry.Name, index, #nodes),
				colors.Muted
			)
			local unlocked, reason = qolState.Unlocks.UnlockSkillNode(entry.Name, entry.Data, entry.Type)
			if unlocked then
				if reason == "already" then alreadyCount += 1 else unlockedCount += 1 end
			else
				table.insert(failed, entry.Name)
			end
			task.wait(0.1)
		end
		if not qolState.Unlocks.Finish(qolState.Unlocks.SkillTreeButton, "Unlock All Skill Tree", requestSerial) then return end
		if #failed == 0 then
			qolState.Unlocks.SetStatus(
				string.format("Skill tree verified: %d unlocked, %d already learned (%s race tree).", unlockedCount, alreadyCount, tostring(race)),
				colors.Success
			)
		else
			qolState.Unlocks.SetStatus(
				string.format("Unlocked %d; server rejected %d: %s", unlockedCount, #failed, table.concat(failed, ", ")),
				colors.DangerHover
			)
		end
	end)
	table.insert(scheduledThreads, thread)
	return true
end

function qolState.Unlocks.GetTransformationSnapshot()
