function autoTransformState.CancelPending()
	autoTransformState.RequestSerial += 1
	autoTransformState.Pending = false
end

function autoTransformState.FiniteNumber(value)
	local number = tonumber(value)
	return number and number == number and math.abs(number) < math.huge and number or nil
end

function autoTransformState.IsOwnVisibleGui(object)
	local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui")
	local character = localPlayer.Character
	if not object or not object.Parent or object:IsDescendantOf(screenGui) then return false end
	if not ((playerGui and object:IsDescendantOf(playerGui)) or (character and object:IsDescendantOf(character))) then return false end
	local current = object
	while current and current ~= playerGui and current ~= character do
		if current:IsA("GuiObject") and not current.Visible then return false end
		if current:IsA("LayerCollector") and not current.Enabled then return false end
		if current:IsA("BillboardGui") and current.Adornee
			and not (character and current.Adornee:IsDescendantOf(character)) then return false end
		current = current.Parent
	end
	return true
end

function autoTransformState.ReadFatiguePercent(forceScan)
	local state = autoTransformState
	local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui")
	local character = localPlayer.Character
	if forceScan or state.FatigueGui ~= playerGui or state.FatigueCharacter ~= character
		or os.clock() >= (state.NextFatigueScanAt or 0) then
		state.FatigueGui, state.FatigueCharacter = playerGui, character
		state.NextFatigueScanAt = os.clock() + 0.75
		state.FatiguePanels = {}
		local seen = {}
		for _, root in pairs({playerGui, character}) do
			local descendants = root:GetDescendants()
			for index, object in ipairs(descendants) do
				if index > 6000 then break end
				if object:IsA("GuiObject") and state.IsOwnVisibleGui(object) then
					local name = string.lower(object.Name):gsub("[^%a]", "")
					local text = (object:IsA("TextLabel") or object:IsA("TextButton"))
						and string.lower(object.Text:gsub("<[^>]+>", "")) or ""
					local panel
					if name == "fatigue" or name == "fatiguebar" or name == "fatigueframe" then panel = object end
					if text:match("^%s*fatigue%s*[:%d%%%.%s]*$") then panel = object.Parent end
					if panel and panel:IsA("GuiObject") and not seen[panel] then
						seen[panel] = true
						table.insert(state.FatiguePanels, panel)
					end
				end
			end
		end
	end
	-- Distinguish an absent/hidden bar from a visible but unreadable bar.
	-- Never read another player's billboard or the hub's own status text.
	local highest, visibleBar = nil, false
	for _, panel in ipairs(state.FatiguePanels or {}) do
		if state.IsOwnVisibleGui(panel) then
			visibleBar = true
			local objects = panel:GetDescendants()
			table.insert(objects, 1, panel)
			if #objects <= 200 then
				for _, object in ipairs(objects) do
					if (object:IsA("TextLabel") or object:IsA("TextButton")) and state.IsOwnVisibleGui(object) then
						local text = object.Text:gsub("<[^>]+>", "")
						local percent = state.FiniteNumber(text:match("^%s*([%d%.]+)%s*%%%s*$")
							or string.lower(text):match("^%s*fatigue%s*:?%s*([%d%.]+)%s*%%%s*$"))
						if percent and percent >= 0 and percent <= 100 then highest = math.max(highest or 0, percent) end
					end
				end
			end
		end
	end
	return highest, visibleBar
end

function autoTransformState.ReadKi()
	local playerStats = localPlayer:FindFirstChild("PlayerStats")
	local statData = playerStats and playerStats:FindFirstChild("StatData")
	local characterStats = statData and statData:FindFirstChild("CharacterStats")
	local function readPair(root, recursive)
		local ki = root and root:FindFirstChild("Ki", recursive)
		local maxKi = root and root:FindFirstChild("MaxKi", recursive)
		local current = ki and ki:IsA("ValueBase") and autoTransformState.FiniteNumber(ki.Value)
		local maximum = maxKi and maxKi:IsA("ValueBase") and autoTransformState.FiniteNumber(maxKi.Value)
		if current and current >= 0 and maximum and maximum > 0 then return current, maximum end
	end
	local current, maximum = readPair(characterStats, false)
	if current then return current, maximum end
	return readPair(playerStats, true)
end

function autoTransformState.ResourceReady(selected, forceScan)
	if string.lower(selected):gsub("[^%a]", "") == "kiburst" then
		local ki, maxKi = autoTransformState.ReadKi()
		if not ki then return false, "Ki unavailable" end
		-- Compare the actual values, not a rounded label that may say 100% early.
		if ki < maxKi then return false, string.format("Ki %.1f%% / 100%%", 100 * ki / maxKi) end
		return true, "Ki full"
	end
	local fatigue, visibleBar = autoTransformState.ReadFatiguePercent(forceScan)
	if not visibleBar then return true, "No fatigue bar; ready" end
	if fatigue == nil then return false, "Fatigue unavailable" end
	if fatigue > 1 then return false, string.format("Fatigue %.1f%% > 1%%", fatigue) end
	return true, "Fatigue ready"
end

function autoTransformState.GetReadyCharacter(selected, forceScan)
	if unloaded or not autoTransformState.Enabled or autoTransformState.Selected ~= selected or npcSafety.LootMode then
		return nil, nil, "Paused"
	end
	local character = localPlayer.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local playerStats = localPlayer:FindFirstChild("PlayerStats")
	local statData = playerStats and playerStats:FindFirstChild("StatData")
	local coreStats = statData and statData:FindFirstChild("CoreStats")
	local misc = statData and statData:FindFirstChild("Misc")
	local formValue = coreStats and coreStats:FindFirstChild("Form")
	local configuredValue = misc and misc:FindFirstChild("Transformation")
	if not character or not humanoid or humanoid.Health <= 0 or not formValue or not configuredValue then
		return nil, nil, "Waiting for character"
	end
	local activeForm = tostring(formValue.Value)
	if activeForm ~= "None" and activeForm ~= "" then return nil, nil, "Form active" end
	local ready, reason = autoTransformState.ResourceReady(selected, forceScan)
	if not ready then return nil, nil, reason end
	local ok, allowed = pcall(function()
		local stateManager = require(ReplicatedStorage.Modules.Metadata.ControlData.StateManager)
		return stateManager.CanPerformAction(character, "Transform") == true
	end)
	if not ok or not allowed then return nil, nil, "Waiting for action" end
	if unloaded or not autoTransformState.Enabled or autoTransformState.Selected ~= selected
		or localPlayer.Character ~= character or humanoid.Health <= 0 or npcSafety.LootMode then return nil, nil, "Paused" end
	activeForm = tostring(formValue.Value)
	if activeForm ~= "None" and activeForm ~= "" then return nil, nil, "Form active" end
	ready, reason = autoTransformState.ResourceReady(selected)
	if not ready then return nil, nil, reason end
	return character, configuredValue, reason
end

function autoTransformState.Render()
	local selector = autoTransformState.SelectorButton
	local toggle = autoTransformState.ToggleButton
	if selector then
		selector.Text = autoTransformState.Selected and (autoTransformState.Selected .. "  v") or "No forms"
	end
	if not toggle then return end
	if autoTransformState.Enabled then
		toggle.Text = "Auto Form: ON\n" .. autoTransformState.Status
		toggle.BackgroundColor3 = colors.Accent
		toggle.TextColor3 = colors.Text
	else
		toggle.Text = "Auto Form: OFF"
		toggle.BackgroundColor3 = colors.SurfaceRaised
		toggle.TextColor3 = colors.Muted
	end
end

function autoTransformState.Select(formName)
	if not autoTransformState.FormLookup[formName] then
		return false
	end
	autoTransformState.Selected = formName
	autoTransformState.CancelPending()
	autoTransformState.AttemptElapsed = autoTransformState.RetryDelay
	autoTransformState.Dropdown.Visible = false
	for optionName, button in pairs(autoTransformState.OptionButtons) do
		button.BackgroundColor3 = optionName == formName and colors.Accent or colors.Surface
		button.TextColor3 = optionName == formName and colors.Text or colors.Muted
	end
	autoTransformState.Render()
	return true
end

function autoTransformState.SetEnabled(enabled)
	autoTransformState.CancelPending()
	if enabled == true and qolState.FormMastery.Enabled and qolState.FormMastery.SetEnabled then
		qolState.FormMastery.SetEnabled(false)
	end
	autoTransformState.Enabled = enabled == true and autoTransformState.Selected ~= nil
	autoTransformState.AttemptElapsed = autoTransformState.RetryDelay
	autoTransformState.Dropdown.Visible = false
	autoTransformState.Render()
	return autoTransformState.Enabled
end

function autoTransformState.RefreshForms()
	local snapshot, snapshotError = qolState.Unlocks.GetTransformationSnapshot()
	if type(snapshot) ~= "table" then
		warn("[GohanHub] Auto Transform could not load forms:", snapshotError)
		return false
	end

	local transformData
	pcall(function()
		transformData = require(ReplicatedStorage.Modules.Metadata.MiscData.TransformData.TransformData)
	end)
	local trueLegend = false
	pcall(function()
		trueLegend = statRetrieveRemote:InvokeServer("TrueLegend") == true
	end)

	table.clear(autoTransformState.Forms)
	table.clear(autoTransformState.FormLookup)
	for _, button in pairs(autoTransformState.OptionButtons) do
		button:Destroy()
	end
	table.clear(autoTransformState.OptionButtons)

	for category, categoryData in pairs(snapshot) do
		if type(categoryData) == "table" then
			for formName, formData in pairs(categoryData) do
				local hasMetadata = type(transformData) ~= "table"
					or (type(transformData[category]) == "table" and type(transformData[category][formName]) == "table")
				if type(formData) == "table"
					and formData.Unlocked == true
					and formData.Can_Toggle ~= false
					and formName ~= "Semi Perfect"
					and formName ~= "Perfect Form"
					and (formName ~= "LSSJ" or trueLegend)
					and hasMetadata then
					local entry = {
						Name = formName,
						Category = category,
						Mastery = tonumber(formData.Mastery) or 0,
					}
					table.insert(autoTransformState.Forms, entry)
					autoTransformState.FormLookup[formName] = entry
				end
			end
		end
	end
	table.sort(autoTransformState.Forms, function(a, b)
		return a.Name == b.Name and a.Category < b.Category or a.Name < b.Name
	end)

	for index, entry in ipairs(autoTransformState.Forms) do
		local button = create("TextButton", {
			Name = entry.Category .. "_" .. entry.Name,
			LayoutOrder = index,
			Size = UDim2.new(1, 0, 0, 25),
			BackgroundColor3 = colors.Surface,
			BorderSizePixel = 0,
			Font = Enum.Font.Gotham,
			Text = "  " .. entry.Name .. "  [" .. entry.Category .. "]",
			TextColor3 = colors.Muted,
			TextSize = 11,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			ZIndex = 71,
		}, autoTransformState.Dropdown)
		create("UICorner", {CornerRadius = UDim.new(0, 5)}, button)
		autoTransformState.OptionButtons[entry.Name] = button
		connect(button.Activated, function()
			autoTransformState.Select(entry.Name)
		end)
	end
	autoTransformState.Dropdown.CanvasSize = UDim2.new(0, 0, 0, 8 + #autoTransformState.Forms * 29)

	local configured
	pcall(function()
		configured = localPlayer.PlayerStats.StatData.Misc.Transformation.Value
	end)
	if not autoTransformState.FormLookup[autoTransformState.Selected] then
		autoTransformState.Selected = autoTransformState.FormLookup[configured] and configured
			or (autoTransformState.Forms[1] and autoTransformState.Forms[1].Name)
	end
	if autoTransformState.Selected then
		autoTransformState.Select(autoTransformState.Selected)
	else
		autoTransformState.SetEnabled(false)
	end
	return #autoTransformState.Forms > 0
end

function autoTransformState.Update(deltaTime)
	if unloaded or not autoTransformState.Enabled or not autoTransformState.Selected then return end
	autoTransformState.AttemptElapsed = math.min(autoTransformState.RetryDelay, autoTransformState.AttemptElapsed + deltaTime)
	autoTransformState.CheckElapsed += deltaTime
	if autoTransformState.CheckElapsed < 0.1 or autoTransformState.Pending then return end
	autoTransformState.CheckElapsed = 0
	local selected = autoTransformState.Selected
	autoTransformState.RequestSerial += 1
	local serial = autoTransformState.RequestSerial
	autoTransformState.Pending = true
	local character, configuredValue, reason = autoTransformState.GetReadyCharacter(selected)
	if serial ~= autoTransformState.RequestSerial then return end
	autoTransformState.Pending = false
	autoTransformState.Status = reason
	autoTransformState.Render()
	if not character or autoTransformState.AttemptElapsed < autoTransformState.RetryDelay then return end
	autoTransformState.AttemptElapsed = 0
	autoTransformState.Pending = true
	local now = os.clock()
	local setOk = pcall(function()
		if tostring(configuredValue.Value) ~= selected or now - autoTransformState.LastSetAt >= 10 then
			serverRemote:FireServer(nil, {
				Module = "TransformationHandler",
				Action = "Set",
				NewValue = selected,
			})
			autoTransformState.LastSetAt = now
		end
	end)
	if not setOk then
		autoTransformState.Pending = false
		autoTransformState.Status = "Set failed; retrying"
		autoTransformState.Render()
		return
	end
	task.delay(0.15, function()
		if serial ~= autoTransformState.RequestSerial then return end
		local readyCharacter, _, currentReason = autoTransformState.GetReadyCharacter(selected, true)
		if serial ~= autoTransformState.RequestSerial then return end
		autoTransformState.Pending = false
		if readyCharacter ~= character then
			autoTransformState.Status = currentReason
			autoTransformState.Render()
			return
		end
		local ok = pcall(function()
			serverRemote:FireServer("Run", {Action = "Terminate"})
			serverRemote:FireServer("Charge", {
				Action = "Execute",
				SecondAction = "Charge",
				ThirdAction = "Transform",
			})
		end)
		autoTransformState.Status = ok and "Activation requested" or "Request failed; retrying"
		autoTransformState.Render()
	end)
end

function qolState.FormMastery.SetStatus(text, color)
	if qolState.FormMastery.StatusLabel then
		qolState.FormMastery.StatusLabel.Text = text
		qolState.FormMastery.StatusLabel.TextColor3 = color or colors.Muted
	end
end

function qolState.FormMastery.GetSelectedMastery()
	if not qolState.FormMastery.Selected then return nil end
	local snapshot = qolState.Unlocks.GetTransformationSnapshot()
	if type(snapshot) ~= "table" then return nil end
	for category, categoryData in pairs(snapshot) do
		local formData = type(categoryData) == "table" and categoryData[qolState.FormMastery.Selected]
		if type(formData) == "table" then
			return tonumber(formData.Mastery), tostring(category), formData
		end
	end
	return nil
end

function qolState.FormMastery.Render()
	local state = qolState.FormMastery
	if not state.SelectorButton or not state.ToggleButton then return end
	if not configStore.FeatureAccess.FormMastery then
		state.SelectorButton.Text = "Select form  //  PREMIUM"
		state.ToggleButton.Text = "Train Mastery: LOCKED"
		state.ToggleButton.BackgroundColor3 = colors.Surface
		state.ToggleButton.TextColor3 = colors.Warning
		return
	end
	state.SelectorButton.Text = state.Selected and (state.Selected .. "  v") or "Select unlocked form  v"
	state.ToggleButton.Text = state.Enabled and "Train Mastery: ON" or "Train Mastery: OFF"
	state.ToggleButton.BackgroundColor3 = state.Enabled and colors.Accent or colors.Surface
	state.ToggleButton.TextColor3 = state.Enabled and colors.Background or colors.Muted
	local current = tonumber(state.CurrentMastery)
	local baseline = tonumber(state.BaselineMastery)
	local gain = current and baseline and math.max(0, current - baseline) or 0
	state.ProgressLabel.Text = string.format(
		"Mastery: %s  |  Session: +%.3f  |  Cycles: %d",
		current and string.format("%.3f", current) or "--",
		gain,
		state.CycleCount
	)
end

function qolState.FormMastery.Select(formName)
	local state = qolState.FormMastery
	local entry = state.FormLookup[formName]
	if not entry then return false end
	state.Selected = formName
	state.CurrentMastery = tonumber(entry.Mastery)
	state.BaselineMastery = state.CurrentMastery
	state.CycleBaseline = state.CurrentMastery
	state.CycleCount = 0
	state.Dropdown.Visible = false
	for optionName, button in pairs(state.OptionButtons) do
		button.BackgroundColor3 = optionName == formName and colors.Accent or colors.Surface
		button.TextColor3 = optionName == formName and colors.Background or colors.Text
	end
	qolState.FormMastery.SetStatus("Ready to train " .. formName .. ".", colors.Success)
	qolState.FormMastery.Render()
	return true
end

function qolState.FormMastery.RefreshForms()
	local state = qolState.FormMastery
	if not configStore.FeatureAccess.FormMastery then return false end
	local snapshot, snapshotError = qolState.Unlocks.GetTransformationSnapshot()
	if type(snapshot) ~= "table" then
		qolState.FormMastery.SetStatus("Could not load form mastery: " .. tostring(snapshotError), colors.DangerHover)
		return false
	end
	table.clear(state.Forms)
	table.clear(state.FormLookup)
	for _, button in pairs(state.OptionButtons) do button:Destroy() end
	table.clear(state.OptionButtons)
	for category, categoryData in pairs(snapshot) do
		if type(categoryData) == "table" then
			for formName, formData in pairs(categoryData) do
				if type(formData) == "table" and formData.Unlocked == true then
					local entry = {
						Name = tostring(formName),
						Category = tostring(category),
						Mastery = tonumber(formData.Mastery) or 0,
					}
					table.insert(state.Forms, entry)
					state.FormLookup[entry.Name] = entry
				end
			end
		end
	end
	table.sort(state.Forms, function(a, b) return a.Name < b.Name end)
	for index, entry in ipairs(state.Forms) do
		local button = create("TextButton", {
			Name = "Form_" .. entry.Name,
			Size = UDim2.new(1, -8, 0, 28),
			BackgroundColor3 = entry.Name == state.Selected and colors.Accent or colors.Surface,
			BorderSizePixel = 0,
			Font = Enum.Font.GothamSemibold,
			Text = string.format("%s  //  %.3f", entry.Name, entry.Mastery),
			TextColor3 = entry.Name == state.Selected and colors.Background or colors.Text,
			TextSize = 9,
			TextXAlignment = Enum.TextXAlignment.Left,
			LayoutOrder = index,
			ZIndex = 81,
		}, state.Dropdown)
		create("UICorner", {CornerRadius = UDim.new(0, 5)}, button)
		state.OptionButtons[entry.Name] = button
		connect(button.Activated, function() qolState.FormMastery.Select(entry.Name) end)
	end
	state.Dropdown.CanvasSize = UDim2.fromOffset(0, 8 + #state.Forms * 31)
	if not state.FormLookup[state.Selected] then
		local playerStats = localPlayer:FindFirstChild("PlayerStats")
		local statData = playerStats and playerStats:FindFirstChild("StatData")
		local misc = statData and statData:FindFirstChild("Misc")
		local configured = misc and misc:FindFirstChild("Transformation")
		local configuredName = configured and tostring(configured.Value)
		state.Selected = state.FormLookup[configuredName] and configuredName
			or (state.Forms[1] and state.Forms[1].Name)
	end
	if state.Selected then qolState.FormMastery.Select(state.Selected) else qolState.FormMastery.Render() end
	return #state.Forms > 0
end

function qolState.FormMastery.RequestTransform()
	local state = qolState.FormMastery
	local character = localPlayer.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local playerStats = localPlayer:FindFirstChild("PlayerStats")
	local statData = playerStats and playerStats:FindFirstChild("StatData")
	local coreStats = statData and statData:FindFirstChild("CoreStats")
	local misc = statData and statData:FindFirstChild("Misc")
	local formValue = coreStats and coreStats:FindFirstChild("Form")
	local configuredValue = misc and misc:FindFirstChild("Transformation")
	if not character or not humanoid or humanoid.Health <= 0 or not formValue or not configuredValue then
		return false, "Waiting for character state"
	end
	local activeForm = tostring(formValue.Value)
	if activeForm == state.Selected then return true, "Active" end
	if activeForm ~= "None" and activeForm ~= "" then
		serverRemote:FireServer("Charge", {Action = "Execute", SecondAction = "DeTransform"})
		return false, "Clearing active form"
	end
	local canTransform = false
	pcall(function()
		local stateManager = require(ReplicatedStorage.Modules.Metadata.ControlData.StateManager)
		canTransform = stateManager.CanPerformAction(character, "Transform") == true
	end)
	if not canTransform then return false, "Waiting for transform state" end
	if tostring(configuredValue.Value) ~= state.Selected then
		serverRemote:FireServer(nil, {
			Module = "TransformationHandler",
			Action = "Set",
			NewValue = state.Selected,
		})
		task.wait(0.15)
	end
	serverRemote:FireServer("Run", {Action = "Terminate"})
	serverRemote:FireServer("Charge", {
		Action = "Execute",
		SecondAction = "Charge",
		ThirdAction = "Transform",
	})
	state.LastTransformAt = os.clock()
	return true, "Activating " .. state.Selected
end

function qolState.FormMastery.SetEnabled(enabled)
	local state = qolState.FormMastery
	if not configStore.FeatureAccess.FormMastery then
		return configStore.ShowPremiumUpgrade("Form Mastery training")
	end
	enabled = enabled == true
	if enabled and not state.Selected then
		qolState.FormMastery.SetStatus("Select an unlocked form first.", colors.DangerHover)
		return false
	end
	state.Enabled = enabled
	state.Dropdown.Visible = false
	state.Busy = false
	state.UpdateElapsed = 0
	state.CycleBaseline = state.CurrentMastery
	if enabled then
		autoTransformState.SetEnabled(false)
		setNpcTargetingEnabled(false)
		state.BaselineMastery = state.CurrentMastery
		state.CycleCount = 0
		qolState.FormMastery.SetStatus("Starting mastery cycle for " .. state.Selected .. "...", colors.Warning)
	else
		qolState.FormMastery.SetStatus("Form mastery training stopped.", colors.Muted)
	end
	qolState.FormMastery.Render()
	return state.Enabled
end

function qolState.FormMastery.Update(deltaTime)
	local state = qolState.FormMastery
	qolState.FormMastery.Render()
	if not state.Enabled or state.Busy or not state.Selected then return end
	state.UpdateElapsed += deltaTime
	if state.UpdateElapsed < 0.4 then return end
	state.UpdateElapsed = 0
	state.Busy = true
	task.spawn(function()
		local ok, updateError = pcall(function()
			local mastery = qolState.FormMastery.GetSelectedMastery()
			if mastery then
				state.CurrentMastery = mastery
				if state.BaselineMastery == nil then state.BaselineMastery = mastery end
			end
			local character = localPlayer.Character
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			local playerStats = localPlayer:FindFirstChild("PlayerStats")
			local statData = playerStats and playerStats:FindFirstChild("StatData")
			local coreStats = statData and statData:FindFirstChild("CoreStats")
			local formValue = coreStats and coreStats:FindFirstChild("Form")
			if not character or not humanoid or humanoid.Health <= 0 or not formValue then
				qolState.FormMastery.SetStatus("Waiting for respawn...", colors.Warning)
				return
			end
			local activeForm = tostring(formValue.Value)
			if activeForm == state.Selected then
				if state.CycleBaseline == nil then state.CycleBaseline = mastery end
				local masteryVerified = mastery and state.CycleBaseline and mastery > state.CycleBaseline + 0.0001
				local timeoutReached = os.clock() - state.LastTransformAt >= 2.5
				if masteryVerified or timeoutReached then
					qolState.FormMastery.SetStatus(
						masteryVerified and "Mastery gained; resetting for the next activation..."
							or "Activation verified; resetting for the next cycle...",
						colors.Success
					)
					if qolState.ResetCharacter() then
						state.CycleCount += 1
						state.CycleBaseline = nil
						state.LastResetAt = os.clock()
					end
				else
					qolState.FormMastery.SetStatus("Form active; verifying mastery gain...", colors.Warning)
				end
				return
			end
			if qolState.ResetCharacterPending or os.clock() - state.LastResetAt < 0.8 then
				qolState.FormMastery.SetStatus("Waiting for respawn...", colors.Warning)
				return
			end
			state.CycleBaseline = mastery
			local sent, reason = qolState.FormMastery.RequestTransform()
			qolState.FormMastery.SetStatus(reason, sent and colors.Warning or colors.Muted)
		end)
		state.Busy = false
		if not ok then qolState.FormMastery.SetStatus("Mastery cycle error: " .. tostring(updateError), colors.DangerHover) end
		qolState.FormMastery.Render()
	end)
end

function qolState.Unlocks.IsFormUnlocked(category, formName)
	local snapshot = qolState.Unlocks.GetTransformationSnapshot()
	local formData = snapshot and snapshot[category] and snapshot[category][formName]
	return type(formData) == "table" and formData.Unlocked == true
end

function qolState.Unlocks.RequestForm(category, formName, raceArgument)
	if qolState.Unlocks.IsFormUnlocked(category, formName) then
		return true, "already"
	end

	local sent, sendError = pcall(function()
		serverRemote:FireServer(nil, {
			Module = "TransformationHandler",
			Action = "GiveTransformation",
			Transformation_Name = formName,
			Race = raceArgument or category,
		})
	end)
	if not sent then
		return false, tostring(sendError)
	end
	task.wait(0.35)
	if qolState.Unlocks.IsFormUnlocked(category, formName) then
		return true, "requested"
	end

	local fallbackSent = false
	if category == "Misc" and formName == "Kaioken" then
		fallbackSent = pcall(function()
			serverRemote:FireServer(nil, {Module = "KingKaiHandler", Action = "GiveKaioKen"})
		end)
	elseif category == "Namekian" and formName == "Giant Namekian" then
		fallbackSent = pcall(function()
			serverRemote:FireServer(nil, {Module = "LordSlugHandler", Action = "GiveGiantNamekian"})
		end)
	end
	if fallbackSent then
		task.wait(0.4)
	end
	return qolState.Unlocks.IsFormUnlocked(category, formName), fallbackSent and "fallback requested" or "server rejected"
end

function qolState.Unlocks.UnlockForms(raceOnly)
	local button = raceOnly and qolState.Unlocks.RaceFormsButton or qolState.Unlocks.AllFormsButton
	local normalText = raceOnly and "Unlock Race Forms" or "Unlock All Forms"
	local requestSerial = qolState.Unlocks.Begin(button, raceOnly and "Unlocking race..." or "Unlocking forms...")
	if not requestSerial then return false end

	local thread = task.spawn(function()
		local snapshot, snapshotError = qolState.Unlocks.GetTransformationSnapshot()
		local okRace, currentRace = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "Race")
		currentRace = okRace and currentRace or nil
		if not snapshot or not currentRace then
			qolState.Unlocks.Finish(button, normalText, requestSerial)
			qolState.Unlocks.SetStatus(
				"Transformation metadata is unavailable: " .. tostring(snapshotError or "race could not be read"),
				colors.DangerHover
			)
			return
		end

		local currentCategory = qolState.Unlocks.GetRaceFormCategory(currentRace, snapshot)
		if raceOnly and not currentCategory then
			qolState.Unlocks.Finish(button, normalText, requestSerial)
			qolState.Unlocks.SetStatus("No race-form category exists for " .. tostring(currentRace) .. ".", colors.DangerHover)
			return
		end

		local targets = {}
		for category, forms in pairs(snapshot) do
			if type(forms) == "table" and (not raceOnly or category == currentCategory) then
				for formName, formData in pairs(forms) do
					if type(formData) == "table" then
						table.insert(targets, {
							Category = category,
							Name = formName,
							RaceArgument = category == currentCategory and currentRace or category,
						})
					end
				end
			end
		end
		table.sort(targets, function(a, b)
			local aCurrent = a.Category == currentCategory
			local bCurrent = b.Category == currentCategory
			if aCurrent ~= bCurrent then
				return aCurrent
			end
			return a.Category == b.Category and a.Name < b.Name or a.Category < b.Category
		end)

		local unlockedCount, alreadyCount = 0, 0
		local failed = {}
		for index, target in ipairs(targets) do
			if unloaded or qolState.Unlocks.RequestSerial ~= requestSerial then return end
			qolState.Unlocks.SetStatus(
				string.format("Unlocking %s (%d/%d)...", target.Name, index, #targets),
				colors.Muted
			)
			local unlocked, reason = qolState.Unlocks.RequestForm(target.Category, target.Name, target.RaceArgument)
			if unlocked then
				if reason == "already" then
					alreadyCount += 1
				else
					unlockedCount += 1
				end
			else
				table.insert(failed, target.Category .. "/" .. target.Name)
			end
			task.wait(0.12)
		end

		if not qolState.Unlocks.Finish(button, normalText, requestSerial) then return end
		if #failed == 0 then
			qolState.Unlocks.SetStatus(
				string.format("Forms verified: %d unlocked, %d already owned.", unlockedCount, alreadyCount),
				colors.Success
			)
		else
			local preview = table.concat(failed, ", ", 1, math.min(3, #failed))
			if #failed > 3 then preview ..= string.format(" (+%d more)", #failed - 3) end
			qolState.Unlocks.SetStatus(
				string.format("Unlocked %d; %d already owned; server rejected %d: %s", unlockedCount, alreadyCount, #failed, preview),
				colors.DangerHover
			)
		end
	end)
	table.insert(scheduledThreads, thread)
	return true
end

function qolState.Unlocks.UnlockRaceForms()
	return qolState.Unlocks.UnlockForms(true)
end

function qolState.Unlocks.UnlockAllForms()
	return qolState.Unlocks.UnlockForms(false)
end

connect(qolState.ProfileEditor.RaceSelectorButton.Activated, function()
	qolState.ProfileEditor.TraitDropdown.Visible = false
	qolState.ProfileEditor.RaceDropdown.Visible = not qolState.ProfileEditor.RaceDropdown.Visible
