connect(RunService.Heartbeat, function(deltaTime)
	npcRefreshElapsed += deltaTime
	if npcRefreshElapsed >= 3 then
		npcRefreshElapsed = 0
		if currentTab == "NPCs" and npcDropdownList.Visible then
			refreshNpcTypes()
		end
		if npcTargetingEnabled and selectedNpcType == npcSafety.StrongestOptionName
			and activeNpcTarget and not npcSafety.GripMode and not npcSafety.LootMode
			and not npcSafety.RecoveryMode and not npcSafety.PlayerEvadeMode then
			local strongest, _, _, _, strongestPower = findNearestNpc(selectedNpcType)
			local currentPower = npcSafety.GetNpcPowerLevel(activeNpcTarget) or -math.huge
			if strongest and strongest ~= activeNpcTarget and strongestPower and strongestPower > currentPower then
				clearNpcConstraintRig()
				npcAcquireElapsed = 1
				setNpcStatus(string.format("A stronger safe NPC appeared (%.0f PL); switching targets...", strongestPower), colors.Success)
			end
		end
	end
	npcSafety.WatchlistScanElapsed += deltaTime
	if npcSafety.WatchlistScanElapsed >= (npcSafety.WatchlistScanInterval or 2.5) then
		npcSafety.WatchlistScanElapsed = 0
		npcSafety.UpdateWatchlistNpcAlerts()
	end
	autoTransformState.Update(deltaTime)
	qolState.FormMastery.Update(deltaTime)
	local autoFoodBusy = qolState.AutoFood.Update(deltaTime)

	if not npcTargetingEnabled then
		-- Keep the standalone QoL noclip reliable even when Roblox or another
		-- character controller changes a part's collision state after spawning.
		applyNpcNoclip(localPlayer.Character)
		return
	end
	local character = localPlayer.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local characterRoot = character and character:FindFirstChild("HumanoidRootPart")
	if not humanoid or humanoid.Health <= 0 or not characterRoot then
		clearNpcConstraintRig()
		setNpcStatus("Waiting for a living character...", colors.Muted)
		return
	end
	-- AutoFarm always requires noclip, independently of the QoL button. Reapply
	-- it every Heartbeat to every current and newly inserted character BasePart.
	applyNpcNoclip(character, true)
	if npcSafety.IsExcludedFarmTarget(activeNpcTarget) or npcSafety.IsExcludedFarmTarget(npcSafety.GripTarget) then
		clearNpcConstraintRig()
		npcSafety.ResetPostCombat()
		npcSafety.SpawnDestination, npcSafety.SpawnSource = nil, nil
		npcAcquireElapsed = 1
	end
	npcSafety.RetargetContestedNpc()
	npcSafety.UpdatePlayerProximityThreat()
	npcSafety.UpdateHideMode(character, humanoid, characterRoot)
	if npcSafety.UpdatePlayerEvade(character, humanoid, characterRoot) then
		return
	end
	if npcSafety.UpdateLootWait(deltaTime, character, humanoid, characterRoot) then
		return
	end
	local attackTargetRoot = activeNpcTarget and getNpcRoot(activeNpcTarget)
	if attackTargetRoot and not npcSafety.LootMode and not npcSafety.DirectLight.Enabled
		and not npcSafety.GripMode and not npcSafety.IsKnocked(activeNpcTarget)
		and not npcSafety.AboveTransitionStage
		and (npcSafety.PositionMode ~= "FrontBehind" or npcSafety.FrontBehindPhase == "Front")
		and (attackTargetRoot.Position - characterRoot.Position).Magnitude <= 30 then
		npcAttackElapsed += deltaTime
		if npcAttackElapsed >= npcSafety.AttackInterval then
			npcAttackElapsed %= npcSafety.AttackInterval
			-- Core Combat only scans a box 3.5 studs in front of the root.
			if (attackTargetRoot.Position - characterRoot.Position).Magnitude > 0.05 then
				characterRoot.CFrame = CFrame.lookAt(characterRoot.Position, attackTargetRoot.Position)
			end
			local attackSent = npcSafety.SendLightAttack()
			if attackSent then
				npcSafety.NormalAttackAttempts += 1
				local attackNow = os.clock()
				npcSafety.LastAttackInputAt = attackNow
				npcSafety.BurstHits = 0
				npcSafety.BurstResetUntil = 0
				if npcApproachPhase == "Rise"
					and (attackTargetRoot.Position - characterRoot.Position).Magnitude <= 14
					and npcSafety.ModeFirstAttackAt == 0 then
					npcSafety.ModeFirstAttackAt = attackNow
				end
			else
				setNpcStatus("The normal light-attack controller is unavailable.", colors.DangerHover)
			end
		end
	else
		npcAttackElapsed = 0
	end
	if autoFoodBusy then
		return
	end
	if npcSafety.PositionMode == "Below" then
		enforceNpcUndergroundCeiling(
			character,
			characterRoot,
			npcSafety.GripMode and npcSafety.GripClearance or npcSafety.CombatClearance
		)
	end
	npcSafety.PlayerScanElapsed += deltaTime
	if npcSafety.PlayerScanElapsed >= 0.5 then
		npcSafety.PlayerScanElapsed = 0
		local nearbyPlayer = npcSafety.ProximityThreatPlayer
		local distance = npcSafety.ProximityThreatDistance
		if nearbyPlayer and distance and npcSafety.PlayerProximityConfirmed and npcSafety.ServerHopEnabled
			and not npcSafety.HideMode then
			npcSafety.RequestServerHop(string.format("%s at %.0f studs", nearbyPlayer.Name, distance), nearbyPlayer)
			if npcSafety.PlayerEvadeMode then
				return
			end
		end
	end

	local healthRatio = humanoid.MaxHealth > 0 and humanoid.Health / humanoid.MaxHealth or 0
	local tookDamage = npcSafety.LastCharacterHealth
		and humanoid.Health < npcSafety.LastCharacterHealth - 0.01
	-- Normal lakes around surface NPCs are allowed. The broken bottom-water case
	-- is identifiable because the player is swimming far beneath the target.
	local bottomWaterTrap = humanoid:GetState() == Enum.HumanoidStateType.Swimming
		and attackTargetRoot and attackTargetRoot.Position.Y - characterRoot.Position.Y >= 25
	if activeNpcTarget and npcSafety.PositionMode == "Below" and not npcSafety.UsesStrictBelowPosition()
		and (tookDamage or bottomWaterTrap) then
		if tookDamage then
			npcSafety.LastDamageAt = os.clock()
		end
		npcSafety.LockAboveForCurrentTarget(bottomWaterTrap and "bottom-map water trap detected" or "incoming damage")
	end
	npcSafety.LastCharacterHealth = humanoid.Health
	local nearPanic = healthRatio <= math.min(0.95,
		npcSafety.PanicHealthRatio + npcSafety.SafetyRetargetBufferRatio)
	if nearPanic and activeNpcTarget and not npcSafety.GripMode and not npcSafety.LootMode
		and not npcSafety.PlayerEvadeMode and os.clock() - npcSafety.LastSafetyRetargetAt >= npcSafety.SafetyRetargetCooldown then
		local currentCrowd = countNearbyNpcs(activeNpcTarget, 55)
		if currentCrowd > 0 then
			local saferTarget, _, saferCrowd = findNearestNpc(selectedNpcType, activeNpcTarget)
			if saferTarget and saferCrowd == 0 and attachToNpc(saferTarget) then
				npcSafety.LastSafetyRetargetAt = os.clock()
				setNpcStatus(string.format("Health near panic; switching to isolated %s before recovering...",
					tostring(selectedNpcType)), colors.Warning)
				return
			end
		end
	end
	if healthRatio <= npcSafety.PanicHealthRatio and not npcSafety.RecoveryMode then
		npcSafety.BeginRecovery(character, humanoid, characterRoot)
	end
	if npcSafety.RecoveryMode then
		local resumeRatio = npcSafety.RecoveryResumeRatio
			or math.min(1, npcSafety.PanicHealthRatio + npcSafety.RecoveryResumeBufferRatio)
		if healthRatio >= resumeRatio then
			npcSafety.RecoveryMode = false
			npcSafety.RecoveryPosition = nil
			npcSafety.RecoveryResumeRatio = nil
			clearNpcConstraintRig()
			npcAcquireElapsed = 1
			setNpcStatus(string.format("Health recovered to %.0f%%; resuming %s autofarm...",
				healthRatio * 100, tostring(selectedNpcType)), colors.Success)
		else
			if not npcLinearVelocity or not npcLinearVelocity.Parent or not npcSafety.RecoveryPosition then
				npcSafety.BeginRecovery(character, humanoid, characterRoot)
			end
			local recoveryDelta = npcSafety.RecoveryPosition - characterRoot.Position
			local recoveryDistance = recoveryDelta.Magnitude
			local recoverySpeed = math.min(500, math.max(25, recoveryDistance * 4))
			npcLinearVelocity.VectorVelocity = recoveryDistance > 0.5
				and recoveryDelta.Unit * recoverySpeed
				or Vector3.zero
			return
		end
	end

	if npcSafety.ChestLootEnabled and not npcSafety.LootMode and os.clock() >= npcSafety.LootScanCooldownUntil then
		npcSafety.ChestScanElapsed += deltaTime
		if npcSafety.ChestScanElapsed >= 0.45 then
			npcSafety.ChestScanElapsed = 0
			local chestGui = playerGui:FindFirstChild("DropChestGui")
			local chestPrompt, chestPosition, chestDistance = npcSafety.FindNearbyChestPrompt(characterRoot.Position, 90)
			if chestGui and chestGui:IsA("ScreenGui") and chestGui.Enabled then
				npcSafety.BeginLootWait(character, humanoid, characterRoot, characterRoot.Position, nil,
					"Open chest detected; pausing autofarm to take all loot...")
			elseif chestPrompt then
				npcSafety.BeginLootWait(character, humanoid, characterRoot, chestPosition, chestPrompt,
					string.format("Nearby chest detected (%.0f studs); looting it before autofarming...", chestDistance))
			end
		end
	end

	if activeNpcTarget and npcSafety.IsKnocked(activeNpcTarget) and getNpcRoot(activeNpcTarget)
		and not npcSafety.GripMode then
		configStore.Session.RecordKill(activeNpcTarget)
		npcSafety.GripMode = true
		npcSafety.GripElapsed = 0
		npcSafety.GripTarget = activeNpcTarget
		npcSafety.GripConfirmed = false
	end

	if npcSafety.GripMode and npcSafety.GripTarget then
		local gripTarget = npcSafety.GripTarget
		local gripping = character:FindFirstChild("Gripping") or gripTarget:FindFirstChild("GettingGripped")
		if gripping then
			npcSafety.GripConfirmed = true
			if npcLinearVelocity then
				npcLinearVelocity.Enabled = false
			end
			if npcAlignOrientation then
				npcAlignOrientation.Enabled = false
			end
			humanoid.PlatformStand = false
			setNpcStatus("Grip in progress; waiting for the dropped chest...", colors.Success)
			return
		elseif npcSafety.GripConfirmed or not gripTarget.Parent or not getNpcRoot(gripTarget) then
			npcSafety.BeginLootWait(character, humanoid, characterRoot)
			return
		elseif not npcSafety.IsKnocked(gripTarget) then
			if isLivingNpcOfType(gripTarget, selectedNpcType) then
				npcSafety.GripMode = false
				npcSafety.GripElapsed = 0
				npcSafety.GripTarget = nil
				npcSafety.GripConfirmed = false
				if npcLinearVelocity then
					npcLinearVelocity.Enabled = true
				end
				if npcAlignOrientation then
					npcAlignOrientation.Enabled = true
				end
			else
				npcSafety.BeginLootWait(character, humanoid, characterRoot)
				return
			end
		end
	end

	if npcSafety.ChestLootEnabled and activeNpcTarget and not npcSafety.GripMode
		and not isLivingNpcOfType(activeNpcTarget, selectedNpcType) then
		configStore.Session.RecordKill(activeNpcTarget)
		npcSafety.BeginLootWait(character, humanoid, characterRoot, npcSafety.LastTargetPosition, nil,
			"Target defeated; waiting for its dropped chest...")
		return
	end

	npcAcquireElapsed += deltaTime
	local activeTargetUsable = activeNpcTarget and (isLivingNpcOfType(activeNpcTarget, selectedNpcType)
		or (npcSafety.GripMode and npcSafety.IsKnocked(activeNpcTarget) and getNpcRoot(activeNpcTarget)))
	if not activeNpcTarget or not activeTargetUsable
		or not npcLinearVelocity or not npcLinearVelocity.Parent then
		if activeNpcTarget and not isLivingNpcOfType(activeNpcTarget, selectedNpcType) then
			clearNpcConstraintRig()
			npcSafety.SpawnDestination = nil
			npcSafety.SpawnSource = nil
		end
		if npcAcquireElapsed >= 0.25 then
			npcAcquireElapsed = 0
			local nearest, distance, nearbyNpcCount, contestedNpcCount, targetPower = findNearestNpc(selectedNpcType)
			if nearest and attachToNpc(nearest) then
				npcSafety.SpawnDestination = nil
				npcSafety.SpawnSource = nil
				npcSafety.SpawnWaitReason = nil
				setNpcStatus(selectedNpcType == npcSafety.StrongestOptionName
					and string.format("Targeting strongest safe NPC: %s (%.0f PL, %.0f studs away).", nearest.Name, targetPower or 0, distance)
					or string.format(isBetaEnvironment
						and "Targeting %s (%.0f studs away, %d nearby NPC%s). Teleporting beneath it..."
						or "Targeting %s (%.0f studs away, %d nearby NPC%s). Gliding beneath it...",
						nearest.Name, distance, nearbyNpcCount, nearbyNpcCount == 1 and "" or "s"), colors.Success)
			elseif contestedNpcCount and contestedNpcCount > 0 then
				npcSafety.SpawnDestination = nil
				npcSafety.SpawnSource = nil
				npcSafety.SpawnWaitReason = string.format(
					"All %d live %s target%s are within %d studs of another player; " ..
						(npcSafety.ServerHopEnabled and "hopping servers..." or "scanning for a safe target..."),
					contestedNpcCount, tostring(selectedNpcType), contestedNpcCount == 1 and "" or "s",
					npcSafety.PlayerRange)
				if npcSafety.ServerHopEnabled then
					local threatPlayer = npcSafety.GetNearbyPlayer(characterRoot.Position, math.huge)
					npcSafety.RequestServerHop(npcSafety.SpawnWaitReason, threatPlayer)
					if npcSafety.PlayerEvadeMode then
						return
					end
				end
			else
				npcSafety.SpawnDestination, npcSafety.SpawnSource = npcSafety.FindSpawnAnchor(selectedNpcType, characterRoot.Position)
			end
		end
		if not activeNpcTarget then
			if npcSafety.SpawnDestination then
				npcSafety.ReacquireHoldPosition = nil
				npcSafety.NavigateToSpawn(character, humanoid, characterRoot, npcSafety.SpawnDestination, npcSafety.SpawnSource)
			else
				npcSafety.HoldWhileReacquiring(character, humanoid, characterRoot)
				setNpcStatus(npcSafety.SpawnWaitReason
					or ("No live " .. tostring(selectedNpcType) .. "; holding position safely while reacquiring."), colors.Muted)
			end
		end
		return
	end

	local targetRoot = getNpcRoot(activeNpcTarget)
	if not targetRoot then
		clearNpcConstraintRig()
		npcAcquireElapsed = 1
		return
	end

	local characterPosition = characterRoot.Position
	local targetPosition = targetRoot.Position
	npcSafety.LastTargetPosition = targetPosition
	local targetKnocked = npcSafety.IsKnocked(activeNpcTarget)
	local targetHumanoid = activeNpcTarget:FindFirstChildOfClass("Humanoid")
	local now = os.clock()
	if targetHumanoid then
		if npcSafety.ObservedTargetHealth and targetHumanoid.Health < npcSafety.ObservedTargetHealth - 0.01 then
			npcSafety.LastConfirmedHitAt = now
			npcSafety.TargetLastConfirmedHitAt = now
			npcSafety.PendingHit = false
			if npcSafety.LastModeConfirmedHitAt == 0 or now - npcSafety.LastModeConfirmedHitAt >= 0.08 then
				npcSafety.ModeConfirmedHits += 1
			end
			npcSafety.LastModeConfirmedHitAt = now
			if npcSafety.PositionMode == "FrontBehind" and npcSafety.FrontBehindPhase == "Front" then
				npcSafety.FrontBehindConfirmedHits += 1
				if npcSafety.FrontBehindConfirmedHits >= 5 then
					npcSafety.FrontBehindPhase = "Behind"
					npcSafety.FrontBehindRecoverUntil = now + npcSafety.FrontBehindRecoveryDuration
					npcAttackElapsed = 0
					setNpcStatus("Five light hits confirmed; moving behind during combo recovery...", colors.Success)
				end
			end
			if npcSafety.PositionMode == "Above" then
				npcSafety.AboveDistanceConfirmed = true
			end
			if npcSafety.ModeConfirmedHits == 1 then
				setNpcStatus(string.format("%s hit confirmed at %.2f studs; continuing light-attack bursts...",
					npcSafety.PositionMode, npcSafety.PositionMode == "Above"
						and npcSafety.CurrentAboveDistance or npcSafety.GetProfile(selectedNpcType).AttackDepth),
					colors.Success)
			end
			if npcSafety.PositionMode == "Above" and npcSafety.SelectedPositionMode == "Below"
				and npcSafety.LockedAboveTarget ~= activeNpcTarget
				and npcSafety.ModeConfirmedHits >= npcSafety.ConsistentHitCount
				and npcSafety.NextBelowProbeAt == 0 then
				npcSafety.NextBelowProbeAt = now + npcSafety.AboveHoldBeforeProbe
			elseif npcSafety.PositionMode == "Below" and npcSafety.BelowProbeActive
				and npcSafety.ModeConfirmedHits >= npcSafety.ConsistentHitCount then
				npcSafety.AdaptiveFallbackActive = false
				npcSafety.BelowProbeActive = false
				setNpcStatus("Below positioning confirmed " .. npcSafety.ModeConfirmedHits
					.. " hits; keeping the below position.", colors.Success)
			end
		end
		npcSafety.ObservedTargetHealth = targetHumanoid.Health
	end
	local recentConfirmedHit = npcSafety.LastConfirmedHitAt > 0 and os.clock() - npcSafety.LastConfirmedHitAt <= 1.1
	local profile = npcSafety.GetProfile(selectedNpcType)
	local approachDepth = profile.AttackDepth
	if targetKnocked then
		approachDepth = math.min(approachDepth, 6)
	elseif npcSafety.PositionMode == "Below" or npcSafety.SelectedPositionMode == "Below" then
		approachDepth = 10
	end
	local targetDistance = (targetPosition - characterPosition).Magnitude
	if not targetKnocked and targetDistance <= 30 and npcSafety.TargetCombatStartedAt == 0 then
		npcSafety.TargetCombatStartedAt = now
		npcSafety.LoopTargetPosition = targetPosition
		npcSafety.LoopPlayerPosition = characterPosition
	end
	if npcSafety.TargetCombatStartedAt > 0 and not targetKnocked
		and npcSafety.SelectedPositionMode == "Below"
		and not npcSafety.UsesStrictBelowPosition()
		and npcSafety.LockedAboveTarget ~= activeNpcTarget then
		local targetJumped = npcSafety.LoopTargetPosition
			and (targetPosition - npcSafety.LoopTargetPosition).Magnitude >= npcSafety.LoopJumpDistance
		local playerJumped = npcSafety.LoopPlayerPosition
			and (characterPosition - npcSafety.LoopPlayerPosition).Magnitude >= npcSafety.LoopJumpDistance
		if targetJumped or playerJumped then
			if npcSafety.LoopWindowStartedAt == 0
				or now - npcSafety.LoopWindowStartedAt > npcSafety.LoopWindowDuration then
				npcSafety.LoopWindowStartedAt = now
				npcSafety.LoopJumpCount = 0
			end
			npcSafety.LoopJumpCount += 1
			if npcSafety.LoopJumpCount >= 2 then
				npcSafety.LockAboveForCurrentTarget("teleport loop detected")
			end
		elseif npcSafety.LoopWindowStartedAt > 0
			and now - npcSafety.LoopWindowStartedAt > npcSafety.LoopWindowDuration then
			npcSafety.LoopWindowStartedAt = 0
			npcSafety.LoopJumpCount = 0
		end
		npcSafety.LoopTargetPosition = targetPosition
		npcSafety.LoopPlayerPosition = characterPosition

		local lastTargetHitOrStart = npcSafety.TargetLastConfirmedHitAt > 0
			and npcSafety.TargetLastConfirmedHitAt or npcSafety.TargetCombatStartedAt
		if now - lastTargetHitOrStart >= npcSafety.TargetNoHitLockDelay then
			npcSafety.LockAboveForCurrentTarget("no confirmed hit for 10 seconds")
		end
	end
	if npcApproachPhase == "Rise" and not targetKnocked and targetDistance <= 14
		and npcSafety.ModeFirstAttackAt > 0 then
		local lastModeHitOrAttempt = npcSafety.LastModeConfirmedHitAt > 0
			and npcSafety.LastModeConfirmedHitAt or npcSafety.ModeFirstAttackAt
		if npcSafety.PositionMode == "Below" and now - lastModeHitOrAttempt >= npcSafety.NoHitTimeout then
			npcSafety.ActivateAboveFallback(npcSafety.ModeConfirmedHits == 0
				and "no confirmed hit" or "hits stopped")
		elseif npcSafety.PositionMode == "Above" then
			if npcSafety.SelectedPositionMode == "Below"
				and npcSafety.LockedAboveTarget ~= activeNpcTarget
				and npcSafety.NextBelowProbeAt > 0 and now >= npcSafety.NextBelowProbeAt then
				npcSafety.BeginBelowProbe()
			elseif now - lastModeHitOrAttempt >= npcSafety.NoHitTimeout then
				if not npcSafety.AboveDistanceConfirmed
					and npcSafety.CurrentAboveDistance > npcSafety.MinimumAboveDistance then
					npcSafety.CurrentAboveDistance = math.max(
						npcSafety.MinimumAboveDistance,
						npcSafety.CurrentAboveDistance - npcSafety.AboveDistanceStep
					)
					npcSafety.ModeFirstAttackAt = 0
					npcSafety.ModeConfirmedHits = 0
					npcSafety.LastModeConfirmedHitAt = 0
					setNpcStatus(string.format("Above attacks missed; moving closer to %.2f studs...",
						npcSafety.CurrentAboveDistance), colors.Warning)
				elseif not npcSafety.AboveDistanceConfirmed and npcSafety.SelectedPositionMode == "Below" then
					npcSafety.BeginBelowProbe()
				else
					npcSafety.ModeFirstAttackAt = now
					setNpcStatus("Holding the confirmed safe attack edge; continuing light-attack bursts...", colors.Success)
				end
			end
		end
	end
	local horizontalDelta = Vector3.new(targetPosition.X - characterPosition.X, 0, targetPosition.Z - characterPosition.Z)
	local horizontalDistance = horizontalDelta.Magnitude
	local currentGroundY = getGroundYAt(characterPosition, character)
	local targetGroundY = getGroundYAt(targetPosition, character)
	local desiredPosition
	if npcSafety.PositionMode == "Above" and npcSafety.AboveTransitionStage
		and npcSafety.AboveTransitionOffset then
		-- This is an absolute world-space waypoint. Keeping it fixed prevents an
		-- aggroed NPC from dragging the transition point away while it chases us.
		local sidePosition = npcSafety.AboveTransitionOffset
		if npcSafety.AboveTransitionStage == "Shift" then
			desiredPosition = Vector3.new(sidePosition.X, characterPosition.Y, sidePosition.Z)
			local shiftDelta = Vector2.new(sidePosition.X - characterPosition.X, sidePosition.Z - characterPosition.Z)
			if shiftDelta.Magnitude <= 2.5 or now - npcSafety.ModeEnteredAt >= 1.5 then
				npcSafety.AboveTransitionStage = "Rise"
				npcSafety.ModeEnteredAt = now
			end
		elseif npcSafety.AboveTransitionStage == "Rise" then
			desiredPosition = Vector3.new(sidePosition.X, targetPosition.Y + npcSafety.CurrentAboveDistance + 3, sidePosition.Z)
			if (desiredPosition - characterPosition).Magnitude <= 2.5 or now - npcSafety.ModeEnteredAt >= 1.5 then
				npcSafety.AboveTransitionStage = "Approach"
				npcSafety.ModeEnteredAt = now
			end
		else
			desiredPosition = Vector3.new(targetPosition.X, targetPosition.Y + npcSafety.CurrentAboveDistance, targetPosition.Z)
			if (desiredPosition - characterPosition).Magnitude <= 1.25 or now - npcSafety.ModeEnteredAt >= 2 then
				npcSafety.AboveTransitionStage = nil
				npcSafety.AboveTransitionOffset = nil
				npcSafety.ModeEnteredAt = now
				setNpcStatus("Safely above " .. activeNpcTarget.Name .. "; resuming light-attack bursts...", colors.Success)
			end
		end
	end

	-- Underground travel intentionally puts the player far below the target, so
	-- only diagnose cliff trouble after the normal approach has reached Rise.
	local cliffPositionBad = npcSafety.PositionMode == "Below" and npcApproachPhase == "Rise"
		and not targetKnocked and targetHumanoid
		and npcSafety.IsCliffPositionBad(characterRoot, targetHumanoid, targetRoot)
	if cliffPositionBad then
		npcSafety.CliffBadElapsed += deltaTime
	else
		npcSafety.CliffBadElapsed = 0
	end
	if npcSafety.CliffBadElapsed >= 0.75
		and not npcSafety.LurePoint
		and now >= npcSafety.NextLureSearchAt then
		npcSafety.NextLureSearchAt = now + npcSafety.LureSearchInterval
		npcSafety.LurePoint = npcSafety.FindFlatLurePoint(character, characterRoot, targetRoot)
		if npcSafety.LurePoint then
			npcSafety.LureUntil = now + npcSafety.LureTimeout
			npcSafety.LureArrivedAt = 0
			npcSafety.CliffBadElapsed = 0
			npcApproachPhase = "Lure"
			setNpcStatus(activeNpcTarget.Name .. " climbed into bad terrain; luring it toward flat ground...", colors.Success)
		end
	end

	if npcSafety.LurePoint then
		local lureTargetDelta = targetPosition - npcSafety.LurePoint
		local lureTargetHorizontal = Vector2.new(lureTargetDelta.X, lureTargetDelta.Z).Magnitude
		local lurePosition = npcSafety.LurePoint - Vector3.new(0, npcSafety.CombatClearance, 0)
		local playerReachedLurePoint = (lurePosition - characterPosition).Magnitude < 3
		if playerReachedLurePoint and npcSafety.LureArrivedAt == 0 then
			npcSafety.LureArrivedAt = now
		elseif not playerReachedLurePoint then
			npcSafety.LureArrivedAt = 0
		end
		local targetReachedFlatArea = lureTargetHorizontal < 28
			and math.abs(lureTargetDelta.Y) < 12
			and (not targetHumanoid or targetHumanoid:GetState() ~= Enum.HumanoidStateType.Climbing)
		local lureHoldComplete = npcSafety.LureArrivedAt > 0 and now - npcSafety.LureArrivedAt >= 1.25

		if targetReachedFlatArea or lureHoldComplete or now >= npcSafety.LureUntil then
			npcSafety.LurePoint = nil
			npcSafety.LureUntil = 0
			npcSafety.LureArrivedAt = 0
			npcSafety.CliffBadElapsed = 0
			npcApproachPhase = "Travel"
			setNpcStatus(targetReachedFlatArea
				and (activeNpcTarget.Name .. " reached open ground; resuming normal positioning...")
				or "Flat-ground lure timed out; resuming normal positioning...", colors.Success)
		else
			-- Hold just beneath the sampled flat ground. The NPC remains aggroed but
			-- must leave the cliff to close the horizontal distance.
			desiredPosition = lurePosition
			npcApproachPhase = "Lure"
		end
	end

	if not desiredPosition and npcSafety.PositionMode == "FrontBehind" and not targetKnocked then
		if npcSafety.FrontBehindPhase == "Behind" and now >= npcSafety.FrontBehindRecoverUntil then
			npcSafety.FrontBehindPhase = "Front"
			npcSafety.FrontBehindConfirmedHits = 0
			npcSafety.FrontBehindRecoverUntil = 0
			setNpcStatus("Combo recovery finished; returning in front for the next light chain...", colors.Success)
		end
		local targetForward = Vector3.new(targetRoot.CFrame.LookVector.X, 0, targetRoot.CFrame.LookVector.Z)
		if targetForward.Magnitude < 0.1 then
			targetForward = Vector3.new(0, 0, -1)
		else
			targetForward = targetForward.Unit
		end
		local sideMultiplier = npcSafety.FrontBehindPhase == "Behind" and -1 or 1
		local horizontalPosition = targetPosition
			+ targetForward * npcSafety.FrontAttackDistance * sideMultiplier
		desiredPosition = Vector3.new(horizontalPosition.X, targetPosition.Y, horizontalPosition.Z)
		npcApproachPhase = "Rise"
	end

	if not desiredPosition then
		if npcApproachPhase ~= "Rise" and currentGroundY and characterPosition.Y > currentGroundY - 5 then
			npcApproachPhase = "Descend"
		end
		if npcApproachPhase == "Descend" then
			local descentY = (currentGroundY or characterPosition.Y) - npcSafety.TravelDepth
			desiredPosition = Vector3.new(characterPosition.X, descentY, characterPosition.Z)
			if not currentGroundY or characterPosition.Y <= currentGroundY - npcSafety.TravelDepth + 3 then
				npcApproachPhase = "Travel"
				setNpcStatus("Safely underground. Travelling beneath " .. activeNpcTarget.Name .. "...", colors.Success)
			end
		elseif npcApproachPhase == "Travel" then
			if horizontalDistance <= 12 then
				npcApproachPhase = "Rise"
				setNpcStatus("Directly beneath " .. activeNpcTarget.Name
					.. (isBetaEnvironment and "; teleporting up to its feet..." or "; gliding up to its feet..."), colors.Success)
			end
			local currentSafeY = currentGroundY and currentGroundY - npcSafety.TravelDepth or characterPosition.Y
			local targetSafeY = targetGroundY and targetGroundY - npcSafety.TravelDepth or targetPosition.Y - npcSafety.TravelDepth
			local travelY = math.min(currentSafeY, targetSafeY, targetPosition.Y - npcSafety.TravelDepth)
			local avoidance = getPlayerAvoidance(characterPosition)
			desiredPosition = Vector3.new(targetPosition.X, travelY, targetPosition.Z) + avoidance
		else
			if horizontalDistance > 40 and not recentConfirmedHit then
				npcApproachPhase = "Travel"
				setNpcStatus(activeNpcTarget.Name .. " moved away; dropping to travel depth again...", colors.Success)
			end
			if npcSafety.PositionMode == "Above" and not targetKnocked then
				npcSafety.AttackAnchorY = nil
				desiredPosition = Vector3.new(targetPosition.X, targetPosition.Y + npcSafety.CurrentAboveDistance, targetPosition.Z)
			else
				local undergroundMargin = targetKnocked and npcSafety.GripClearance or npcSafety.CombatClearance
				local maximumUndergroundY = targetGroundY and targetGroundY - undergroundMargin or targetPosition.Y - approachDepth
				local calculatedAttackY = math.min(targetPosition.Y - approachDepth, maximumUndergroundY)
				if targetKnocked then
					npcSafety.AttackAnchorY = nil
				elseif not recentConfirmedHit or not npcSafety.AttackAnchorY then
					npcSafety.AttackAnchorY = calculatedAttackY
				end
				local attackY = recentConfirmedHit and npcSafety.AttackAnchorY or calculatedAttackY
				desiredPosition = Vector3.new(targetPosition.X, attackY, targetPosition.Z)
			end
		end
	end
	local shouldPlatformStand = npcApproachPhase ~= "Rise" or npcSafety.PositionMode == "Above"
	if humanoid.PlatformStand ~= shouldPlatformStand then
		humanoid.PlatformStand = shouldPlatformStand
	end
	-- The below-target rig points the character upward so normal melee hitboxes
	-- reach the NPC's feet. When noclip recovery moves above the NPC, invert that
	-- pitch; otherwise the character continues attacking away from the target.
	if npcAlignOrientation then
		if npcSafety.PositionMode == "FrontBehind" then
			local faceDelta = Vector3.new(targetPosition.X - characterPosition.X, 0, targetPosition.Z - characterPosition.Z)
			if faceDelta.Magnitude >= 0.1 then
				npcAlignOrientation.CFrame = CFrame.lookAt(Vector3.zero, faceDelta.Unit)
			end
		else
			local combatPitch = npcSafety.PositionMode == "Above" and -90 or 90
			npcAlignOrientation.CFrame = CFrame.Angles(math.rad(combatPitch), 0, 0)
		end
	end

	local movementDelta = desiredPosition - characterPosition
	local movementDistance = movementDelta.Magnitude
	npcSafety.MovementSampleElapsed += deltaTime
	if npcSafety.MovementSampleElapsed >= 0.5 then
		local sampleDuration = npcSafety.MovementSampleElapsed
		local madeProgress = npcSafety.MovementSampleDistance == nil
			or npcSafety.MovementSampleDistance - movementDistance >= 0.75
		if npcSafety.PositionMode == "Below" and npcApproachPhase == "Rise"
			and movementDistance > 4 and not madeProgress then
			npcSafety.MovementStallElapsed += sampleDuration
		else
			npcSafety.MovementStallElapsed = math.max(0, npcSafety.MovementStallElapsed - sampleDuration)
		end
		npcSafety.MovementSampleElapsed = 0
		npcSafety.MovementSamplePosition = characterPosition
		npcSafety.MovementSampleDistance = movementDistance
		if npcSafety.MovementStallElapsed >= 1.5 and not npcSafety.UsesStrictBelowPosition() then
			npcSafety.ActivateAboveFallback("movement stalled or rubberbanded")
		end
	end
	local speed = getNpcGlideSpeed(math.max(horizontalDistance, movementDistance))
	if npcApproachPhase == "Lure" then
		speed = math.min(speed, 55)
	elseif npcSafety.PositionMode == "FrontBehind" then
		speed = math.min(speed, 90)
	elseif npcSafety.PositionMode == "Above" and npcApproachPhase == "Rise" then
		speed = math.min(speed, 70)
	elseif npcApproachPhase == "Descend" then
		speed = math.min(speed, 300)
	end
	npcCurrentGlideSpeed = speed
	local commandedSpeed = math.min(speed, math.max(18, movementDistance * 5))
	if recentConfirmedHit and npcApproachPhase == "Rise" and movementDistance > 0.35 then
		commandedSpeed = math.max(commandedSpeed, math.min(speed, 36))
	end
	if not applyUpdatedAutofarmMovement(characterRoot, desiredPosition, movementDelta, movementDistance, commandedSpeed) then
		npcLinearVelocity.VectorVelocity = movementDistance > 0.35
			and movementDelta.Unit * commandedSpeed
			or Vector3.zero
	end

	local distance = (targetRoot.Position - characterRoot.Position).Magnitude
	if targetKnocked then
		configStore.Session.RecordKill(activeNpcTarget)
		npcSafety.GripMode = true
		npcSafety.GripTarget = activeNpcTarget
		npcSafety.GripElapsed += deltaTime
		if npcLinearVelocity then
			npcLinearVelocity.Enabled = true
		end
		if npcAlignOrientation then
			npcAlignOrientation.Enabled = true
		end
		humanoid.PlatformStand = false
		if character:FindFirstChild("Gripping") or activeNpcTarget:FindFirstChild("GettingGripped") then
			npcSafety.GripConfirmed = true
			npcLinearVelocity.Enabled = false
			npcAlignOrientation.Enabled = false
			setNpcStatus("Grip in progress; holding position until it completes...", colors.Success)
		elseif npcApproachPhase == "Rise" and horizontalDistance <= 3.5 and distance <= 9.5
			and npcSafety.GripElapsed >= 0.75 then
			npcSafety.GripElapsed = 0
			if npcSafety.SendKey(Enum.KeyCode.B) then
				setNpcStatus(string.format("%s is knocked; pressing B to grip (%.1f studs).", activeNpcTarget.Name, distance), colors.Success)
			else
				setNpcStatus("Normal B-key input is unavailable for gripping.", colors.DangerHover)
			end
		else
			setNpcStatus(string.format("%s is knocked; moving into grip range (%.1f studs).", activeNpcTarget.Name, distance), colors.Success)
		end
		return
	end
end)

local trainingStatus = ""
local trainingDefinitionByButton = {}
for _, definition in ipairs(trainingDefinitions) do
	trainingDefinitionByButton[definition.Button] = definition
end

local function setTrainingStatus(text, color)
	if trainingStatus == text then
		return
	end
	trainingStatus = text
	trainingStatusLabel.Text = text
	trainingStatusLabel.TextColor3 = color or colors.Muted
end

local function restoreKiControlCamera()
	kiControlAimSerial += 1
	local state = kiControlCameraState
	kiControlCameraState = nil
	if not state then
		return
	end

	local camera = state.Camera
	if camera and camera.Parent then
		camera.CameraType = state.CameraType
		camera.CameraSubject = state.CameraSubject
		camera.CFrame = state.CFrame
		camera.Focus = state.Focus
	end
	UserInputService.MouseBehavior = state.MouseBehavior
end

function qolState.StatAllocate.IsAutoTrainingTargetReached()
	if type(qolState.StatAllocate.AutoTrainingEnhancedTarget) ~= "number" then return false end
	local definition = trainingDefinitionByButton[selectedTrainingButton]
	local current = definition and qolState.StatAllocate.GetEnhancedValue(definition.EnhancedStat)
	return type(current) == "number" and current >= qolState.StatAllocate.AutoTrainingEnhancedTarget, current, definition
end

local function stopTrainingSession(statusText)
	restoreKiControlCamera()
	activeTrainingButton = nil
	trainingSessionSawTargets = false
	strengthPressedThisCircle = false
	durabilityLastPressAt = 0
	kiControlLastShotAt = 0
	kiControlSweepCooldownUntil = 0
	kiControlDesignatedTarget = nil
	handledTrainingTargets = {}
	local selected = trainingDefinitionByButton[selectedTrainingButton]
	setTrainingStatus(statusText or ("Selected: " .. selected.Label .. " - press M and choose " .. selected.Button), colors.Success)
end
qolState.StatAllocate.StopTrainingSession = stopTrainingSession

local function startTrainingSession(buttonName)
	if unloaded then
		return
	end

	local definition = trainingDefinitionByButton[buttonName]
	if not definition or buttonName ~= selectedTrainingButton then
		local selected = trainingDefinitionByButton[selectedTrainingButton]
		stopTrainingSession("Stat Trainer is set to " .. selected.Label)
		return
	end

	restoreKiControlCamera()
	activeTrainingButton = buttonName
	trainingSessionStartedAt = os.clock()
	trainingSessionSawTargets = false
	trainingLastTargetsAt = trainingSessionStartedAt
	strengthPressedThisCircle = false
	durabilityLastPressAt = 0
	kiControlLastShotAt = 0
	kiControlSweepCooldownUntil = 0
	kiControlDesignatedTarget = nil
	handledTrainingTargets = {}
	setTrainingStatus(definition.Label .. " - waiting for minigame...", colors.Success)
end

local function isGuiVisible(object)
	if not object:IsA("GuiObject") or not object.Visible then
		return false
	end

	local ancestor = object.Parent
	while ancestor and ancestor ~= playerGui do
		if ancestor:IsA("GuiObject") and not ancestor.Visible then
			return false
		end
		if ancestor:IsA("LayerCollector") and not ancestor.Enabled then
			return false
		end
		ancestor = ancestor.Parent
	end
	return true
end

local function sendKeyPress(keyCode)
	local pressed = pcall(function()
		VirtualInputManager:SendKeyEvent(true, keyCode, false, game)
	end)
	if not pressed then
		stopTrainingSession("Unable to send keyboard input")
		trainingStatusLabel.TextColor3 = colors.DangerHover
		return false
	end

	task.delay(0.035, function()
		pcall(function()
			VirtualInputManager:SendKeyEvent(false, keyCode, false, game)
		end)
	end)
	return true
end

local function getKiControlAim(target)
	local camera = workspace.CurrentCamera
	local character = localPlayer.Character
	local characterRoot = character and character:FindFirstChild("HumanoidRootPart")
	local characterHead = character and character:FindFirstChild("Head")
	local targetRoot = target and target:FindFirstChild("HumanoidRootPart")
	if not camera or not characterRoot or not targetRoot then
		return nil
	end

	local targetPosition = targetRoot.Position
	local eyePosition = characterHead and characterHead.Position or characterRoot.Position + Vector3.new(0, 1.5, 0)
	local fromEye = targetPosition - eyePosition
	if fromEye.Magnitude < 1 then
		return nil
	end

	local direction = fromEye.Unit
	local cameraPosition = eyePosition + direction * 0.75
	local raycastParams = RaycastParams.new()
	raycastParams.FilterType = Enum.RaycastFilterType.Exclude
	raycastParams.FilterDescendantsInstances = {character}
	raycastParams.IgnoreWater = true
	local rayResult = workspace:Raycast(cameraPosition, targetPosition - cameraPosition, raycastParams)
	if not rayResult or not rayResult.Instance:IsDescendantOf(target) then
		return nil
	end

	return CFrame.lookAt(cameraPosition, targetPosition), targetPosition, raycastParams
end

local function aimAndFireKiControl(target)
	if kiControlCameraState then
		return false
	end

	local camera = workspace.CurrentCamera
	local targetRoot = target and target:FindFirstChild("HumanoidRootPart")
	local aimCFrame, targetPosition, raycastParams = getKiControlAim(target)
	if not camera or not targetRoot or not aimCFrame then
		return false
	end

	kiControlAimSerial += 1
	local thisAim = kiControlAimSerial
	kiControlCameraState = {
		Camera = camera,
		CameraType = camera.CameraType,
		CameraSubject = camera.CameraSubject,
		CFrame = camera.CFrame,
		Focus = camera.Focus,
		MouseBehavior = UserInputService.MouseBehavior,
	}
	camera.CameraType = Enum.CameraType.Scriptable
	camera.CFrame = aimCFrame
	camera.Focus = CFrame.new(targetPosition)
	UserInputService.MouseBehavior = Enum.MouseBehavior.Default

	local screenPosition = camera.ViewportSize / 2
	pcall(function()
		VirtualInputManager:SendMouseMoveEvent(screenPosition.X, screenPosition.Y, game)
	end)

	task.delay(0.025, function()
		if unloaded or thisAim ~= kiControlAimSerial or activeTrainingButton ~= "Control"
			or not target.Parent or not targetRoot.Parent or target:FindFirstChild("Target Hit") then
			restoreKiControlCamera()
			return
		end

		camera.CFrame = aimCFrame
		local mouse = localPlayer:GetMouse()
		local mousePosition = mouse.Hit.Position
		local mouseDirection = mousePosition - camera.CFrame.Position
		local rayResult = mouseDirection.Magnitude > 0 and workspace:Raycast(
			camera.CFrame.Position,
			mouseDirection.Unit * 10000,
			raycastParams
		)
		local mouseTarget = mouse.Target
		local locked = mouseTarget and mouseTarget:IsDescendantOf(target)
			or rayResult and rayResult.Instance:IsDescendantOf(target)
		if locked then
			if sendKeyPress(Enum.KeyCode.E) then
				handledTrainingTargets[target] = true
				kiControlDesignatedTarget = nil
				setTrainingStatus("Ki Control - locked target and fired", colors.Success)
			end
		else
			setTrainingStatus("Ki Control - correcting aim...", colors.Success)
		end

		task.delay(0.04, function()
			if thisAim == kiControlAimSerial then
				restoreKiControlCamera()
			end
		end)
	end)
	return true
end

local function sendMouseClick(target)
	if not target or not target:IsA("GuiButton") or not isGuiVisible(target) then
		return false
	end

	local position = getVirtualInputPosition(target)
	local guiWasEnabled = screenGui.Enabled

	if guiWasEnabled then
		screenGui.Enabled = false
		task.wait()
	end

	local clicked = pcall(function()
		VirtualInputManager:SendMouseButtonEvent(position.X, position.Y, 0, true, game, 0)
		task.wait(0.075)
		VirtualInputManager:SendMouseButtonEvent(position.X, position.Y, 0, false, game, 0)
	end)

	if guiWasEnabled and not unloaded and screenGui.Parent then
		task.delay(0.08, function()
			if not unloaded and screenGui.Parent then
				screenGui.Enabled = true
			end
		end)
	end

	if not clicked then
		stopTrainingSession("Unable to click Ki Damage target")
		trainingStatusLabel.TextColor3 = colors.DangerHover
	end

	return clicked
end

local function clickTrainingButton(button)
	if not button or not button:IsA("GuiButton") or not isGuiVisible(button) then
		return false
	end

	local position = getVirtualInputPosition(button)
	local guiWasEnabled = screenGui.Enabled

	if guiWasEnabled then
		screenGui.Enabled = false
		task.wait()
	end

	local clicked = pcall(function()
		VirtualInputManager:SendMouseButtonEvent(position.X, position.Y, 0, true, game, 0)
		task.wait(0.075)
		VirtualInputManager:SendMouseButtonEvent(position.X, position.Y, 0, false, game, 0)
	end)

	-- Give the game's menu time to consume the click before Gohan Hub returns.
	task.wait(0.08)
	if guiWasEnabled and not unloaded and screenGui.Parent then
		screenGui.Enabled = true
	end

	return clicked
end

local function findSelectedTrainingButton()
	local meditateGui = playerGui:FindFirstChild("MeditateGui")
	if not meditateGui then
		return nil
	end

	local button = meditateGui:FindFirstChild(selectedTrainingButton, true)
	if button and button:IsA("GuiButton") and isGuiVisible(button) then
		return button
	end
	return nil
end

local function attemptAutoStart()
	if not configStore.TrainingEnabled then return end
	if unloaded or not autoStartEnabled or autoStartBusy or activeTrainingButton then
		return
	end
	local reached, current, definition = qolState.StatAllocate.IsAutoTrainingTargetReached()
	if reached then
		autoStartEnabled = false
		autoStartButton.Text = "Auto Training: OFF"
		autoStartButton.TextColor3 = colors.Muted
		autoStartButton.BackgroundColor3 = colors.Surface
		setTrainingStatus(string.format("%s enhanced target reached: %.2f / %s.",
			definition.Label, current, tostring(qolState.StatAllocate.AutoTrainingEnhancedTarget)), colors.Success)
		return
	end
	if os.clock() - autoStartLastAttemptAt < 2.5 then
		return
	end

	autoStartLastAttemptAt = os.clock()
	autoStartBusy = true
	task.spawn(function()
		local character = localPlayer.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		if not humanoid or humanoid.Health <= 0 then
			setTrainingStatus("Auto Start - waiting for a live character...", colors.Muted)
			autoStartBusy = false
			return
		end
		local button = findSelectedTrainingButton()
		if (character:GetAttribute("Meditating") or character:GetAttribute("State_Meditating")) and not button then
			setTrainingStatus("Auto Start - waiting for current meditation...", colors.Muted)
			autoStartBusy = false
			return
		end

		if not button then
			sendKeyPress(Enum.KeyCode.M)
			local menuDeadline = os.clock() + 1
			repeat
				task.wait(0.03)
				if unloaded or not autoStartEnabled then
					autoStartBusy = false
					return
				end
				button = findSelectedTrainingButton()
			until button or os.clock() >= menuDeadline
		end

		if button then
			local definition = trainingDefinitionByButton[selectedTrainingButton]
			setTrainingStatus("Auto Start - launching " .. definition.Label .. "...", colors.Success)
			autoStartFailedLaunches += 1
			if not clickTrainingButton(button) then
				setTrainingStatus("Auto Start - unable to click training", colors.DangerHover)
			end
		else
			setTrainingStatus("Auto Start - training menu unavailable", colors.Muted)
		end
		task.wait(0.45)
		autoStartBusy = false
	end)
end

