	if enabled == false and autoBuildState.PersistentAutoEnabled and not autoBuildState.InternalTrainingToggle then
		autoBuildState.PersistentAutoEnabled = false
		autoBuildState.WaitingForGtp = false
		autoBuildState.AutoBuildElapsed = 0
