function qolState.StatAllocate.MoveAutoBuildToSafeTrainingSpot()
	local character = localPlayer.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local characterRoot = character and character:FindFirstChild("HumanoidRootPart")
	if not humanoid or humanoid.Health <= 0 or not characterRoot then return false end

	-- Move to real terrain near the last farm position instead of placing the
	-- character in the void. This keeps training away from Capital and avoids
	-- the PlatformStand ragdoll that the combat movement rig uses.
	local origin = npcSafety.LastTargetPosition or characterRoot.Position
	local safePosition = nil
	for _, offset in ipairs({
		Vector3.new(360, 0, 210), Vector3.new(-320, 0, 280),
		Vector3.new(260, 0, -370), Vector3.new(-410, 0, -190),
	}) do
		local candidate = origin + offset
		local groundY = getGroundYAt(candidate, character)
		if groundY then
			safePosition = Vector3.new(candidate.X, groundY + 4, candidate.Z)
			break
		end
	end
	if not safePosition then
		local groundY = getGroundYAt(characterRoot.Position, character)
		safePosition = Vector3.new(characterRoot.Position.X, (groundY or characterRoot.Position.Y) + 4, characterRoot.Position.Z)
	end
	character:PivotTo(CFrame.new(safePosition) * characterRoot.CFrame.Rotation)
	characterRoot.AssemblyLinearVelocity = Vector3.zero
	characterRoot.AssemblyAngularVelocity = Vector3.zero
	humanoid.PlatformStand = false
	humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
	return true
end

