function qolState.StatAllocate.GetUtp()
	local hud = playerGui:FindFirstChild("HUD")
	local inventory = hud and hud:FindFirstChild("Inventory")
	local statFrame = inventory and inventory:FindFirstChild("StatFrame")
	local stats = statFrame and statFrame:FindFirstChild("Stats")
	local utp = stats and stats:FindFirstChild("UTP")
	local label = utp and utp:FindFirstChild("StatNum")
	return label and tonumber(label.Text) or nil
end

function qolState.StatAllocate.UpdateAutoBuildTrainer(deltaTime)
	local state = qolState.StatAllocate
	if not state.PersistentAutoEnabled or unloaded then return end
	state.AutoBuildElapsed += deltaTime
	if state.AutoBuildElapsed < 0.5 then return end
	state.AutoBuildElapsed = 0
	local utp = state.GetUtp()
	local gtpOk, gtp = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "Gained TP")
	gtp = gtpOk and tonumber(gtp) or nil
	if utp == nil or gtp == nil then
		state.SetStatus("Auto Build is waiting for the UTP/GTP counters.", colors.Muted)
		return
	end
	local statName, current, target = state.SelectNextBuildStat()
	if not statName then
		state.PersistentAutoEnabled = false
		state.RenderAuto()
		if autoStartEnabled then
			state.InternalTrainingToggle = true
			setAutoStartEnabled(false)
			state.InternalTrainingToggle = false
		end
		return
	end
	local buttonName = state.AutoBuildTrainingButtons[statName]
	local definition = trainingDefinitionByButton[buttonName]
	if not definition then return end
	-- Autofarm is the default. Training is allowed only when UTP is exactly
	-- zero while there is still GTP to convert through the training minigame.
	if utp > 0 or gtp <= 0 then
		state.WaitingForGtp = false
		if autoStartEnabled then
			state.InternalTrainingToggle = true
			setAutoStartEnabled(false)
			state.InternalTrainingToggle = false
		end
		if activeTrainingButton then stopTrainingSession("Auto Build resuming Autofarm.") end
		if selectedNpcType and not npcTargetingEnabled then setNpcTargetingEnabled(true) end
		state.SetStatus(
			utp > 0 and "Auto Build has UTP; Autofarm active."
				or "Auto Build has no UTP or GTP; Autofarm active.",
			colors.Success)
		return
	end
	if npcTargetingEnabled then
		setNpcTargetingEnabled(false)
		qolState.StatAllocate.MoveAutoBuildToSafeTrainingSpot()
	end
	state.WaitingForGtp = true
	state.GtpEmptyAlertSent = false
	-- Auto Build trains only until UTP returns. Do not reuse an enhanced-stat
	-- cap here: that cap was ending the session after a couple of successful reps.
	qolState.StatAllocate.AutoTrainingEnhancedTarget = nil
	qolState.StatAllocate.AutoTrainingTargetBox.Text = ""
	if selectedTrainingButton ~= buttonName then selectTrainingDefinition(definition) end
	if not autoStartEnabled then setAutoStartEnabled(true) end
	state.SetStatus(string.format("Auto Build has 0 UTP; training %s until the next level.",
		state.DisplayNames[statName]), colors.Success)
end
