-- Each recording has an archive. Values use Instance identity, not names:
-- duplicate Frame siblings otherwise overwrite each other's cached properties.
configStore.MinigameTrace = {
	Values = {}, Dumped = {}, Layers = {}, Baseline = {}, Scripts = {}, NextId = 0,
	Lines = 0, File = configStore.Root .. "/minigame_trace.txt", Buffer = {},
}

function configStore.MinigameTrace.Flush()
	local trace = configStore.MinigameTrace
	if not trace.Dirty or type(writefile) ~= "function" then return end
	local body = table.concat(trace.Buffer, "\n")
	local ok = pcall(writefile, trace.File, body)
	if trace.SessionFile then
		local sessionOk = pcall(writefile, trace.SessionFile, body)
		ok = ok and sessionOk
	end
	if ok then trace.Dirty = false end
end

function configStore.MinigameTrace.Start()
	local trace = configStore.MinigameTrace
	trace.Flush()
	local id = tostring(os.time()) .. "_" .. HttpService:GenerateGUID(false)
	-- Preserve an older recorder's latest-only files before the first v3 run.
	if not trace.SessionFile then
		local read = configStore.GetFunction("readfile")
		local write = configStore.GetFunction("writefile")
		if read and write then
			for _, name in ipairs({"minigame_trace", "clash_log"}) do
				local ok, old = pcall(read, configStore.Root .. "/" .. name .. ".txt")
				if ok and type(old) == "string" and #old > 0 then
					pcall(write, configStore.Root .. "/" .. name .. "_before_" .. id .. ".txt", old)
				end
			end
		end
	end
	trace.SessionFile = configStore.Root .. "/minigame_trace_" .. id .. ".txt"
	configStore.AutoClash.SessionLogFile = configStore.Root .. "/clash_log_" .. id .. ".txt"
	trace.Values, trace.Dumped, trace.Layers, trace.Baseline = {}, {}, {}, {}
	trace.Scripts = {}
	trace.Buffer, trace.Lines, trace.NextId = {}, 0, 0
	trace.CheckElapsed, trace.FlushElapsed = 0, 0
	for _, layer in ipairs(playerGui:GetChildren()) do
		if layer:IsA("LayerCollector") then trace.Baseline[layer] = layer.Enabled end
	end
	trace.Write("RECORDER v3 // " .. trace.SessionFile)
	trace.Flush()
end

function configStore.MinigameTrace.Describe(object)
	local fields = {}
	local function add(name)
		local ok, value = pcall(function()
			return object[name]
		end)
		if ok then
			fields[name] = typeof(value) == "Instance" and value:GetFullName() or tostring(value)
		end
	end
	if object:IsA("GuiObject") then
		for _, name in ipairs({"Visible", "Rotation", "Position", "Size", "AbsolutePosition", "AbsoluteSize", "AnchorPoint", "BackgroundColor3", "BackgroundTransparency"}) do
			add(name)
		end
		if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
			add("Text")
			add("TextColor3")
		end
		if object:IsA("ImageLabel") or object:IsA("ImageButton") then
			for _, name in ipairs({"Image", "ImageColor3", "ImageTransparency", "ImageRectOffset", "ImageRectSize"}) do
				add(name)
			end
		end
	elseif object:IsA("UIGradient") then
		for _, name in ipairs({"Enabled", "Rotation", "Offset", "Transparency", "Color"}) do
			add(name)
		end
	elseif object:IsA("UIStroke") then
		for _, name in ipairs({"Enabled", "Color", "Transparency", "Thickness"}) do
			add(name)
		end
	elseif object:IsA("ValueBase") then
		add("Value")
	elseif object:IsA("LayerCollector") then
		add("Enabled")
	end
	for name, value in pairs(object:GetAttributes()) do
		fields["Attribute:" .. name] = tostring(value)
	end
	return fields
end

function configStore.MinigameTrace.Write(line)
	local trace = configStore.MinigameTrace
	if trace.Lines >= 100000 then
		return
	end
	trace.Lines += 1
	if trace.Lines == 100000 then line = "TRACE LIMIT REACHED // start another recording" end
	table.insert(trace.Buffer, string.format("[%.3f] %s", os.clock(), line))
	trace.Dirty = true
end

function configStore.MinigameTrace.FindPanels()
	local trace = configStore.MinigameTrace
	local layers = {}
	for _, layer in ipairs(playerGui:GetChildren()) do
		if layer:IsA("LayerCollector") and layer.Enabled and not configStore.AutoClash.IsHubGui(layer) then
			local name = string.lower(layer.Name)
			if trace.Baseline[layer] ~= true or string.find(name, "maze", 1, true)
				or string.find(name, "labyrinth", 1, true) or string.find(name, "minigame", 1, true)
				or name == "mindcontest" then layers[layer] = true end
		end
	end
	for _, descendant in ipairs(playerGui:GetDescendants()) do
		if (descendant:IsA("TextLabel") or descendant:IsA("TextButton"))
			and not configStore.AutoClash.IsHubGui(descendant) and isGuiVisible(descendant) then
			local text = string.upper((string.gsub(descendant.Text, "<[^>]->", "")))
			if string.find(text, "KEEP THE BODY", 1, true) or string.find(text, "HIT THE MARK", 1, true)
				or string.find(text, "MAZE", 1, true) or string.find(text, "LABYRINTH", 1, true)
				or string.find(text, "REACH THE EXIT", 1, true) then
				local layer = descendant:FindFirstAncestorWhichIsA("LayerCollector")
				if layer then layers[layer] = true end
			end
		end
	end
	return layers
end

function configStore.MinigameTrace.Observe(object)
	local trace = configStore.MinigameTrace
	local state = trace.Values[object]
	local parent = object.Parent
	if parent and parent ~= playerGui and not trace.Values[parent] then trace.Observe(parent) end
	local fields = trace.Describe(object)
	fields.ParentId = tostring(parent and trace.Values[parent] and trace.Values[parent].Id or 0)
	if not state then
		trace.NextId += 1
		state = {Id = trace.NextId, Fields = fields}
		trace.Values[object] = state
		local parts = {}
		for name, value in pairs(fields) do table.insert(parts, name .. "=" .. value) end
		table.sort(parts)
		trace.Write(string.format("#%d %s [%s] %s", state.Id, object:GetFullName(), object.ClassName, table.concat(parts, " ")))
		return
	end
	for name, value in pairs(fields) do
		if state.Fields[name] ~= value then
			trace.Write(string.format("#%d .%s = %s", state.Id, name, value))
		end
	end
	for name in pairs(state.Fields) do
		if fields[name] == nil then trace.Write(string.format("#%d .%s = <removed>", state.Id, name)) end
	end
	state.Fields = fields
end

function configStore.MinigameTrace.Dump(layer)
	local trace = configStore.MinigameTrace
	trace.Write("===== TREE " .. layer:GetFullName() .. " =====")
	trace.Observe(layer)
	for _, descendant in ipairs(layer:GetDescendants()) do
		trace.Observe(descendant)
	end
	trace.Write("===== END TREE =====")
	-- Decompilation can yield; run it separately so it cannot stall UI sampling.
	local sessionFile = trace.SessionFile
	task.spawn(function()
	local decompiler = getgenv and (getgenv().decompile or decompile) or nil
	local scripts = {}
	for _, descendant in ipairs(layer:GetDescendants()) do
		if descendant:IsA("LocalScript") or descendant:IsA("ModuleScript") then
			table.insert(scripts, descendant)
		end
	end
	local playerScripts = localPlayer:FindFirstChildOfClass("PlayerScripts")
	for _, root in ipairs({playerScripts, ReplicatedStorage}) do
		for _, descendant in ipairs(root and root:GetDescendants() or {}) do
			local lowerName = string.lower(descendant.Name)
			if (descendant:IsA("LocalScript") or descendant:IsA("ModuleScript"))
				and (string.find(lowerName, "body", 1, true) or string.find(lowerName, "mark", 1, true)
					or string.find(lowerName, "resist", 1, true) or string.find(lowerName, "minigame", 1, true)
					or string.find(lowerName, "possess", 1, true) or string.find(lowerName, "grab", 1, true)
					or string.find(lowerName, "contest", 1, true) or string.find(lowerName, "maze", 1, true)
					or string.find(lowerName, "labyrinth", 1, true) or lowerName == "circuitrouter") then
				table.insert(scripts, descendant)
			end
		end
	end
	for _, scriptObject in ipairs(scripts) do
		if unloaded or not configStore.AutoClash.Recording or trace.SessionFile ~= sessionFile then break end
		if trace.Scripts[scriptObject] then continue end
		trace.Scripts[scriptObject] = true
		trace.Write("SCRIPT " .. scriptObject:GetFullName() .. " [" .. scriptObject.ClassName .. "]")
		if type(decompiler) == "function" and type(writefile) == "function" then
			local ok, source = pcall(decompiler, scriptObject)
			if unloaded or not configStore.AutoClash.Recording or trace.SessionFile ~= sessionFile then break end
			if ok and type(source) == "string" then
				local fileName = configStore.Root .. "/src_" .. string.gsub(scriptObject:GetFullName(), "[^%w_]", "_") .. ".lua"
				pcall(writefile, fileName, source)
				trace.Write("  decompiled -> " .. fileName .. " (" .. #source .. " bytes)")
			else
				trace.Write("  decompile failed: " .. tostring(source))
			end
		end
	end
	end)
end

connect(RunService.Heartbeat, function(deltaTime)
	local trace = configStore.MinigameTrace
	if not configStore.AutoClash.Recording or unloaded then
		return
	end
	trace.CheckElapsed = (trace.CheckElapsed or 0) + deltaTime
	trace.FlushElapsed = (trace.FlushElapsed or 0) + deltaTime
	if trace.CheckElapsed >= 0.15 then
		trace.CheckElapsed = 0
		for layer in pairs(trace.FindPanels()) do
			trace.Layers[layer] = true
			if not trace.Dumped[layer] then
				trace.Dumped[layer] = true
				warn("[Anomaly's Hub] Minigame panel found: " .. layer:GetFullName() .. " - tracing to " .. tostring(trace.SessionFile))
				trace.Dump(layer)
			end
		end
	end
	for layer in pairs(trace.Layers) do
		if not layer.Parent then
			trace.Layers[layer], trace.Dumped[layer], trace.Baseline[layer] = nil, nil, nil
		else
			trace.Observe(layer)
			for _, descendant in ipairs(layer:GetDescendants()) do trace.Observe(descendant) end
		end
	end
	for object, state in pairs(trace.Values) do
		if not object:IsDescendantOf(playerGui) then
			trace.Write(string.format("#%d REMOVED", state.Id))
			trace.Values[object] = nil
		end
	end
	if trace.FlushElapsed >= 0.5 then trace.FlushElapsed = 0; trace.Flush() end
end)
-- Only minigame controls are recorded, and never while typing in a text box.
configStore.MinigameTrace.InputKeys = {W = true, A = true, S = true, D = true,
	Up = true, Down = true, Left = true, Right = true, Space = true}
function configStore.MinigameTrace.Input(input, direction)
	if not configStore.AutoClash.Recording or unloaded or UserInputService:GetFocusedTextBox() then return end
	local trace = configStore.MinigameTrace
	local key = input.KeyCode.Name
	if trace.InputKeys[key] then trace.Write("INPUT " .. key .. " " .. direction) end
end
connect(UserInputService.InputBegan, function(input) configStore.MinigameTrace.Input(input, "DOWN") end)
connect(UserInputService.InputEnded, function(input) configStore.MinigameTrace.Input(input, "UP") end)
configStore.AutoClash.Render()

connect(RunService.RenderStepped, function()
	if unloaded or not activeTrainingButton then
		return
	end
	local reached, current, definition = qolState.StatAllocate.IsAutoTrainingTargetReached()
	if reached then
		autoStartEnabled = false
		autoStartButton.Text = "Auto Training: OFF"
		autoStartButton.TextColor3 = colors.Muted
		autoStartButton.BackgroundColor3 = colors.Surface
		stopTrainingSession(string.format("%s enhanced target reached: %.2f / %s.",
			definition.Label, current, tostring(qolState.StatAllocate.AutoTrainingEnhancedTarget)))
		return
	end

	if activeTrainingButton == "Pushup" then
		local popupGui = playerGui:FindFirstChild("PopupGui")
		local goalFrame = popupGui and popupGui:FindFirstChild("GoalFrame")
		local circle = popupGui and popupGui:FindFirstChild("Circle")
		local found = goalFrame and circle and goalFrame:IsA("GuiObject") and circle:IsA("GuiObject")
			and isGuiVisible(goalFrame) and isGuiVisible(circle)
		if not updateTrainingTargetPresence(found) then
			return
		end

		local circleScale = circle.Size.X.Scale
		local insideGoal = circleScale > 0 and circleScale <= goalFrame.Size.X.Scale + 0.1
		if insideGoal and not strengthPressedThisCircle then
			strengthPressedThisCircle = true
			if sendKeyPress(Enum.KeyCode.Space) then
				setTrainingStatus("Strength - Space pressed", colors.Success)
			end
		elseif not insideGoal then
			strengthPressedThisCircle = false
			setTrainingStatus("Strength - timing circle...", colors.Success)
		end
	elseif activeTrainingButton == "Squat" then
		local popupGui = playerGui:FindFirstChild("PopupGui")
		local letterLabel = popupGui and popupGui:FindFirstChild("LetterLabel")
		local found = letterLabel and letterLabel:IsA("TextLabel") and isGuiVisible(letterLabel)
		if not updateTrainingTargetPresence(found) then
			return
		end

		if not handledTrainingTargets[letterLabel] then
			local letter = letterLabel.Text
			local keyCode = (letter == "W" or letter == "A" or letter == "S" or letter == "D") and Enum.KeyCode[letter] or nil
			if keyCode then
				handledTrainingTargets[letterLabel] = true
				if sendKeyPress(keyCode) then
					setTrainingStatus("Agility - pressed " .. letterLabel.Text, colors.Success)
				end
			end
		end
	elseif activeTrainingButton == "Situp" then
		local character = localPlayer.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")
		local miniGame = root and root:FindFirstChild("Mini_Medi")
		local bar = miniGame and miniGame:FindFirstChild("Bar")
		local goal = bar and bar:FindFirstChild("Goal")
		local slider = bar and bar:FindFirstChild("Slider")
		local found = goal and slider and goal:IsA("GuiObject") and slider:IsA("GuiObject")
			and not (miniGame:IsA("LayerCollector") and not miniGame.Enabled)
			and goal.Visible and slider.Visible
		-- Once the minigame object is gone the set is over; only a hidden
		-- (but still present) bar needs the normal grace period.
		if not updateTrainingTargetPresence(found, not miniGame and configStore.DurabilityTrainer.FinishGap or nil) then
			configStore.DurabilityTrainer.LastX = nil
			return
		end

		local durability = configStore.DurabilityTrainer
		if durability.Session ~= trainingSessionStartedAt then
			durability.Session = trainingSessionStartedAt
			durability.LastX = nil
			durability.Velocity = 0
			durability.Presses = 0
		end
		local sliderX, goalLeft, goalRight = durability.Measure(bar, goal, slider)
		local goalWidth = math.max(goalRight - goalLeft, 1e-6)
		local now = os.clock()
		if durability.LastX and now > durability.LastAt then
			local delta = sliderX - durability.LastX
			local sample = delta / (now - durability.LastAt)
			if math.abs(delta) > goalWidth * 3 then
				-- Slider snapped back to its start after a rep; old speed is meaningless.
				durability.Velocity = 0
			elseif sample * durability.Velocity < 0 then
				-- Bounced off an end of the bar.
				durability.Velocity = sample
			else
				durability.Velocity += (sample - durability.Velocity) * 0.5
			end
		end
		durability.LastX, durability.LastAt = sliderX, now

		-- Press as soon as the slider is in the goal now and will still be in it
		-- when the input lands. Geometry is read fresh every frame, so a goal
		-- that just relocated is judged at its new spot immediately.
		local predictedX = sliderX + durability.Velocity * durability.Lead
		local margin = goalWidth * durability.Margin
		local insideNow = goalLeft + margin <= sliderX and sliderX <= goalRight - margin
		local insidePredicted = goalLeft + margin <= predictedX and predictedX <= goalRight - margin
		if insideNow and insidePredicted and now - durabilityLastPressAt >= durability.Cooldown then
			durabilityLastPressAt = now
			durability.Presses += 1
			if sendKeyPress(Enum.KeyCode.Space) then
				setTrainingStatus(string.format("Durability - Space pressed (%d this set)", durability.Presses), colors.Success)
			end
		elseif not insideNow then
			setTrainingStatus("Durability - tracking slider...", colors.Success)
		end
	elseif activeTrainingButton == "Dmg" then
		local meditateGui = playerGui:FindFirstChild("MeditateGui")
		local foundTarget = false
		if meditateGui then
			for _, target in ipairs(meditateGui:GetChildren()) do
				if target.Name == "Goal" and target:IsA("GuiButton") and isGuiVisible(target) then
					foundTarget = true
					if not handledTrainingTargets[target] then
						handledTrainingTargets[target] = true
						if sendMouseClick(target) then
							setTrainingStatus("Ki Damage - circle clicked", colors.Success)
						end
					end
				end
			end
		end
		updateTrainingTargetPresence(foundTarget)
	elseif activeTrainingButton == "Control" then
		local world = workspace:FindFirstChild("World")
		local live = world and world:FindFirstChild("Live")
		local foundTarget = false
		local characterRoot = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
		local designatedIsValid = kiControlDesignatedTarget and kiControlDesignatedTarget.Parent == live
			and kiControlDesignatedTarget:FindFirstChild("Marker")
			and kiControlDesignatedTarget:FindFirstChild("HumanoidRootPart")
			and not kiControlDesignatedTarget:FindFirstChild("Target Hit")

		if not designatedIsValid then
			restoreKiControlCamera()
			kiControlDesignatedTarget = nil
			local closestDistance = math.huge
			local clearTargetExists = false
			if live and characterRoot and os.clock() >= kiControlSweepCooldownUntil then
				for _, target in ipairs(live:GetChildren()) do
					local targetRoot = target.Name == "Target" and target:FindFirstChild("HumanoidRootPart")
					local hasClearAim = targetRoot and getKiControlAim(target) ~= nil
					if hasClearAim and target:FindFirstChild("Marker") and not target:FindFirstChild("Target Hit") then
						clearTargetExists = true
						local distance = (targetRoot.Position - characterRoot.Position).Magnitude
						if not handledTrainingTargets[target] and distance < closestDistance then
							closestDistance = distance
							kiControlDesignatedTarget = target
						end
					end
				end
				if clearTargetExists and not kiControlDesignatedTarget then
					handledTrainingTargets = {}
					kiControlSweepCooldownUntil = os.clock() + 0.25
				end
			end
		end

		if live then
			for _, target in ipairs(live:GetChildren()) do
				local targetRoot = target.Name == "Target" and target:FindFirstChild("HumanoidRootPart")
				if targetRoot and target:FindFirstChild("Marker") and not target:FindFirstChild("Target Hit") then
					foundTarget = true
				end
			end
		end

		if updateTrainingTargetPresence(foundTarget) and kiControlDesignatedTarget
			and not kiControlCameraState and os.clock() - kiControlLastShotAt >= 0.075 then
			kiControlLastShotAt = os.clock()
			if aimAndFireKiControl(kiControlDesignatedTarget) then
				setTrainingStatus("Ki Control - target locked...", colors.Success)
			else
				kiControlDesignatedTarget = nil
				setTrainingStatus("Ki Control - finding clear target...", colors.Success)
			end
		end
	end
end)

local function extractValue(rowText)
	if type(rowText) ~= "string" then
		return "Unavailable"
	end
	local value = string.match(rowText, "^[^:]+:%s*(.*)$")
	if value == nil or value == "" then
		return "Unavailable"
	end
	return value
end

function configStore.ApplyDoctorReport(dataInfo)
	if type(dataInfo) ~= "table" then
		return false
	end

	local populated = 0
	for _, definition in ipairs(fieldDefinitions) do
		local value = extractValue(dataInfo[definition.Key])
		valueLabels[definition.Key].Text = value
		if value ~= "Unavailable" then
			populated += 1
		end
	end

	statusLabel.Text = string.format("Updated from Doctor report • %d/%d fields", populated, #fieldDefinitions)
	statusLabel.TextColor3 = populated > 0 and Color3.fromRGB(116, 214, 154) or colors.Muted
	return populated > 0
end

function configStore.RequestDoctorReport()
	if unloaded or requestPending then
		return false
	end

	local now = os.clock()
	if now - lastRequestAt < 0.75 then
		statusLabel.Text = "Please wait a moment before refreshing again."
		statusLabel.TextColor3 = colors.Muted
		return false
	end

	lastRequestAt = now
	requestPending = true
	requestSerial += 1
	local thisRequest = requestSerial
	statusLabel.Text = "Requesting authoritative Doctor report…"
	statusLabel.TextColor3 = colors.Muted
	refreshButton.Text = "Loading…"
	refreshButton.BackgroundColor3 = colors.AccentSoft

	-- Legacy placeholder retained only for compatibility; Doctor requests are no longer sent.

	schedule(6, function()
		if requestPending and requestSerial == thisRequest then
			requestPending = false
			refreshButton.Text = "Refresh"
			refreshButton.BackgroundColor3 = colors.Accent
			statusLabel.Text = "Doctor report request timed out."
			statusLabel.TextColor3 = colors.DangerHover
		end
	end)
	return true
end

function configStore.FormatDirectStat(value)
	if type(value) == "number" then
		if math.abs(value - math.round(value)) < 0.001 then
			return tostring(math.round(value))
		end
		local formatted = string.format("%.2f", value)
		return (formatted:gsub("0+$", ""):gsub("%.$", ""))
	end
	if type(value) == "string" and value ~= "" then
		return value
	end
	return "Unavailable"
end

function configStore.ApplyDirectStats(statData, characterData)
	local energy = type(statData) == "table" and statData.Energy
	local coreStats = type(statData) == "table" and statData.CoreStats
	local race = type(characterData) == "table" and characterData.Race
	local directValues = {
		Vitality = type(energy) == "table" and energy.Vitality,
		GravityMastery = type(coreStats) == "table" and coreStats.GravityMastery,
		PotentialType = type(characterData) == "table" and characterData.PotentialType,
		Motivation = type(energy) == "table" and energy.Motivation,
		SubType = type(race) == "table" and race.SubType,
	}

	local populated = 0
	for key, value in pairs(directValues) do
		local formatted = configStore.FormatDirectStat(value)
		valueLabels[key].Text = formatted
		if formatted ~= "Unavailable" then
			populated += 1
		end
	end
	return populated
end

function configStore.RequestReport()
	if unloaded or requestPending then
		return false
	end

	local now = os.clock()
	if now - lastRequestAt < 0.75 then
		statusLabel.Text = "Please wait a moment before refreshing again."
		statusLabel.TextColor3 = colors.Muted
		return false
	end

	lastRequestAt = now
	requestPending = true
	requestSerial += 1
	local thisRequest = requestSerial
	statusLabel.Text = "Reading live character stats..."
	statusLabel.TextColor3 = colors.Muted
	refreshButton.Text = "Loading..."
	refreshButton.BackgroundColor3 = colors.AccentSoft

	task.spawn(function()
		local function current() return requestSerial == thisRequest end
		local statOk, statData = configStore.ReadStatBounded(3, current, "StatData", "TableStat")
		if unloaded or not current() then return end
		local characterOk, characterData = configStore.ReadStatBounded(3, current, "CharacterData", "TableStat")
		if unloaded or requestSerial ~= thisRequest then
			return
		end

		requestPending = false
		refreshButton.Text = "Refresh"
		refreshButton.BackgroundColor3 = colors.Accent
		if not statOk or not characterOk or type(statData) ~= "table" or type(characterData) ~= "table" then
			statusLabel.Text = "Live stat request failed. Try again shortly."
			statusLabel.TextColor3 = colors.DangerHover
			return
		end

		local populated = configStore.ApplyDirectStats(statData, characterData)
		statusLabel.Text = string.format("Live stats updated - %d direct fields; wounds require a Doctor", populated)
		statusLabel.TextColor3 = populated > 0 and colors.Success or colors.Muted
	end)
	schedule(6, function()
		if requestPending and requestSerial == thisRequest then
			requestSerial += 1
			requestPending = false
			refreshButton.Text = "Refresh"
			refreshButton.BackgroundColor3 = colors.Accent
			statusLabel.Text = "Live stat request timed out."
			statusLabel.TextColor3 = colors.DangerHover
		end
	end)
	return true
end

function configStore.RefreshLiveMotivation()
	if unloaded or motivationRequestPending or currentTab ~= "Doctor" or os.clock() < (configStore.MotivationReadRetryAt or 0) then
		return
	end
	motivationRequestPending = true
	task.spawn(function()
		local ok, value = configStore.ReadStatBounded(5, function() return currentTab == "Doctor" end, "Motivation")
		motivationRequestPending = false
		configStore.MotivationReadRetryAt = ok and 0 or os.clock() + 5
		if not unloaded and currentTab == "Doctor" and ok then
			valueLabels.Motivation.Text = configStore.FormatDirectStat(value)
		elseif not unloaded and currentTab == "Doctor" then
			valueLabels.Motivation.Text = "Unavailable (retrying)"
		end
	end)
end

function configStore.GetServerInfoLabelText(labelName)
	local serverInfo = playerGui:FindFirstChild("ServerInfo", true)
	local label = serverInfo and serverInfo:FindFirstChild(labelName, true)
	if not label or not label:IsA("TextLabel") or label.Text == "" then
		return "Unavailable"
	end
	return label.Text
end

function configStore.StripInfoPrefix(text)
	return string.match(text, ":%s*(.+)$") or text
end

function configStore.GetPingText()
	local network = Stats:FindFirstChild("Network")
	local serverStats = network and network:FindFirstChild("ServerStatsItem")
	local dataPing = serverStats and serverStats:FindFirstChild("Data Ping")
	if not dataPing then
		return "Unavailable"
	end
	local ok, rawValue = pcall(function()
		return dataPing:GetValueString()
	end)
	local milliseconds = ok and tonumber(string.match(rawValue, "[%d%.]+"))
	if not milliseconds then
		return "Unavailable"
	end
	return tostring(math.floor(milliseconds + 0.5)) .. " ms"
end

