		qolState.AutoFood.SetThreshold(data.AutoFoodThreshold)
	end
	if type(data.AutoFoodEnabled) == "boolean" then
		qolState.AutoFood.SetEnabled(data.AutoFoodEnabled)
	end
	if configStore.FeatureAccess.AutoTraining and type(data.AutoTraining) == "boolean" then
		setAutoStartEnabled(data.AutoTraining)
	end
	if configStore.FeatureAccess.AutoTraining and type(data.AutoTrainingEnhancedTarget) == "number"
		and data.AutoTrainingEnhancedTarget >= 0 then
		qolState.StatAllocate.AutoTrainingEnhancedTarget = math.clamp(data.AutoTrainingEnhancedTarget, 0, 1000000000)
		qolState.StatAllocate.AutoTrainingTargetBox.Text = tostring(qolState.StatAllocate.AutoTrainingEnhancedTarget)
	end
	if configStore.FeatureAccess.AdvancedBuild and type(data.AutoAllocateStat) == "string" then
		qolState.StatAllocate.Select(data.AutoAllocateStat)
	end
	if configStore.FeatureAccess.AdvancedBuild and type(data.AutoAllocateBuildTargets) == "table" then
		for statName, value in pairs(data.AutoAllocateBuildTargets) do
			if qolState.StatAllocate.Definitions[statName] and type(value) == "number" and value >= 0 then
				qolState.StatAllocate.BuildTargets[statName] = value
				local box = qolState.StatAllocate.BuildTargetBoxes[statName]
				if box then box.Text = tostring(value) end
			end
		end
	end
	if configStore.FeatureAccess.AdvancedBuild and type(data.AutoAllocateBuildPriority) == "table" then
		for statName, value in pairs(data.AutoAllocateBuildPriority) do
			if qolState.StatAllocate.Definitions[statName] and type(value) == "number" then
				qolState.StatAllocate.BuildPriority[statName] = math.clamp(math.floor(value), 1, 5)
				local box = qolState.StatAllocate.BuildPriorityBoxes[statName]
				if box then box.Text = tostring(qolState.StatAllocate.BuildPriority[statName]) end
			end
		end
	end
	if configStore.FeatureAccess.AdvancedBuild and type(data.AutoAllocate) == "boolean" then
		qolState.StatAllocate.SetAutoEnabled(data.AutoAllocate)
	end
	if configStore.FeatureAccess.AdvancedBuild and type(data.PersistentAutoAllocate) == "boolean" then
		qolState.StatAllocate.SetPersistentAutoEnabled(data.PersistentAutoAllocate)
	end
	if configStore.FeatureAccess.AdvancedBuild and type(data.RapidAllocate) == "boolean" then
		qolState.StatAllocate.SetRapidEnabled(data.RapidAllocate)
	end
	if configStore.FeatureAccess.Motivation and type(data.AutoMotivation) == "boolean" then
		qolState.StatAllocate.SetMotivationAutoEnabled(data.AutoMotivation)
	end
	if configStore.FeatureAccess.AdvancedBuild and type(data.AutoAllocateTarget) == "number" then
		qolState.StatAllocate.SetTargetEnhanced(data.AutoAllocateTarget)
	end
	if type(data.ESPSettings)=="table" then
		for key,value in pairs(data.ESPSettings) do
			if configStore.ESP.Settings[key]~=nil and type(value)=="boolean" then
				configStore.ESP.Settings[key]=value
			end
		end
	end
	if type(data.ESPEnabled)=="boolean" then configStore.ESP.SetEnabled(data.ESPEnabled) else configStore.ESP.RenderButtons() end
	if type(data.ESPMaxDistance) == "number" then
		configStore.ESP.SetMaxDistance(data.ESPMaxDistance)
	end
	if type(data.NpcESPSettings) == "table" then
		for key, value in pairs(data.NpcESPSettings) do
			if configStore.NpcESP.Settings[key] ~= nil and type(value) == "boolean" then
				configStore.NpcESP.Settings[key] = value
			end
		end
	end
	if type(data.BuuDetectorEnabled) == "boolean" then configStore.BuuDetector.SetEnabled(data.BuuDetectorEnabled) end
	if type(data.Super17DetectorEnabled) == "boolean" then configStore.Super17Detector.SetEnabled(data.Super17DetectorEnabled) end
	if type(data.NpcESPEnabled) == "boolean" then
		configStore.NpcESP.SetEnabled(data.NpcESPEnabled)
	else
		configStore.NpcESP.RenderButtons()
	end
	if type(data.AutoClashMash) == "boolean" then
		configStore.AutoClash.Mash = data.AutoClashMash
	end
	configStore.BodyRing.SetEnabled(data.AutoBodyRingEnabled == true)
	configStore.AutoMaze.SetEnabled(data.AutoMazeEnabled == true)
	if type(data.AutoClashEnabled) == "boolean" then
		configStore.AutoClash.SetEnabled(data.AutoClashEnabled)
	else
		configStore.AutoClash.Render()
	end
	if type(data.DragonBallESPSettings) == "table" then
		for key, value in pairs(data.DragonBallESPSettings) do
			if configStore.DragonBallESP.Settings[key] ~= nil and type(value) == "boolean" then
				configStore.DragonBallESP.Settings[key] = value
			end
		end
	end
	if type(data.DragonBallESPEnabled) == "boolean" then
		-- Older always-on builds saved true without the user opting in.
		configStore.DragonBallESP.SetEnabled(data.DragonBallScannerToggleVersion==1 and data.DragonBallESPEnabled)
	else
		configStore.DragonBallESP.RenderButtons()
	end
	if type(data.NpcESPMaxDistance) == "number" then
		configStore.NpcESP.SetMaxDistance(data.NpcESPMaxDistance)
	else
		configStore.NpcESP.SetMaxDistance(1000000)
	end
	if type(data.LastTab) == "string" then configStore.SelectTab(data.LastTab) end
	if type(data.NpcPlayerRange) == "number" then
		npcSafety.PlayerRange = math.clamp(math.floor(data.NpcPlayerRange + 0.5), 25, 5000)
		npcSafety.PlayerRangeBox.Text = tostring(npcSafety.PlayerRange)
	end
	if type(data.NpcPanicHealthPercent) == "number" then
		npcSafety.PanicHealthRatio = math.clamp(data.NpcPanicHealthPercent / 100, 0.05, 0.95)
		npcSafety.PanicHealthBox.Text = tostring(math.floor(npcSafety.PanicHealthRatio * 100 + 0.5))
	end
	if type(data.NpcServerHop) == "boolean" then
		npcSafety.SetServerHopEnabled(data.NpcServerHop)
	end
	if type(data.NpcChestLoot) == "boolean" then
		npcSafety.SetChestLootEnabled(data.NpcChestLoot)
	end
	if type(data.AutoBlockPlayersBeforeHop) == "boolean" then
		qolState.ServerNavigation.SetAutoBlockPlayers(data.AutoBlockPlayersBeforeHop)
	end
	if type(data.NpcProfiles) == "table" then
		for npcType, savedProfile in pairs(data.NpcProfiles) do
			if type(npcType) == "string" and type(savedProfile) == "table" then
				local profile = npcSafety.GetProfile(npcType)
				for _, definition in ipairs(npcSafety.TuningDefinitions) do
					local value = savedProfile[definition.Key]
					if type(value) == "number" then
						profile[definition.Key] = math.clamp(value, definition.Min, definition.Max)
					end
				end
			end
		end
	end
	if type(data.NpcType) == "string" and data.NpcType ~= "" then
		selectedNpcType = npcSafety.IsExcludedFarmName(data.NpcType) and npcSafety.StrongestOptionName or data.NpcType
		npcSelectorButton.Text = selectedNpcType .. "  v"
		clearNpcConstraintRig()
		npcSafety.SpawnDestination = nil
		npcSafety.SpawnSource = nil
		npcAcquireElapsed = 1
		npcSafety.UpdateProfileVisual()
		refreshNpcTypes()
	end
	if data.NpcPositionMode == "Below" or data.NpcPositionMode == "Above"
		or data.NpcPositionMode == "FrontBehind" then
		npcSafety.SetPositionMode(data.NpcPositionMode)
	end
	npcSafety.ApplySavedAttackPreset(npcSafety.PositionMode)
	if type(data.AutoTransformForm) == "string" then
		autoTransformState.Select(data.AutoTransformForm)
	end
	if type(data.AutoTransformEnabled) == "boolean" then
		autoTransformState.SetEnabled(data.AutoTransformEnabled)
	end
	if type(data.NpcAutofarm) == "boolean" then
		setNpcTargetingEnabled(data.NpcAutofarm)
	end
	if configStore.FeatureAccess.FormMastery and type(data.FormMasteryForm) == "string" then
		qolState.FormMastery.Select(data.FormMasteryForm)
	end
	if configStore.FeatureAccess.FormMastery and type(data.FormMasteryEnabled) == "boolean" then
		qolState.FormMastery.SetEnabled(data.FormMasteryEnabled)
	end
	return true
end

function configStore.Select(name)
	local normalized = configStore.NormalizeName(name)
	if not normalized then
		return false
	end
	configStore.SelectedName = normalized
	configStore.NameBox.Text = normalized
	configStore.SelectButton.Text = normalized .. "  v"
	configStore.Dropdown.Visible = false
	return true
end

function configStore.RefreshDropdown()
	for _, button in ipairs(configStore.Buttons) do
		button:Destroy()
	end
	table.clear(configStore.Buttons)
	local names = configStore.ListNames()
	for order, name in ipairs(names) do
		local button = create("TextButton", {
			Name = name,
			LayoutOrder = order,
			Size = UDim2.new(1, 0, 0, 28),
			AutoButtonColor = false,
			BackgroundColor3 = name == configStore.SelectedName and colors.Accent or colors.Surface,
			BorderSizePixel = 0,
			Font = Enum.Font.GothamMedium,
			Text = name,
			TextColor3 = colors.Text,
			TextSize = 10,
			ZIndex = 61,
		}, configStore.Dropdown)
		create("UICorner", {CornerRadius = UDim.new(0, 5)}, button)
		table.insert(configStore.Buttons, button)
		connect(button.Activated, function()
			configStore.Select(name)
			configStore.RefreshDropdown()
		end)
	end
	if #names == 0 then
		configStore.SetStatus("No configs yet. Enter a name and click Create.", colors.Muted)
	end
	return #names
end

function configStore.SaveFromInput(overwrite)
	local name = configStore.NormalizeName(configStore.NameBox.Text)
		or configStore.SelectedName
	if not name then
		configStore.SetStatus("Enter a valid config name using letters, numbers, _ or -.", colors.DangerHover)
		return false
	end
	local ok, message = configStore.Write(name, configStore.Capture(), overwrite)
	if not ok then
		configStore.SetStatus(message or "Config save failed.", colors.DangerHover)
		return false
	end
	configStore.Select(name)
	configStore.RefreshDropdown()
	configStore.SetStatus((overwrite and "Saved " or "Created ") .. name .. ".json", colors.Success)
	return true
end

function configStore.LoadSelected()
	local name = configStore.SelectedName or configStore.NormalizeName(configStore.NameBox.Text)
	local data = name and configStore.Read(name) or nil
	if not data then
		configStore.SetStatus("Select an existing config to load.", colors.DangerHover)
		return false
	end
	local ok, message = configStore.SafeApply(data)
	if ok then
		configStore.Select(name)
		configStore.SetStatus("Loaded " .. name .. ".json", colors.Success)
	else
		configStore.SetStatus(message or "Config load failed.", colors.DangerHover)
	end
	return ok
end

connect(configStore.SelectButton.Activated, function()
	configStore.Dropdown.Visible = not configStore.Dropdown.Visible
	if configStore.Dropdown.Visible then
		configStore.RefreshDropdown()
	end
end)

connect(configStore.CreateButton.Activated, function()
	configStore.SaveFromInput(false)
end)

connect(configStore.SaveButton.Activated, function()
	configStore.SaveFromInput(true)
end)

connect(configStore.LoadButton.Activated, function()
	configStore.LoadSelected()
end)

connect(configStore.DeleteButton.Activated, function()
	local name = configStore.SelectedName or configStore.NormalizeName(configStore.NameBox.Text)
	if not name or not configStore.Delete(name) then
		configStore.SetStatus("Select an existing config to delete.", colors.DangerHover)
		return
	end
	if configStore.AutoloadName == name then
		configStore.AutoloadEnabled = false
		configStore.AutoloadName = nil
		configStore.WriteAutoload()
		configStore.UpdateAutoloadVisual()
	end
	configStore.SelectedName = nil
	configStore.NameBox.Text = ""
	configStore.SelectButton.Text = "Select config  v"
	configStore.RefreshDropdown()
	configStore.SetStatus("Deleted " .. name .. ".json", colors.Success)
end)

connect(configStore.AutoloadButton.Activated, function()
	if configStore.AutoloadEnabled then
		configStore.AutoloadEnabled = false
		configStore.AutoloadName = nil
	else
		local name = configStore.SelectedName or configStore.NormalizeName(configStore.NameBox.Text)
		if not name or not configStore.Read(name) then
			configStore.SetStatus("Select a saved config before enabling autoload.", colors.DangerHover)
			return
		end
		configStore.AutoloadEnabled = true
		configStore.AutoloadName = name
	end
	configStore.WriteAutoload()
	configStore.UpdateAutoloadVisual()
	configStore.SetStatus(configStore.AutoloadEnabled
		and ("Autoload set to " .. configStore.AutoloadName .. ".json")
		or "Autoload disabled.", colors.Success)
end)

function configStore.InitializeAutoload()
	local record = configStore.ReadAutoload()
	if type(record) ~= "table" then
		configStore.RefreshDropdown()
		return false
	end
	configStore.AutoloadEnabled = record.Enabled == true
	configStore.AutoloadName = configStore.NormalizeName(record.Config)
	configStore.UpdateAutoloadVisual()
	if not configStore.AutoloadEnabled or not configStore.AutoloadName then
		return false
	end
	local data = configStore.Read(configStore.AutoloadName)
	if not data then
		configStore.SetStatus("Autoload config is missing or invalid.", colors.DangerHover)
		return false
	end
	configStore.Select(configStore.AutoloadName)
	local ok, message = configStore.SafeApply(data)
	configStore.SetStatus(ok
		and ("Autoloaded " .. configStore.AutoloadName .. ".json")
		or (message or "Autoload failed."), ok and colors.Success or colors.DangerHover)
	return ok
end

function controller.Unload()
	if unloaded then
		return
	end
	local function step(label, callback)
		local ok, err = pcall(callback)
		if not ok then
			warn("[" .. HUB_DISPLAY_NAME .. "] Unload step failed (" .. label .. "):", err)
		end
	end
	step("server browser",qolState.ServerNavigation.StopServerBrowser)
	step("reload request",function()
		local state=configStore.Reload
		state.Serial+=1;state.Busy=false
		if state.Worker then pcall(task.cancel,state.Worker);state.Worker=nil end
	end)
	step("chat", function()
		if configStore.ChatLog then configStore.ChatLog.RestoreNativeChat() end
	end)
	step("stat allocate", function()
		qolState.StatAllocate.CancelAllocation()
		qolState.StatAllocate.CancelMotivation()
		qolState.StatAllocate.AutoEnabled = false
		qolState.StatAllocate.PersistentAutoEnabled = false
		qolState.StatAllocate.MotivationAutoEnabled = false
		qolState.StatAllocate.MotivationBusy = false
		qolState.StatAllocate.ReleaseAutoBuildHold()
	end)
	autoTransformState.Enabled = false
	autoTransformState.CancelPending()
	qolState.FormMastery.Enabled = false
	step("ki camera", restoreKiControlCamera)
	step("auto food", function() qolState.AutoFood.SetEnabled(false) end)
	step("camera clip", function() qolState.SetCameraClipEnabled(false) end)
	step("noclip", function() qolState.SetNoclipEnabled(false) end)
	step("diagnostic", function() npcSafety.StopDirectLightDiagnostic("Hub unloaded") end)
	step("autofarm", function() setNpcTargetingEnabled(false) end)
	npcTargetingEnabled = false
	step("flight", function()
		local session = getActiveFlightSession()
		if session then
			session.speed = 40
			session.currentSpeed = math.min(tonumber(session.currentSpeed) or 15, 15)
		end
	end)
	step("esp", function()
		configStore.ESP.LeaderboardPress=nil
		configStore.ESP.StopNativeLeaderboardBindings()
		configStore.ESP.Enabled = false
		configStore.ESP.StopSpectate()
		configStore.ESP.Clear()
	end)
	step("npc esp", function()
		configStore.NpcESP.Enabled = false
		configStore.NpcESP.Clear()
	end)
	step("buu detector", function()
		configStore.BuuDetector.SetEnabled(false)
		configStore.BuuDetector.Gui:Destroy()
	end)
	step("super17 detector", function()
		configStore.Super17Detector.SetEnabled(false)
		configStore.Super17Detector.Gui:Destroy()
	end)
	step("auto clash", function()
		configStore.AutoClash.Enabled = false
		configStore.AutoClash.Recording = false
		configStore.BodyRing.SetEnabled(false)
		configStore.AutoMaze.SetEnabled(false)
		configStore.MinigameTrace.Flush()
		configStore.AutoClash.FlushLog()
	end)
	step("dragon ball esp", function()
		configStore.DragonBallESP.Enabled = false
		configStore.DragonBallESP.DisconnectWorld()
		configStore.DragonBallESP.Clear()
		configStore.DragonBallESP.Gui:Destroy()
		table.clear(configStore.DragonBallESP.Tracked)
		table.clear(configStore.DragonBallESP.AlertedBalls)
		table.clear(configStore.DragonBallESP.SuppressedBalls)
	end)
	step("session", function()
		configStore.Session.StopWatchingTarget()
		configStore.Session.Save()
	end)
	step("skill probe", configStore.SkillProbe.Cancel)
	step("skill discovery", configStore.SkillDiscovery.Cancel)
	step("remote inspector", configStore.RemoteInspector.Cleanup)
	step("remote spy", npcSafety.RemoteSpy.Uninstall)
	step("nearby alert", function()
		configStore.NearbyAlert.Enabled = false
		configStore.NearbyAlert.Gui:Destroy()
	end)
	step("movement", restoreNpcMovementState)
	step("camera shake", restoreNpcCameraShake)
	unloaded = true
	for worker in pairs(configStore.PendingStatReads) do pcall(task.cancel, worker) end
	table.clear(configStore.PendingStatReads)
	requestPending = false
	activeTrainingButton = nil

	for _, connection in ipairs(connections) do
		pcall(function()
			connection:Disconnect()
		end)
	end
	table.clear(connections)

	for _, thread in ipairs(scheduledThreads) do
		pcall(task.cancel, thread)
	end
	table.clear(scheduledThreads)

	if screenGui then
		screenGui:Destroy()
	end
	if environment[controllerKey] == controller then
		environment[controllerKey] = nil
	end
	print("[" .. HUB_DISPLAY_NAME .. "] Unloaded cleanly")
end

-- BEGIN RELOAD LOGIC
function controller.Reload()
	local state=configStore.Reload
	if unloaded or state.Busy or state.Committing then return false end
	state.Busy=true;state.Serial+=1
	local serial=state.Serial
	state.Button.Text="Downloading reload..."
	local function alive() return not unloaded and state.Serial==serial end
	local function failed(message)
		if not alive() then return end
		state.Busy=false;state.Worker=nil
		state.Button.Text="Reload failed - try again"
		warn("["..HUB_DISPLAY_NAME.."] Reload: "..tostring(message))
	end
	state.Worker=task.defer(function()
		local ok, source=pcall(function()
			if environment.GohanHubEnvironment=="local" then
				local reader=configStore.GetFunction("readfile")
				if not reader then error("readfile unavailable") end
				return reader("GohanHub_dev.lua")
			end
			local url=environment.__GohanHubLoaderUrl
			if type(url)=="string" and url:match("^https://") then return game:HttpGet(url) end
			return environment.__GohanHubSource
		end)
		if not alive() then return end
		if not ok or type(source)~="string" or source=="" then failed("Could not read hub source: "..tostring(source));return end
		if type(loadstring)~="function" then failed("loadstring unavailable");return end
		local compiled, chunk, err=pcall(loadstring,source,"AnomalysHub_reload")
		if not compiled or type(chunk)~="function" then failed(err or chunk or "compile failed");return end
		if not alive() then return end
		-- Do not include this continuation in unload's canceled workers.
		state.Worker=nil;state.Committing=true
		environment.__GohanHubSource=source
		controller.Unload()
		local ran, runtimeError=pcall(chunk)
		if not ran then warn("["..HUB_DISPLAY_NAME.."] Reload runtime error: "..tostring(runtimeError)) end
	end)
	task.delay(20,function()
		if not alive() or not state.Busy then return end
		if state.Worker then pcall(task.cancel,state.Worker);state.Worker=nil end
		failed("download timed out; existing hub kept open")
		state.Serial+=1
	end)
	return true
end
connect(configStore.Reload.Button.Activated,controller.Reload)
