controller.GetNpcProfile = function(npcType)
	local profile = npcSafety.GetProfile(npcType or selectedNpcType)
	local copy = {}
	for setting, value in pairs(profile) do
		copy[setting] = value
	end
	return copy
end
controller.SetNpcProfileValue = function(setting, value, npcType)
	if type(setting) ~= "string" or type(value) ~= "number" then
		return false
	end
	for _, definition in ipairs(npcSafety.TuningDefinitions) do
		if definition.Key == setting then
			npcSafety.GetProfile(npcType or selectedNpcType)[setting] = math.clamp(value, definition.Min, definition.Max)
			npcSafety.UpdateProfileVisual()
			return true
		end
	end
	return false
end
